INSERT INTO `agent_run` VALUES (49, 'b86ac39d6e89479589fa35bd0c66919d', 184, 166, NULL, 2, 'Agentic问答', '已完成', 5, 5, 1, 0, '{\"query\": \"设备报 ERR-5021 该怎么处理？\", \"kb_ids\": [208]}', 'ERR-5021 是点位配置与协议栈不兼容，常见于跨大版本升级固件之后。处理方式是回退到升级前的固件版本，按《固件升级与版本发布说明》先升到过渡版本再升级目标版本。', NULL, '2026-09-04 11:41:48', '2026-09-04 03:41:51', 3084, '2026-09-04 03:41:48');
INSERT INTO `agent_run` VALUES (50, '90bf1a68d6ab4557bf397c6129d79420', 184, 169, NULL, 2, 'Agentic问答', '已完成', 5, 5, 1, 0, '{\"query\": \"设备报 ERR-5021 该怎么处理？\", \"kb_ids\": [208]}', 'ERR-5021 是点位配置与协议栈不兼容，常见于跨大版本升级固件之后。处理方式是回退到升级前的固件版本，按《固件升级与版本发布说明》先升到过渡版本再升级目标版本。', NULL, '2026-09-04 11:42:58', '2026-09-04 03:43:01', 3610, '2026-09-04 03:42:58');
INSERT INTO `agent_run` VALUES (51, 'dfa6c886cad64aa8ab3c8f81756a4c53', NULL, NULL, NULL, 1, 'Agentic问答', '已完成', 5, 5, 1, 0, '{\"query\": \"你们售后退款都是怎么处理的\", \"kb_ids\": [208]}', '根据资料，售后退款处理流程如下：\n\n1. **检测环节**：我方收货后3个工作日内完成外观与功能检测（资料1、资料3）。\n\n2. **退款时限**：检测通过后5个工作日内办理退款，退款原路返回（资料1）。\n\n3. **退款责任划分**：\n   - 若因设备本身质量问题且无法维修，且在到货15日内提出退货申请并经检测确认的，货款全额退回，往返运费由公司承担（资料4）；\n   - 若为到货7日内无理由退货（未拆封、包装完好、配件齐全），客户承担往返运费，公司不收取折旧费，货款全额退回（资料4）；\n   - 若检测发现设备存在人为损坏，退货申请作废，设备寄回客户，运费由客户承担（资料1）；\n   - 若交付型号、配置与合同不符，且客户不接受更换的，可退货，全部费用由公司承担（资料2）。\n\n4. **不可退货情形**（不触发退款）包括：\n   - 超过到货15日；\n   - 设备已投入使用并产生磨损、划痕、端子变形；\n   - 封条破损、自行拆机；\n   - 定制固件或定制硬件配置的设备；\n   - 试用转采购的设备；\n   - 促销、清仓、样机特价销售的设备（资料3）。\n\n5. **退货前提**：客户须先提交退货申请，注明设备序列号、采购单号、退货原因，并附现场照片；客户服务中心2个工作日内审核并答复（资料3）。\n\n注：停产型号的备件不接受退货（资料4）。', NULL, '2026-09-05 23:01:27', '2026-09-05 15:01:37', 9782, '2026-09-05 15:01:27');
INSERT INTO `agent_run` VALUES (52, '07ce5f20bc8c4a03a97c366205892af5', NULL, NULL, NULL, 1, 'Agentic问答', '已完成', 5, 5, 1, 0, '{\"query\": \"你们售后退款是怎么处理的？\", \"kb_ids\": [208]}', '根据资料，售后退款处理流程如下：\n\n1. **检测通过后5个工作日内办理退款**，退款原路返回（资料1）。\n\n2. **退款前提条件**：\n   - 属于可退货情形（如：到货7日内未拆封无理由退货；或到货15日内确认为设备本身质量问题且无法维修等）（资料4）；\n   - 退货申请经客户服务中心审核通过（资料3）；\n   - 我方收货后3个工作日内完成外观与功能检测，且检测未发现人为损坏（资料1、资料3）；\n   - 若检测发现人为损坏，退货申请作废，不退款（资料1）。\n\n3. **运费承担规则**：\n   - 无理由退货（7日内未拆封）：客户承担往返运费（资料4）；\n   - 质量问题退货（15日内）：往返运费由公司承担（资料4）；\n   - 型号/配置不符且不接受更换的退货：全部费用由公司承担（资料2）。\n\n4. **不可退款情形**（对应不可退货情形）：\n   - 超过到货15日；\n   - 设备已投入使用并产生磨损、划痕、端子变形；\n   - 封条破损、自行拆机；\n   - 定制固件或定制硬件配置的设备；\n   - 试用转采购的设备；\n   - 促销、清仓、样机特价销售的设备（资料3）。\n\n综上，退款以检测通过为必要前提，且须符合可退货情形及流程要求。', NULL, '2026-09-05 23:08:48', '2026-09-05 15:08:57', 9257, '2026-09-05 15:08:48');
INSERT INTO `agent_run` VALUES (53, '817bd2100b2946409680c5c945091188', 184, 172, NULL, 1, 'Agentic问答', '已完成', 5, 5, 1, 0, '{\"query\": \"请问你们退款流程是什么？\", \"kb_ids\": [208]}', '根据资料，退款流程如下：\n\n1. 我方收货后 3 个工作日内完成外观与功能检测；  \n2. 检测通过后 5 个工作日内办理退款，退款原路返回。  \n\n此外，需注意：  \n- 检测发现设备存在人为损坏的，退货申请作废，设备寄回客户，运费由客户承担；  \n- 若已开具增值税专用发票，需退回发票原件（或已认证抵扣的，由客户开具红字信息表），我方收到发票原件后才办理退款。', NULL, '2026-09-05 23:11:50', '2026-09-05 15:11:54', 4117, '2026-09-05 15:11:50');
INSERT INTO `agent_run` VALUES (54, '13f76a62ed414ebc80f2602072ae8d0a', 184, 174, NULL, 1, 'Agentic问答', '已完成', 5, 5, 1, 0, '{\"query\": \"质保期多久\", \"kb_ids\": [208]}', '资料中未明确说明整机设备的质保期具体时长（如12个月、24个月等），仅规定了质保期的起算方式和配件、备件的保修期限：\n\n- 质保期以设备铭牌标注的出厂日期为准；  \n- 客户能提供有效购买凭证的，可按购买日期起算，最长顺延3个月；  \n- 电源适配器、天线、端子、导轨卡扣等配件保修期为12个月；  \n- 单独采购的备件保修6个月；  \n- 随整机维修更换的备件跟随整机剩余质保期（不足3个月按3个月计）。\n\n但整机设备本身的质保期长度（例如标准为多少个月或年）在提供的资料中未予说明。\n\n因此，答案是：知识库中未找到相关内容。', NULL, '2026-09-05 23:14:57', '2026-09-05 15:15:03', 5657, '2026-09-05 15:14:57');
INSERT INTO `agent_run` VALUES (67, '1dcc71e081964b0a837d6b3b81f85c77', 184, 215, NULL, 1, 'Agentic问答', '已完成', 5, 5, 1, 0, '{\"query\": \"请问你们的退款流程是什么样的？\", \"kb_ids\": [208]}', '根据资料，退款流程如下：\n\n1. 我方收货后 3 个工作日内完成外观与功能检测；  \n2. 检测通过后 5 个工作日内办理退款，退款原路返回。  \n\n补充说明：  \n- 若检测发现设备存在人为损坏，退货申请作废，设备寄回客户，运费由客户承担；  \n- 已开具增值税专用发票的，需退回发票原件（或已认证抵扣的，由客户开具红字信息表），我方收到发票原件后才办理退款。  \n\n以上内容均依据所提供资料整理，无额外推断。', NULL, '2026-09-05 23:49:25', '2026-09-05 15:49:30', 4520, '2026-09-05 15:49:25');
INSERT INTO `agent_run` VALUES (74, '3c489169fe0b48b88f3606dbf84f9b32', 184, 240, NULL, 1, 'Agentic问答', '已完成', 5, 5, 1, 0, '{\"query\": \"售后退款一般是怎么处理的？\", \"kb_ids\": [208]}', '根据资料，售后退款处理流程如下：\n\n1. 我方收货后 3 个工作日内完成外观与功能检测；  \n2. 检测通过后 5 个工作日内办理退款，退款原路返回。  \n\n此外，若检测发现设备存在人为损坏，退货申请作废，设备寄回客户，运费由客户承担。\n\n注：退款适用情形需符合退货政策（如到货15日内确认为设备本身质量问题且无法维修等），具体参见可退货与不可退货情形条款。', NULL, '2026-09-06 00:31:59', '2026-09-05 16:32:06', 6279, '2026-09-05 16:31:59');
