INSERT INTO `agent_run` VALUES (93, '6745bc72d043456a8f2e88b65c2b942a', 184, 293, NULL, 1, 'Agentic问答', '已完成', 5, 5, 1, 0, '{\"query\": \"你们售后退款是如何处理的？\", \"kb_ids\": [208]}', '根据资料，售后退款处理流程如下：\n\n1. 我方收货后3个工作日内完成外观与功能检测；  \n2. 检测通过后5个工作日内办理退款，退款原路返回。\n\n此外，补充说明：\n- 若检测发现设备存在人为损坏，退货申请作废，设备寄回客户，运费由客户承担；  \n- 对于因设备本身质量问题（到货15日内、经检测确认且无法维修）导致的退货，往返运费由公司承担，货款全额退回；  \n- 无理由退货（到货7日内、未拆封等条件满足）的，客户承担往返运费，公司不收取折旧费，货款全额退回。\n\n其他情形（如型号/配置不符且客户不接受更换）也支持退货，全部费用由公司承担（见资料2）。\n\n注：不可退货情形（如超15日、已使用产生磨损、封条破损、自行拆机、定制设备、试用转采购、促销/清仓/样机特价设备等）不适用退款（见资料3）。', NULL, '2026-09-06 01:41:33', '2026-09-05 17:41:41', 7888, '2026-09-05 17:41:33');
INSERT INTO `agent_run` VALUES (94, '8da5d31832054fee83bb74b6ce442bff', 184, 246, NULL, 2, 'Agentic问答', '已完成', 5, 5, 1, 0, '{\"query\": \"你们售后退款都是怎么操作的？\", \"kb_ids\": [208]}', '根据资料，售后退款操作如下：\n\n1. 我方收货后 3 个工作日内完成外观与功能检测；  \n2. 检测通过后 5 个工作日内办理退款，退款原路返回；  \n3. 若检测发现设备存在人为损坏，退货申请作废，设备寄回客户，运费由客户承担。\n\n注：退款适用情形需符合退货政策（如到货15日内确认为设备本身质量问题且无法维修等），具体参见可退货与不可退货情形规定。', NULL, '2026-09-06 01:45:40', '2026-09-05 17:45:44', 4142, '2026-09-05 17:45:40');
