INSERT INTO `chat_message` VALUES (351, 165, 'user', '病假工资怎么算？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-04 03:41:43');
INSERT INTO `chat_message` VALUES (352, 165, 'assistant', '根据《广联智造股份有限公司考勤与请假管理办法》第十条“病假”规定：\n\n- 病假须提供二级及以上医院的病假条与挂号记录；\n- 当年病假累计不超过10天的，按基本工资的80%计发；\n- 超过10天的部分，按当地最低工资标准的80%计发。', '病假工资的计算方法是什么？', '{\"id\": 3, \"name\": \"完整-混合检索加重排加改写\", \"vector_enabled\": \"是\", \"vector_top_k\": 10, \"bm25_enabled\": \"是\", \"bm25_top_k\": 10, \"rrf_k\": 60, \"rerank_enabled\": \"是\", \"rerank_model_id\": 3, \"rerank_top_n\": 4, \"query_rewrite_enabled\": \"是\", \"rewrite_type\": \"多查询扩展\", \"multi_query_count\": 3, \"parent_recall_enabled\": \"是\", \"score_threshold\": 0.3, \"metadata_filter\": null, \"is_default\": \"否\", \"remark\": \"全部能力打开，用于和前两套策略做效果对比。\", \"create_time\": \"2026-09-03 21:09:50+08:00\", \"update_time\": \"2026-09-03 21:09:50+08:00\"}', NULL, NULL, NULL, '正常回答', NULL, 4580, '2026-09-04 03:41:43');
INSERT INTO `chat_message` VALUES (353, 166, 'user', '设备报 ERR-5021 该怎么处理？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-04 03:41:48');
INSERT INTO `chat_message` VALUES (354, 166, 'assistant', 'ERR-5021 是点位配置与协议栈不兼容，常见于跨大版本升级固件之后。处理方式是回退到升级前的固件版本，按《固件升级与版本发布说明》先升到过渡版本再升级目标版本。', NULL, NULL, 49, NULL, NULL, '正常回答', NULL, 3096, '2026-09-04 03:41:48');
