INSERT INTO `chat_message` VALUES (362, 171, 'assistant', '现行制度里没有查到相关条款，请联系人力资源部确认。', '如何办理退款？', '{\"id\": 3, \"name\": \"完整-混合检索加重排加改写\", \"vector_enabled\": \"是\", \"vector_top_k\": 10, \"bm25_enabled\": \"是\", \"bm25_top_k\": 10, \"rrf_k\": 60, \"rerank_enabled\": \"是\", \"rerank_model_id\": 3, \"rerank_top_n\": 4, \"query_rewrite_enabled\": \"是\", \"rewrite_type\": \"多查询扩展\", \"multi_query_count\": 3, \"parent_recall_enabled\": \"是\", \"score_threshold\": 0.3, \"metadata_filter\": null, \"is_default\": \"否\", \"remark\": \"全部能力打开，用于和前两套策略做效果对比。\", \"create_time\": \"2026-09-03 21:09:50+08:00\", \"update_time\": \"2026-09-03 21:09:50+08:00\"}', NULL, NULL, NULL, '没有召回', NULL, 4347, '2026-09-05 15:10:59');
INSERT INTO `chat_message` VALUES (363, 172, 'user', '请问你们退款流程是什么？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-05 15:11:50');
INSERT INTO `chat_message` VALUES (364, 172, 'assistant', '根据资料，退款流程如下：\n\n1. 我方收货后 3 个工作日内完成外观与功能检测；  \n2. 检测通过后 5 个工作日内办理退款，退款原路返回。  \n\n此外，需注意：  \n- 检测发现设备存在人为损坏的，退货申请作废，设备寄回客户，运费由客户承担；  \n- 若已开具增值税专用发票，需退回发票原件（或已认证抵扣的，由客户开具红字信息表），我方收到发票原件后才办理退款。', NULL, NULL, 53, NULL, NULL, '正常回答', NULL, 4142, '2026-09-05 15:11:50');
INSERT INTO `chat_message` VALUES (365, 173, 'user', 'GTE-3000Pro 最多支持多少个采集点位？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-05 15:14:06');
