INSERT INTO `chat_message` VALUES (503, 240, 'user', '售后退款一般是怎么处理的？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-05 16:31:59');
INSERT INTO `chat_message` VALUES (504, 240, 'assistant', '根据资料，售后退款处理流程如下：\n\n1. 我方收货后 3 个工作日内完成外观与功能检测；  \n2. 检测通过后 5 个工作日内办理退款，退款原路返回。  \n\n此外，若检测发现设备存在人为损坏，退货申请作废，设备寄回客户，运费由客户承担。\n\n注：退款适用情形需符合退货政策（如到货15日内确认为设备本身质量问题且无法维修等），具体参见可退货与不可退货情形条款。', NULL, NULL, 74, NULL, NULL, '正常回答', NULL, 6299, '2026-09-05 16:31:59');
INSERT INTO `chat_message` VALUES (505, 241, 'user', '把 GTE-3000、GTE-3000S、GTE-3000Pro 三个型号的差异完整列出来，包括处理器、内存、接口、无线和点位上限。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-05 16:34:36');
INSERT INTO `chat_message` VALUES (506, 241, 'assistant', '根据资料，GTE-3000、GTE-3000S、GTE-3000Pro 三个型号的差异完整对比如下：\n\n| 项目 | GTE-3000 | GTE-3000S | GTE-3000Pro |\n|------|----------|-----------|-------------|\n| **处理器** | 四核 1.2GHz | 四核 1.2GHz | 八核 1.8GHz |\n| **内存** | 2GB | 4GB | 8GB |\n| **存储** | 8GB eMMC | 16GB eMMC | 64GB eMMC |\n| **以太网口** | 2 × 千兆 | 4 × 千兆 | 4 × 千兆 |\n| **串口** | 2 × RS485 | 4 × RS485/RS232 | 4 × RS485/RS232 |\n| **无线能力** | 无 | 4G 全网通 | 5G + Wi-Fi 6 |\n| **点位上限** | 2000 个 | 5000 个 | 20000 个 |\n| **数字量 I/O** | 未提及（资料中未说明） | 未提及（资料中未说明） | 4 路 DI（干接点输入）、2 路 DO（继电器输出，30VDC/2A） |\n| **CNC 协议支持（FOCAS）** | 不支持（资料明确仅 GTE-3000Pro 支持） | 不支持 | 支持 |\n| **边缘推理能力** | 无 | 无 | 具备本地推理能力，可运行轻量视觉检测模型 |\n\n注：  \n- 串口类型与数量依据[资料1]表格及[资料3]中“GTE-3000S 与 GTE-3000Pro 的……RS485/RS232”描述；GTE-3000 仅标注为“2 × RS485”，未提 RS232，故不列入 RS232。  \n- DI/DO 仅在[资料3]和[资料5]中明确为 GTE-3000Pro 特有，其余型号未提及，故按“未提及”处理（不推断存在）。  \n- 点位上限数据来自[资料5]：“一台 GTE-3000 最多可配置 2000 个采集点位，GTE-3000S 为 5000 个，GTE-3000Pro 为 20000 个”。  \n- FOCAS 协议支持明确限定为“仅 GTE-3000Pro 支持”（[资料4]）。  \n- 边缘推理能力描述见[资料1]末句。', '把 GTE-3000、GTE-3000S、GTE-3000Pro 三个型号的差异完整列出来，包括处理器、内存、接口、无线和点位上限。', '{\"id\": 2, \"name\": \"进阶-混合检索\", \"vector_enabled\": \"是\", \"vector_top_k\": 8, \"bm25_enabled\": \"是\", \"bm25_top_k\": 8, \"rrf_k\": 60, \"rerank_enabled\": \"否\", \"rerank_model_id\": null, \"rerank_top_n\": 3, \"query_rewrite_enabled\": \"否\", \"rewrite_type\": null, \"multi_query_count\": 3, \"parent_recall_enabled\": \"否\", \"score_threshold\": 0.3, \"metadata_filter\": null, \"is_default\": \"否\", \"remark\": \"向量加 BM25 双路召回后 RRF 融合，解决专有名词检索不到的问题。\", \"create_time\": \"2026-09-03 21:09:50+08:00\", \"update_time\": \"2026-09-03 21:09:50+08:00\"}', NULL, NULL, NULL, '正常回答', NULL, 15640, '2026-09-05 16:34:36');
