INSERT INTO `chat_message` VALUES (510, 243, 'assistant', '根据资料，GTE-3000、GTE-3000S、GTE-3000Pro 三个型号的差异完整对比如下：\n\n| 项目 | GTE-3000 | GTE-3000S | GTE-3000Pro |\n|------|----------|-----------|-------------|\n| **处理器** | 四核 1.2GHz | 四核 1.2GHz | 八核 1.8GHz |\n| **内存** | 2GB | 4GB | 8GB |\n| **存储** | 8GB eMMC | 16GB eMMC | 64GB eMMC |\n| **以太网口** | 2 × 千兆 | 4 × 千兆 | 4 × 千兆 |\n| **串口** | 2 × RS485 | 4 × RS485/RS232 | 4 × RS485/RS232 |\n| **无线** | 无 | 4G 全网通 | 5G + Wi-Fi 6 |\n| **点位上限** | 2000 个 | 5000 个 | 20000 个 |\n| **数字量 I/O** | 不支持（资料中未提及） | 不支持（资料中未提及） | 4 路 DI（干接点输入）、2 路 DO（继电器输出，触点容量 30VDC/2A） |\n\n注：  \n- GTE-3000S 与 GTE-3000Pro 支持 LAN3/LAN4 配置为交换口（级联用），GTE-3000 未说明具备该能力；  \n- GTE-3000Pro 独有 CNC 设备 FOCAS 协议支持（资料5）；  \n- GTE-3000Pro 具备本地推理能力，可运行轻量视觉检测模型（资料1）；  \n- 典型功耗（非用户要求项，但资料中明确）：GTE-3000 6.5W，GTE-3000S 9.2W，GTE-3000Pro 15.8W。', '把 GTE-3000、GTE-3000S、GTE-3000Pro 三个型号的差异完整列出来，包括处理器、内存、接口、无线和点位上限。', '{\"id\": 2, \"name\": \"进阶-混合检索\", \"vector_enabled\": \"是\", \"vector_top_k\": 8, \"bm25_enabled\": \"是\", \"bm25_top_k\": 8, \"rrf_k\": 60, \"rerank_enabled\": \"否\", \"rerank_model_id\": null, \"rerank_top_n\": 3, \"query_rewrite_enabled\": \"否\", \"rewrite_type\": null, \"multi_query_count\": 3, \"parent_recall_enabled\": \"否\", \"score_threshold\": 0.3, \"metadata_filter\": null, \"is_default\": \"否\", \"remark\": \"向量加 BM25 双路召回后 RRF 融合，解决专有名词检索不到的问题。\", \"create_time\": \"2026-09-03 21:09:50+08:00\", \"update_time\": \"2026-09-03 21:09:50+08:00\"}', NULL, NULL, NULL, '正常回答', NULL, 8614, '2026-09-05 16:38:27');
