INSERT INTO `chat_message` VALUES (560, 270, 'assistant', 'ERR-5021 是点位配置与协议栈不兼容，常见于跨大版本升级固件之后。处理方式是回退到升级前的固件版本，按《固件升级与版本发布说明》先升到过渡版本再升级目标版本。', NULL, NULL, 84, NULL, NULL, '正常回答', NULL, 4418, '2026-09-05 17:27:44');
