INSERT INTO `chat_message` VALUES (607, 293, 'user', '你们售后退款是如何处理的？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-05 17:41:33');
INSERT INTO `chat_message` VALUES (608, 293, 'assistant', '根据资料，售后退款处理流程如下：\n\n1. 我方收货后3个工作日内完成外观与功能检测；  \n2. 检测通过后5个工作日内办理退款，退款原路返回。\n\n此外，补充说明：\n- 若检测发现设备存在人为损坏，退货申请作废，设备寄回客户，运费由客户承担；  \n- 对于因设备本身质量问题（到货15日内、经检测确认且无法维修）导致的退货，往返运费由公司承担，货款全额退回；  \n- 无理由退货（到货7日内、未拆封等条件满足）的，客户承担往返运费，公司不收取折旧费，货款全额退回。\n\n其他情形（如型号/配置不符且客户不接受更换）也支持退货，全部费用由公司承担（见资料2）。\n\n注：不可退货情形（如超15日、已使用产生磨损、封条破损、自行拆机、定制设备、试用转采购、促销/清仓/样机特价设备等）不适用退款（见资料3）。', NULL, NULL, 93, NULL, NULL, '正常回答', NULL, 8221, '2026-09-05 17:41:33');
INSERT INTO `chat_message` VALUES (609, 294, 'user', '你们企业制度是啥', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-05 17:42:04');
INSERT INTO `chat_message` VALUES (610, 294, 'assistant', '现行制度里没有查到相关条款，请联系人力资源部确认。', '请问贵单位的内部制度体系是怎样的？', '{\"id\": 3, \"name\": \"完整-混合检索加重排加改写\", \"vector_enabled\": \"是\", \"vector_top_k\": 10, \"bm25_enabled\": \"是\", \"bm25_top_k\": 10, \"rrf_k\": 60, \"rerank_enabled\": \"是\", \"rerank_model_id\": 3, \"rerank_top_n\": 4, \"query_rewrite_enabled\": \"是\", \"rewrite_type\": \"多查询扩展\", \"multi_query_count\": 3, \"parent_recall_enabled\": \"是\", \"score_threshold\": 0.3, \"metadata_filter\": null, \"is_default\": \"否\", \"remark\": \"全部能力打开，用于和前两套策略做效果对比。\", \"create_time\": \"2026-09-03 21:09:50+08:00\", \"update_time\": \"2026-09-03 21:09:50+08:00\"}', NULL, NULL, NULL, '没有召回', NULL, 4278, '2026-09-05 17:42:04');
INSERT INTO `chat_message` VALUES (611, 295, 'user', '你们差旅费是如何报销的？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-05 17:42:43');
INSERT INTO `chat_message` VALUES (612, 295, 'assistant', '根据《广联智造股份有限公司差旅与费用报销管理制度》（GL-FIN-2024-004，V3.5），差旅费报销流程和要求如下：\n\n一、**前提条件**  \n- 必须遵循“先审批后支出”原则：出差前须在OA系统提交出差申请，注明事由、目的地、起止日期、同行人员、预计费用，审批通过后方可订票；紧急出差须在出发后1个工作日内补交申请（第三条）。  \n- 未经审批发生的费用，公司有权拒绝报销（第二条）。\n\n二、**报销时限**  \n- 费用发生后30日内提交报销单；跨年度费用最迟须在次年1月15日前提交，逾期不予受理（第八条）。\n\n三、**单据要求**  \n- 发票抬头须为公司全称，纳税人识别号准确；  \n- 增值税专用发票须在开票之日起360日内认证；  \n- 餐费、住宿费须附消费明细；  \n- 打车费须提供行程单（非仅支付截图）（第九条）。\n\n四、**费用标准与特殊规定**  \n- **交通工具**：按职级执行标准（见制度附表），如普通员工单程飞行超3小时或火车超6小时可申请升舱，但需分管副总批准（第五条、附表）；  \n- **住宿**：有明确每人每晚标准上限；超标准须事前申请并说明原因，事后补报的按标准上限报销，差额自理；两名同性别员工合住标准间，节省部分按每人每晚50元补贴（第六条）；  \n- **出差补贴**：每人每天发放；当日往返不足8小时不发；客户或合作方已安排餐食的，当餐补贴不予发放；客户现场连续驻场满5个工作日的，另按《员工手册》第十七条发放驻场补贴（第七条）。\n\n五、**审批与付款**  \n- 报销审批权限按制度第十条执行（原文未列明具体权限细则，故知识库中未提供）；  \n- 每月10日、25日为固定付款日；报销单须在付款日前3个工作日完成财务审核，否则顺延至下一期（第十一条）。\n\n六、**其他重要规定**  \n- 出差结束后10个工作日内须完成借款核销；前次借款未核销的，不得再次借款（第十二条）；  \n- 虚开发票、虚报费用、拆分单据规避审批的，将全额追回并按严重违纪处理（第十三条）。\n\n如需具体职级对应的标准金额（如住宿标准数值、出差补贴金额等），知识库中未提供详细数值。', '出差相关费用的报销规定和操作步骤有哪些？', '{\"id\": 3, \"name\": \"完整-混合检索加重排加改写\", \"vector_enabled\": \"是\", \"vector_top_k\": 10, \"bm25_enabled\": \"是\", \"bm25_top_k\": 10, \"rrf_k\": 60, \"rerank_enabled\": \"是\", \"rerank_model_id\": 3, \"rerank_top_n\": 4, \"query_rewrite_enabled\": \"是\", \"rewrite_type\": \"多查询扩展\", \"multi_query_count\": 3, \"parent_recall_enabled\": \"是\", \"score_threshold\": 0.3, \"metadata_filter\": null, \"is_default\": \"否\", \"remark\": \"全部能力打开，用于和前两套策略做效果对比。\", \"create_time\": \"2026-09-03 21:09:50+08:00\", \"update_time\": \"2026-09-03 21:09:50+08:00\"}', NULL, NULL, NULL, '正常回答', NULL, 13930, '2026-09-05 17:42:43');
INSERT INTO `chat_message` VALUES (613, 296, 'user', 'GTE-3000如何安装的？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-05 17:43:35');
INSERT INTO `chat_message` VALUES (614, 296, 'assistant', '根据资料，GTE-3000的安装方法如下：\n\n1. **安装方式**：支持 DIN 导轨安装和壁挂安装两种方式（见资料2）。\n\n2. **DIN 导轨安装**：  \n   - 断开现场电源，确认电源指示灯熄灭后再进行接线作业（资料1）；  \n   - 将网关卡扣对准 DIN 导轨，先挂上沿再向下扣紧，听到卡扣到位声即可（资料1）。\n\n3. **壁挂安装**：使用 M4 螺丝固定四角（资料1）。\n\n4. **电源接入**：  \n   - 使用 3 针端子（V+、V-、PE），PE 必须接柜体接地排，接地电阻不大于 4Ω（资料1）；  \n   - 供电要求为 DC 9V 至 36V，并需预留独立空开（资料1）；  \n   - 安装前需确认环境温度长期不超过 60℃，且远离变频器、大功率接触器等强干扰源（资料1）。\n\n5. **网络接入**：  \n   - LAN1 为管理口，LAN2 为业务口；网线制作完成后需用测试仪确认线序为 T568B（资料7）；  \n   - 有线接入需提前布好网线（资料1）。\n\n6. **上电与状态确认**：  \n   - 上电后观察指示灯：PWR 常亮表示供电正常，SYS 每秒闪烁一次表示系统运行正常（资料7）。\n\n注：安装前须完成三项确认（环境温度、供电、网络条件），详见资料1。', 'GTE-3000如何安装的？', '{\"id\": 2, \"name\": \"进阶-混合检索\", \"vector_enabled\": \"是\", \"vector_top_k\": 8, \"bm25_enabled\": \"是\", \"bm25_top_k\": 8, \"rrf_k\": 60, \"rerank_enabled\": \"否\", \"rerank_model_id\": null, \"rerank_top_n\": 3, \"query_rewrite_enabled\": \"否\", \"rewrite_type\": null, \"multi_query_count\": 3, \"parent_recall_enabled\": \"否\", \"score_threshold\": 0.3, \"metadata_filter\": null, \"is_default\": \"否\", \"remark\": \"向量加 BM25 双路召回后 RRF 融合，解决专有名词检索不到的问题。\", \"create_time\": \"2026-09-03 21:09:50+08:00\", \"update_time\": \"2026-09-03 21:09:50+08:00\"}', NULL, NULL, NULL, '正常回答', NULL, 6604, '2026-09-05 17:43:35');
INSERT INTO `chat_message` VALUES (615, 297, 'user', 'GTE-3000 如何安装的？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-05 17:44:30');
INSERT INTO `chat_message` VALUES (616, 297, 'assistant', '根据资料，GTE-3000 的安装方法如下（适用于 GTE-3000 / GTE-3000S / GTE-3000Pro 全系列）：\n\n1. **作业前确认**：  \n   - 安装位置环境温度长期不超过 60℃，且远离变频器、大功率接触器等强干扰源；  \n   - 现场供电为 DC 9V 至 36V，并预留独立空开；  \n   - 网络条件满足：有线接入需提前布好网线；4G/5G 接入需现场信号强度不低于 -95dBm。\n\n2. **安装方式**（支持两种）：  \n   - **DIN 导轨安装**：将网关卡扣对准 DIN 导轨，先挂上沿再向下扣紧，听到卡扣到位声即可；  \n   - **壁挂安装**：使用 M4 螺丝固定四角。\n\n3. **接线要求**：  \n   - 断开现场电源，确认电源指示灯熄灭后再进行接线；  \n   - 电源接入：3 针端子从左到右依次为 V+、V-、PE，PE 必须接柜体接地排，接地电阻不大于 4Ω；  \n   - RS485 接入：A 接 A、B 接 B，总线两端启用 120Ω 终端电阻，屏蔽层单端接地。\n\n4. **以太网接入**：  \n   - LAN1 为管理口，LAN2 为业务口；  \n   - 网线线序需为 T568B，建议用测试仪确认。\n\n5. **上电与状态确认**：  \n   - 上电后观察指示灯：PWR 常亮表示供电正常，SYS 每秒闪烁一次表示系统运行正常，COM 闪烁表示串口有数据收发。\n\n以上内容均依据资料1、资料2、资料7整理，未添加任何外部信息。', 'GTE-3000 如何安装的？', '{\"id\": 2, \"name\": \"进阶-混合检索\", \"vector_enabled\": \"是\", \"vector_top_k\": 8, \"bm25_enabled\": \"是\", \"bm25_top_k\": 8, \"rrf_k\": 60, \"rerank_enabled\": \"否\", \"rerank_model_id\": null, \"rerank_top_n\": 3, \"query_rewrite_enabled\": \"否\", \"rewrite_type\": null, \"multi_query_count\": 3, \"parent_recall_enabled\": \"否\", \"score_threshold\": 0.3, \"metadata_filter\": null, \"is_default\": \"否\", \"remark\": \"向量加 BM25 双路召回后 RRF 融合，解决专有名词检索不到的问题。\", \"create_time\": \"2026-09-03 21:09:50+08:00\", \"update_time\": \"2026-09-03 21:09:50+08:00\"}', NULL, NULL, NULL, '正常回答', NULL, 7733, '2026-09-05 17:44:30');
INSERT INTO `chat_message` VALUES (617, 298, 'user', '差旅费是如何报销的？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-05 17:44:51');
INSERT INTO `chat_message` VALUES (618, 298, 'assistant', '根据《广联智造股份有限公司差旅与费用报销管理制度》（文档编号：GL-FIN-2024-004，版本V3.5），差旅费报销流程和要求如下：\n\n1. **前提条件**：须遵循“先审批后支出”原则。出差前须在OA系统提交出差申请（注明事由、目的地、起止日期、同行人员、预计费用），审批通过后方可订票；紧急出差须出发后1个工作日内补交申请（第三条）。\n\n2. **报销时限**：费用发生后30日内提交报销单；跨年度费用最迟于次年1月15日前提交，逾期不予受理（第八条）。\n\n3. **单据要求**：\n   - 发票抬头须为公司全称，纳税人识别号准确；\n   - 增值税专用发票须在开票之日起360日内认证；\n   - 餐费、住宿费须附消费明细；\n   - 打车费须提供行程单（非仅支付截图）（第九条）。\n\n4. **住宿与补贴标准**：\n   - 住宿按职级对应标准执行（资料中未完整列出具体金额，但明确“超标准住宿需事前申请并说明原因”，事后补报的按标准上限报销，差额自理）；\n   - 两名同性别员工同行鼓励合住标准间，节省部分按每人每晚50元给予补贴（第六条）；\n   - 出差补贴按每人每天标准发放；当日往返不足8小时不发补贴；客户或合作方已安排餐食的，当餐补贴不予发放；客户现场连续驻场满5个工作日的，另按《员工手册》第十七条发放驻场补贴（第七条）。\n\n5. **付款安排**：每月10日、25日为固定付款日；报销单在付款日前3个工作日完成财务审核的，纳入本期付款，否则顺延至下一期（第十一条）。\n\n6. **借款核销**：如涉及预借款，单笔不超过预计费用的80%，出差结束后10个工作日内须完成核销；前次借款未核销的，不得再次借款（第十二条）。\n\n7. **审批权限**：依据出差天数及性质执行分级审批（如3天以内由部门负责人审批，3–7天由分管副总审批，7天以上或出境由总经理审批），报销审批权限见制度第十条（原文未展开具体内容，但明确存在分级审批机制）（第四条、第十条）。\n\n8. **违规处理**：虚开发票、虚报费用、拆分单据规避审批的，全额追回并按《员工手册》第三十条作严重违纪处理（第十三条）。\n\n综上，差旅费报销须严格履行事前审批、合规票据、及时提交、分级审核、按时核销等全流程管理要求。', '公司对差旅开支的报销规定和操作步骤有哪些？', '{\"id\": 3, \"name\": \"完整-混合检索加重排加改写\", \"vector_enabled\": \"是\", \"vector_top_k\": 10, \"bm25_enabled\": \"是\", \"bm25_top_k\": 10, \"rrf_k\": 60, \"rerank_enabled\": \"是\", \"rerank_model_id\": 3, \"rerank_top_n\": 4, \"query_rewrite_enabled\": \"是\", \"rewrite_type\": \"多查询扩展\", \"multi_query_count\": 3, \"parent_recall_enabled\": \"是\", \"score_threshold\": 0.3, \"metadata_filter\": null, \"is_default\": \"否\", \"remark\": \"全部能力打开，用于和前两套策略做效果对比。\", \"create_time\": \"2026-09-03 21:09:50+08:00\", \"update_time\": \"2026-09-03 21:09:50+08:00\"}', NULL, NULL, NULL, '正常回答', NULL, 14120, '2026-09-05 17:44:51');
INSERT INTO `chat_message` VALUES (619, 246, 'user', '你们售后退款都是怎么操作的？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-05 17:45:40');
INSERT INTO `chat_message` VALUES (620, 246, 'assistant', '根据资料，售后退款操作如下：\n\n1. 我方收货后 3 个工作日内完成外观与功能检测；  \n2. 检测通过后 5 个工作日内办理退款，退款原路返回；  \n3. 若检测发现设备存在人为损坏，退货申请作废，设备寄回客户，运费由客户承担。\n\n注：退款适用情形需符合退货政策（如到货15日内确认为设备本身质量问题且无法维修等），具体参见可退货与不可退货情形规定。', NULL, NULL, 94, NULL, NULL, '正常回答', NULL, 4468, '2026-09-05 17:45:40');
