INSERT INTO `knowledge_base` VALUES (207, '公司制度知识库', '员工手册、考勤请假、差旅报销、信息安全等公司内部管理制度，条款型文档，面向全体员工自助查询。', 2, 3, 4, 42, '正常', 1, '2026-09-04 02:10:18', '2026-09-04 10:20:11');
INSERT INTO `knowledge_base` VALUES (208, '售后服务知识库', '质保条款、常见问题解答、备件与退换货政策，面向客服坐席和客户自助问答。', 2, 2, 3, 42, '正常', 1, '2026-09-04 02:10:18', '2026-09-04 12:32:54');
INSERT INTO `knowledge_chunk` VALUES (153, 206, 125, NULL, 0, '普通块', '# GTE-3000 系列工业智能网关 产品技术手册\n\n文档编号：GL-PRD-2024-017\n版本：V3.2\n适用型号：GTE-3000、GTE-3000S、GTE-3000Pro\n发布单位：广联智造股份有限公司 产品部\n\n## 1. 产品概述\n\nGTE-3000 系列是广联智造面向离散制造和流程工业推出的工业智能网关，部署在产线设备与上层系统之间，负责协议转换、边缘计算和数据上云。设备采用无风扇铝合金外壳设计，支持 DIN 导轨安装和壁挂安装两种方式', 230, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:22:22');
INSERT INTO `knowledge_chunk` VALUES (154, 206, 125, NULL, 1, '普通块', '。\n\n系列内共三款型号，硬件平台一致，差异集中在算力、接口数量和无线能力上：\n\n| 型号 | 处理器 | 内存 | 存储 | 以太网口 | 串口 | 无线 | 典型功耗 |\n| --- | --- | --- | --- | --- | --- | --- | --- |\n| GTE-3000 | 四核 1.2GHz | 2GB | 8GB eMMC | 2 × 千兆 | 2 × RS485 | 无 | 6.5W |\n| GTE-3000S | 四核 1.2GHz | 4GB | 16GB eMMC | 4 × 千兆 | 4 × RS485/RS232 | 4G 全网通 | 9.2W |\n| GTE-3000Pro | 八核 1.8GHz | 8GB | 64GB eMMC | 4 × 千兆 | 4 × RS485/RS232 | 5G + Wi-Fi 6 | 15.8W |\n\nGTE-3000 是基础款，适合单产线小规模采集；GTE-3000S 增加了 4G 上行和更多串口，适合没有有线网络的车间；GTE-3000Pro 具备本地推理能力，可在边缘侧运行轻量视觉检测模型', 493, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:22:22');
INSERT INTO `knowledge_chunk` VALUES (155, 206, 125, NULL, 2, '普通块', '。\n\n## 2. 环境参数\n\n| 项目 | 指标 |\n| --- | --- |\n| 工作温度 | -20℃ ~ +70℃ |\n| 存储温度 | -40℃ ~ +85℃ |\n| 相对湿度 | 5% ~ 95%，无凝露 |\n| 防护等级 | IP40（配防尘套件后可达 IP54） |\n| 输入电压 | DC 9V ~ 36V，标配 24V 电源适配器 |\n| 抗震动 | 5 ~ 500Hz，2Grms |\n| 平均无故障时间 | MTBF ≥ 100000 小时 |\n\n安装现场环境温度长期高于 60℃ 时，必须加装导流风道或将设备移出高温区，否则处理器会触发降频保护，表现为采集周期变长、数据延迟增大。\n\n## 3. 接口说明\n\n### 3.1 电源接口\n\n设备左侧为 3 针凤凰端子，从左到右依次为 V+、V-、PE。PE 为保护接地，车间强电干扰较大时必须接地，否则 RS485 通信容易出现校验错误。\n\n### 3.2 以太网口\n\nLAN1 默认为管理口，出厂 IP 为 192.168.1.10，子网掩码 255.255.255.0。LAN2 默认为业务口，出厂配置为 DHCP 客户端', 499, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:22:22');
INSERT INTO `knowledge_chunk` VALUES (156, 206, 125, NULL, 3, '普通块', '。LAN2 默认为业务口，出厂配置为 DHCP 客户端。GTE-3000S 与 GTE-3000Pro 的 LAN3、LAN4 可配置为交换口，级联下游设备。\n\n管理口 IP 遗忘时，长按 RESET 按钮 10 秒以上，设备恢复出厂设置，管理口 IP 回到 192.168.1.10。恢复出厂设置会清空全部采集点位配置，操作前务必先导出配置文件。\n\n### 3.3 串口\n\nRS485 采用 2 针端子，A、B 两线。串口参数支持 1200 ~ 115200bps，默认 9600bps、8 数据位、1 停止位、无校验。同一条 485 总线上最多挂接 32 个从站，总线两端需接 120Ω 终端电阻，GTE-3000S 与 GTE-3000Pro 内置可通过拨码开关启用的终端电阻。\n\n### 3.4 数字量输入输出\n\nGTE-3000Pro 提供 4 路 DI 和 2 路 DO。DI 为干接点输入，DO 为继电器输出，触点容量 30VDC/2A。DO 常用于联动声光报警器，在采集中断或阈值越限时输出信号', 455, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:22:22');
INSERT INTO `knowledge_chunk` VALUES (157, 206, 125, NULL, 4, '普通块', '。DO 常用于联动声光报警器，在采集中断或阈值越限时输出信号。\n\n## 4. 协议支持\n\n设备南向（面向现场设备）支持的协议：\n\n- Modbus RTU / Modbus TCP\n- OPC UA Client\n- Siemens S7（S7-200 Smart / S7-1200 / S7-1500）\n- Mitsubishi MC 协议（3E 帧）\n- Omron FINS\n- 三菱 FX 系列编程口协议\n- CNC 设备的 FOCAS 协议（仅 GTE-3000Pro 支持）\n\n设备北向（面向上层系统）支持的协议：\n\n- MQTT 3.1.1 / MQTT 5.0，支持 TLS 加密和双向证书认证\n- HTTP / HTTPS 主动上报\n- OPC UA Server\n- 阿里云、华为云、AWS IoT 平台标准接入\n\n一台 GTE-3000 最多可配置 2000 个采集点位，GTE-3000S 为 5000 个，GTE-3000Pro 为 20000 个。超出点位上限后新增点位会被拒绝，Web 配置页提示\"点位数量超出当前型号上限\"', 478, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:22:22');
INSERT INTO `knowledge_chunk` VALUES (158, 206, 125, NULL, 5, '普通块', '。超出点位上限后新增点位会被拒绝，Web 配置页提示\"点位数量超出当前型号上限\"。\n\n## 5. 采集与上报机制\n\n采集任务以\"采集组\"为单位组织。一个采集组包含若干点位、一个采集周期和一个上报策略。采集周期最小 100ms，最大 3600s。上报策略有三种：\n\n**周期上报**：按固定间隔把最新值打包上报，间隔独立于采集周期配置。适合趋势类数据，例如温度、电流。\n\n**变化上报**：只有当数值变化超过设定的死区阈值时才上报。适合状态类数据，能显著降低流量。死区阈值支持绝对值和百分比两种形式。\n\n**混合上报**：变化时立即上报，同时按一个较长的心跳周期兜底上报一次，保证上层系统即使错过变化事件也能拿到最新值。生产环境推荐这一种。\n\n断网时数据进入本地缓存，GTE-3000 缓存容量为 10 万条，GTE-3000S 为 50 万条，GTE-3000Pro 为 500 万条。网络恢复后按时间顺序补传，补传速率默认限制为 200 条/秒，避免瞬间冲垮上层系统。缓存写满后按先进先出丢弃最旧的数据。\n\n## 6. 边缘计算\n\nGTE-3000Pro 支持在设备上运行边缘规则和轻量模型', 496, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:22:22');
INSERT INTO `knowledge_chunk` VALUES (159, 206, 125, NULL, 6, '普通块', '。\n\n## 6. 边缘计算\n\nGTE-3000Pro 支持在设备上运行边缘规则和轻量模型。\n\n边缘规则用类 SQL 的语法编写，例如：\n\n```text\nSELECT device_id, temperature\nFROM stream\nWHERE temperature > 85\n```\n\n命中规则后可触发三类动作：上报告警消息、置位 DO 输出、调用下游设备的写指令。\n\n模型推理支持 ONNX 格式，模型文件不超过 200MB。典型场景是产品外观缺陷的初筛，在边缘侧过滤掉明显合格的图片，只把疑似缺陷的图片上传到中心侧复检，可减少 80% 以上的上行带宽占用。\n\n## 7. Web 配置界面\n\n浏览器访问 `https://192.168.1.10`，默认账号 admin，默认密码 Gl@2024。首次登录强制修改密码，新密码不少于 10 位，且必须包含大写字母、小写字母、数字、特殊字符四类中的至少三类', 408, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:22:22');
INSERT INTO `knowledge_chunk` VALUES (160, 206, 125, NULL, 7, '普通块', '。\n\n主要功能区：\n\n- 运行监控：CPU、内存、存储占用，各采集组的实时状态\n- 设备管理：南向设备与点位的增删改查，支持 Excel 批量导入\n- 数据转发：北向连接配置与主题映射\n- 边缘规则：规则编写与调试\n- 系统维护：固件升级、配置导入导出、日志下载、时间同步\n\n配置文件导出格式为加密的 .glcfg，导入时校验型号与版本，跨型号导入会被拒绝。GTE-3000 的配置可以导入 GTE-3000S，反向不行，因为高型号的点位数可能超出低型号上限。\n\n## 8. 安全机制\n\n设备默认关闭 Telnet 和 FTP，仅开放 HTTPS 与 SSH。SSH 默认端口 22，可在系统维护页修改。\n\n支持三级用户角色：管理员可做全部操作；运维员可查看监控、下载日志、重启采集任务，不能改点位配置；访客只读。\n\n固件包由广联智造签名，设备升级时校验签名，签名不通过直接拒绝并保留原固件。升级过程约 3 ~ 5 分钟，期间采集中断，升级完成后自动重启并恢复原有配置', 434, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:22:22');
INSERT INTO `knowledge_chunk` VALUES (161, 206, 125, NULL, 8, '普通块', '。升级过程约 3 ~ 5 分钟，期间采集中断，升级完成后自动重启并恢复原有配置。\n\n## 9. 典型部署方式\n\n**单机部署**：一台 GTE-3000 接入一条产线的 PLC 与仪表，通过 LAN2 接入车间交换机，数据上报到厂级 MES。\n\n**双机热备**：两台 GTE-3000S 通过心跳线互联，主机故障时备机在 5 秒内接管，点位配置由主机自动同步给备机。热备要求两台设备型号、固件版本完全一致。\n\n**级联部署**：车间层用多台 GTE-3000 就近采集，汇聚到一台 GTE-3000Pro 做边缘计算与统一上云，减少公网连接数。\n\n## 10. 选型建议\n\n- 点位少于 500、有有线网络、无边缘计算需求：GTE-3000\n- 点位 500 ~ 3000、现场没有网线、需要 4G 上行：GTE-3000S\n- 点位超过 3000、需要边缘推理或 CNC 设备接入：GTE-3000Pro\n\n三款设备的点位配置格式完全兼容，后期从 GTE-3000 升级到 GTE-3000Pro 时，导出配置直接导入即可，无需重新录入点位。', 473, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:22:22');
INSERT INTO `knowledge_chunk` VALUES (162, 206, 126, NULL, 0, '普通块', 'GTE 系列网关 现场安装与维护作业指导书\n\n文档编号：GL-OPS-2024-009\n\n版本：V2.6\n\n适用型号：GTE-3000 / GTE-3000S / GTE-3000Pro\n\n编制部门：技术服务部\n\n1. 作业前准备\n\n现场作业前须完成三项确认：一是确认安装位置的环境温度长期不超过 60℃，且远离变频器、大功率接触器等强干扰源；二是确认现场供电为 DC 9V 至 36V，并预留独立空开；三是确认网络条件，有线接入需提前布好网线，4G/5G 接入需确认现场信号强度不低于 -95dBm。\n\n作业工具清单：\n\n2. 安装步骤\n\n1. 断开现场电源，确认电源指示灯熄灭后再进行接线作业。\n\n2. 将网关卡扣对准 DIN 导轨，先挂上沿再向下扣紧，听到卡扣到位声即可；壁挂安装时使用 M4 螺丝固定四角。\n\n3. 接入电源：3 针端子从左到右依次为 V+、V-、PE，PE 必须接柜体接地排，接地电阻不大于 4Ω。\n\n4. 接入 RS485：A 接 A、B 接 B，总线两端启用 120Ω 终端电阻，屏蔽层单端接地', 462, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:22:22');
INSERT INTO `knowledge_chunk` VALUES (163, 206, 126, NULL, 1, '普通块', '。\n\n5. 接入以太网：LAN1 为管理口，LAN2 为业务口，网线做完后用测试仪确认线序为 T568B。\n\n6. 无线型号安装天线，天线尽量伸出金属柜体，柜内安装会导致信号衰减 10dB 以上。\n\n7. 上电，观察指示灯：PWR 常亮表示供电正常，SYS 每秒闪烁一次表示系统运行正常，COM 闪烁表示串口有数据收发。\n\n3. 调试与验收\n\n笔记本网口配置为 192.168.1.100/24，浏览器访问 https://192.168.1.10 登录 Web 界面，默认账号 admin，默认密码 Gl@2024，首次登录强制修改密码。\n\n依次完成：修改管理口 IP 为现场规划地址、配置业务口网络、添加南向设备与点位、配置北向 MQTT 连接、启动采集组、在运行监控页确认各采集组状态为运行中。\n\n验收标准：\n\n4. 日常维护\n\n月度维护：检查指示灯状态、查看 Web 界面的 CPU 与内存占用是否长期高于 80%、检查存储剩余空间是否低于 20%、导出并归档运行日志。\n\n季度维护：清理设备表面与散热片积灰、复紧电源与串口端子、核对系统时间偏差是否超过 1 分钟、导出一次完整配置文件备份', 499, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:22:22');
INSERT INTO `knowledge_chunk` VALUES (164, 206, 126, NULL, 2, '普通块', '。\n\n年度维护：检查电源适配器输出电压是否衰减、评估固件版本是否需要升级、对双机热备的设备做一次主备切换演练。\n\n5. 常见故障现场处理\n\nPWR 灯不亮：先测量端子输入电压，无电压查上级空开与线路，有电压但设备不亮则更换电源适配器。\n\nSYS 灯快闪：系统异常，先断电重启；重启后仍快闪的，导出日志联系技术服务部。\n\nCOM 灯不闪：串口无数据收发，按 A/B 接反、参数不一致、从站地址错误、终端电阻缺失的顺序排查。\n\n采集组报 ERR-5021：点位配置与协议栈不兼容，多见于跨大版本升级固件之后，回退固件后按过渡版本重新升级。\n\n设备频繁重启：依次排查供电是否稳定、环境温度是否超过 60℃、边缘模型数量是否超过 3 个。\n\n6. 安全注意事项\n\n带电接线严禁进行，必须断电验电后作业。\n\n拆装主板前佩戴防静电手环，主板边缘持拿，不触碰芯片引脚。\n\n高空作业系安全带，柜顶安装使用绝缘梯。\n\n作业完成后清点工具，防止金属工具遗留在柜内造成短路', 425, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:22:22');
INSERT INTO `knowledge_chunk` VALUES (165, 206, 126, NULL, 3, '普通块', '。\n\n| 工具名称 | 规格 | 用途 |\n| --- | --- | --- |\n| 十字螺丝刀 | PH1 / PH2 | 端子紧固与外壳拆装 |\n| 万用表 | 支持直流电压 0-100V | 测量输入电压与线路压降 |\n| 网线测试仪 | RJ45 | 确认网线通断与线序 |\n| 笔记本电脑 | 带网口或 USB 转网口 | 配置管理口与调试 |\n| 信号强度检测仪 | 支持 4G/5G | 无线型号安装前的信号勘测 |\n| 防静电手环 | - | 拆装主板时防止静电击穿 |\n\n| 验收项 | 合格标准 | 检查方式 |\n| --- | --- | --- |\n| 供电电压 | 端子处实测 22V 至 26V | 万用表测量 |\n| 接地电阻 | 不大于 4Ω | 接地电阻测试仪 |\n| 串口通信 | 各从站超时率低于 1% | 通信质量面板观察 10 分钟 |\n| 点位数据 | 抽查 10 个点位与现场仪表读数一致 | 现场比对 |\n| 上云链路 | 数据转发状态为已连接，平台侧能收到数据 | 平台侧核对 |\n| 断网补传 | 拔网线 5 分钟后恢复，数据无缺口 | 查询平台', 500, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:22:22');
INSERT INTO `knowledge_chunk` VALUES (166, 206, 126, NULL, 4, '普通块', '侧能收到数据 | 平台侧核对 |\n| 断网补传 | 拔网线 5 分钟后恢复，数据无缺口 | 查询平台历史曲线 |\n| 重启恢复 | 断电重启后 90 秒内采集自动恢复 | 现场断电测试 |', 94, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:22:22');
INSERT INTO `knowledge_chunk` VALUES (167, 206, 127, NULL, 0, '普通块', '【工作表：故障代码】\n| 故障代码 | 名称 | 严重等级 | 触发条件 | 现场处理步骤 | 是否影响采集 |\n| --- | --- | --- | --- | --- | --- |\n| ERR-1001 | 输入电压过低 | 严重 | 输入电压持续低于 9V 超过 3 秒 | 测量端子实测电压，检查上级空开与线路压降，必要时更换电源适配器 | 是 |\n| ERR-1002 | 输入电压过高 | 严重 | 输入电压持续高于 36V 超过 1 秒 | 立即断电，核对电源规格，禁止使用非 24V 工业电源 | 是 |\n| ERR-1005 | 机内温度过高 | 警告 | 主板温度传感器读数超过 85℃ | 检查安装位置是否靠近热源，加装导流风道或移出高温区 | 否 |\n| ERR-2003 | eMMC 存储写入失败 | 严重 | 连续 3 次写入校验不通过 | 导出日志后返厂检测，存储芯片寿命耗尽需更换主板 | 是 |\n| ERR-2007 | 存储空间不足 | 警告 | 剩余存储空间低于 10% | 在系统维护页清理历史日志，或缩短本地缓存保留天数 | 否 |\n| ERR-301', 500, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:22:23');
INSERT INTO `knowledge_chunk` VALUES (168, 206, 127, NULL, 1, '普通块', '间低于 10% | 在系统维护页清理历史日志，或缩短本地缓存保留天数 | 否 |\n| ERR-3011 | RS485 通信超时 | 警告 | 同一从站连续 5 个采集周期无响应 | 按 A/B 接反、串口参数不一致、从站地址错误、终端电阻缺失的顺序排查 | 部分 |\n| ERR-3012 | RS485 校验错误率过高 | 警告 | 10 分钟内 CRC 校验失败率超过 5% | 检查 PE 是否接地、屏蔽层是否单端接地、总线长度是否超过 1200 米 | 部分 |\n| ERR-3020 | Modbus 从站返回异常码 | 提示 | 从站返回异常功能码 01/02/03 | 核对寄存器地址与数据类型，确认从站是否支持该功能码 | 部分 |\n| ERR-4002 | OPC UA 会话建立失败 | 警告 | 与 OPC UA Server 握手失败 | 核对端点地址、安全策略、用户名密码，检查证书是否过期 | 部分 |\n| ERR-4015 | S7 连接被拒绝 | 警告 | PLC 侧拒绝建立连接 | 确认 PLC 的机架号槽号配置，确认 PLC 允许的连接数未耗尽 | 部分 |', 499, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:22:23');
INSERT INTO `knowledge_chunk` VALUES (169, 206, 127, NULL, 2, '普通块', '侧拒绝建立连接 | 确认 PLC 的机架号槽号配置，确认 PLC 允许的连接数未耗尽 | 部分 |\n| ERR-5021 | 点位配置与协议栈不兼容 | 严重 | 加载点位配置时字段解析失败 | 多见于跨大版本升级固件之后，回退固件后按过渡版本重新升级 | 是 |\n| ERR-5022 | 点位数量超出型号上限 | 警告 | 配置点位数超过当前型号上限 | 删减点位或升级到更高型号，GTE-3000 上限 2000、GTE-3000S 为 5000、GTE-3000Pro 为 20000 | 部分 |\n| ERR-6003 | MQTT 连接鉴权失败 | 严重 | Broker 返回 CONNACK 错误码 4 或 5 | 核对用户名密码与 ClientID，确认平台侧设备未被禁用 | 否 |\n| ERR-6008 | TLS 握手失败 | 严重 | 证书校验不通过或时间不同步 | 检查证书有效期与 CA 链，核对设备系统时间偏差是否超过 5 分钟 | 否 |\n| ERR-6012 | 本地缓存写满 | 警告 | 断网期间缓存条数达到型号上限 | 尽快恢复网络，缓存写满后按先进先出丢弃', 500, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:22:23');
INSERT INTO `knowledge_chunk` VALUES (170, 206, 127, NULL, 3, '普通块', '本地缓存写满 | 警告 | 断网期间缓存条数达到型号上限 | 尽快恢复网络，缓存写满后按先进先出丢弃最旧数据 | 否 |\n| ERR-7001 | 边缘规则语法错误 | 提示 | 规则保存时语法解析失败 | 在边缘规则页面用调试功能定位错误行，确认字段名与流名称正确 | 否 |\n| ERR-7005 | 模型加载失败 | 警告 | ONNX 模型文件校验不通过或超过 200MB | 确认模型格式与算子版本，压缩或裁剪模型后重新上传 | 否 |\n| ERR-7009 | 边缘推理内存不足 | 严重 | 同时运行的模型占用内存超过阈值 | 减少同时运行的模型数量，单设备建议不超过 3 个 | 部分 |\n| ERR-8004 | 固件签名校验失败 | 严重 | 升级包签名与设备公钥不匹配 | 从官方渠道重新下载固件包，核对 SHA256 校验值 | 否 |\n| ERR-8006 | 固件型号不匹配 | 提示 | 升级包型号标识与设备型号不一致 | GTE-3000 与 GTE-3000S 固件不通用，检查包名中的型号标识 | 否 |\n| ERR-9002 | 双机热备心跳丢失 | 警告 |', 499, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:22:23');
INSERT INTO `knowledge_chunk` VALUES (171, 206, 127, NULL, 4, '普通块', '不通用，检查包名中的型号标识 | 否 |\n| ERR-9002 | 双机热备心跳丢失 | 警告 | 连续 5 秒未收到对端心跳 | 检查心跳线连通性，确认两台设备型号与固件版本完全一致 | 否 |\n| ERR-9007 | 系统时间未同步 | 提示 | NTP 同步连续失败超过 24 小时 | 确认 NTP 服务器地址可达，无外网时改用内网 NTP 或手动设置时间 | 否 |\n\n【工作表：指示灯状态】\n| 指示灯 | 状态 | 含义 | 处理建议 |\n| --- | --- | --- | --- |\n| PWR | 常亮 | 供电正常 | 无需处理 |\n| PWR | 不亮 | 无供电或电源损坏 | 测量输入电压，更换电源适配器 |\n| SYS | 每秒闪烁一次 | 系统运行正常 | 无需处理 |\n| SYS | 快速闪烁 | 系统异常 | 断电重启，仍异常则导出日志报修 |\n| SYS | 常亮不闪 | 系统启动中或已卡死 | 等待 90 秒，仍常亮则断电重启 |\n| COM | 闪烁 | 串口有数据收发 | 无需处理 |\n| COM | 不闪 | 串口无数据 | 排查接线、串口参', 500, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:22:23');
INSERT INTO `knowledge_chunk` VALUES (172, 206, 127, NULL, 5, '普通块', '烁 | 串口有数据收发 | 无需处理 |\n| COM | 不闪 | 串口无数据 | 排查接线、串口参数、从站地址 |\n| NET | 常亮 | 北向连接已建立 | 无需处理 |\n| NET | 慢闪 | 正在重连 | 检查网络与证书，查看 ERR-6003 与 ERR-6008 |\n| ALM | 常亮 | 存在未确认的严重告警 | 登录 Web 界面查看告警列表 |', 185, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:22:23');
INSERT INTO `knowledge_chunk` VALUES (173, 206, 128, NULL, 0, '普通块', '广联智造 GTE 系列固件升级与版本发布说明\n\n文档编号：GL-PRD-2024-023\n版本：V1.8\n适用型号：GTE-3000、GTE-3000S、GTE-3000Pro\n维护部门：产品部 固件组\n\n一、固件版本命名规则\n\n固件版本号形如 3.2.14-r5，四段含义如下：\n\n3   主版本号，硬件平台大改或协议栈重构时递增\n2   次版本号，新增功能时递增\n14  修订号，缺陷修复时递增\nr5  发布批次，同一修订号的重新打包，功能不变\n\n主版本号不同的固件不能直接升级，例如 2.x 升 3.x 必须先升到 2.9.20 过渡版本，再升 3.0.0，跳版升级会导致配置文件无法解析，设备启动后点位全部丢失', 309, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:22:23');
INSERT INTO `knowledge_chunk` VALUES (174, 206, 128, NULL, 1, '普通块', '。\n\n二、当前在维版本\n\n3.2.14-r5   稳定版，2024 年 9 月发布，推荐生产环境使用\n3.3.6-r2    功能版，2024 年 12 月发布，新增 5G 双卡双待和 MQTT 5.0 支持\n2.9.20-r8   维护版，仅修复严重缺陷，2025 年 12 月 31 日停止维护\n\n三、3.3.6 主要变更\n\n新增功能：\n1. MQTT 5.0 支持，可使用共享订阅和主题别名，长连接场景下报文开销降低约 15%\n2. GTE-3000S 与 GTE-3000Pro 支持 5G 双卡双待，主卡故障时 30 秒内自动切换到备卡\n3. 采集组支持导入导出为 Excel，字段包括点位名称、寄存器地址、数据类型、缩放系数\n4. Web 界面新增\"通信质量\"面板，展示各南向设备的响应耗时与超时率\n5. 边缘规则支持窗口函数，可计算 5 分钟滑动平均值\n\n缺陷修复：\n1. 修复 RS485 在 115200bps 下长时间运行偶发丢帧的问题，原因是串口驱动缓冲区在高负载下未及时清空\n2. 修复断网补传时数据顺序错乱的问题，补传队列改为严格按时间戳排序\n3. 修复配置文件导入后 DO', 500, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:22:23');
INSERT INTO `knowledge_chunk` VALUES (175, 206, 128, NULL, 2, '普通块', '2. 修复断网补传时数据顺序错乱的问题，补传队列改为严格按时间戳排序\n3. 修复配置文件导入后 DO 输出状态未复位的问题\n4. 修复 OPC UA Server 在客户端异常断开后会话未释放，累计超过 64 个后拒绝新连接的问题\n5. 修复设备时间未同步时日志时间戳为 1970 年的问题\n\n已知问题：\n1. GTE-3000Pro 在同时运行 4 个以上 ONNX 模型时内存占用偏高，建议单设备模型数不超过 3 个\n2. FOCAS 协议连接部分老款 FANUC 系统时首次握手较慢，约需 20 秒\n\n四、升级前准备\n\n1. 在 Web 界面【系统维护】→【配置管理】导出当前配置，文件名建议带日期，例如 line3-gw01-20241220.glcfg\n2. 在【系统维护】→【日志下载】导出最近 7 天日志，便于升级后对比\n3. 确认设备电源稳定，升级过程中断电会导致固件损坏，需要返厂刷机\n4. 确认当前固件版本与目标固件版本主版本号一致\n5. 通知产线相关人员，升级期间数据采集中断 3 到 5 分钟\n\n五、升级操作步骤\n\n方式一：Web 界面升级（推荐）\n\n1. 浏览器访问设备管理', 500, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:22:23');
INSERT INTO `knowledge_chunk` VALUES (176, 206, 128, NULL, 3, '普通块', '3 到 5 分钟\n\n五、升级操作步骤\n\n方式一：Web 界面升级（推荐）\n\n1. 浏览器访问设备管理口 https://192.168.1.10，用管理员账号登录\n2. 进入【系统维护】→【固件升级】\n3. 点击\"选择文件\"，上传 .glfw 固件包\n4. 系统自动校验签名和型号匹配，校验通过后\"开始升级\"按钮变为可点击\n5. 点击\"开始升级\"，页面显示进度条，此时不要关闭页面、不要断电\n6. 进度到 100% 后设备自动重启，约 60 秒后 Web 界面恢复访问\n7. 登录后在【运行监控】确认版本号已更新，各采集组状态为\"运行中\"\n\n方式二：批量升级\n\n超过 20 台设备时使用广联智造设备管理平台批量下发', 307, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:22:23');
INSERT INTO `knowledge_chunk` VALUES (177, 206, 128, NULL, 4, '普通块', '。平台按分组推送固件，支持分批灰度：先升级 10% 的设备，观察 24 小时无异常后再推送剩余设备。\n\n六、升级失败的处理\n\n现象一：上传固件包后提示\"签名校验失败\"\n原因是固件包不完整或来源不可信。重新从官方渠道下载，核对 SHA256 校验值。\n\n现象二：提示\"型号不匹配\"\nGTE-3000 与 GTE-3000S 的固件包不通用，检查包名中的型号标识。\n\n现象三：升级后设备无法访问\n先确认管理口 IP 是否变化，用直连方式访问 192.168.1.10。仍无法访问时长按 RESET 10 秒恢复出厂设置，再导入升级前导出的配置文件。\n\n现象四：升级后采集组不运行，日志报 ERR-5021\n这是点位配置与新版本协议栈不兼容，多见于 2.x 跨版本升到 3.x。回退到升级前版本，走 2.9.20 过渡版本重新升级。\n\n七、固件回退\n\n设备保留上一个版本的固件镜像，在【系统维护】→【固件升级】页面点击\"回退到上一版本\"即可，回退耗时约 2 分钟。回退只保留一个历史版本，连续升级两次后无法回退到更早的版本', 458, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:22:23');
INSERT INTO `knowledge_chunk` VALUES (178, 206, 128, NULL, 5, '普通块', '。回退只保留一个历史版本，连续升级两次后无法回退到更早的版本。\n\n回退后配置文件会自动降级适配，但新版本中新增的配置项会丢失，例如从 3.3.6 回退到 3.2.14 时，5G 双卡配置和窗口函数规则都会被清除。\n\n八、版本支持周期\n\n稳定版自发布之日起提供 24 个月的缺陷修复支持，功能版为 12 个月。停止维护的版本不再发布安全补丁，建议在停止维护前 3 个月完成升级规划。', 190, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:22:23');
INSERT INTO `knowledge_chunk` VALUES (179, 207, 129, NULL, 0, '父块', '# 广联智造股份有限公司 员工手册\n\n文档编号：GL-HR-2024-001\n版本：V4.1\n生效日期：2024 年 7 月 1 日\n解释部门：人力资源部\n\n## 第一章 总则\n\n第一条 为规范公司管理，明确员工的权利与义务，依据《中华人民共和国劳动法》《中华人民共和国劳动合同法》及相关法律法规，结合公司实际情况，制定本手册。\n\n第二条 本手册适用于与公司签订劳动合同的全体员工，包括正式员工、试用期员工。实习生、劳务派遣人员参照执行，另有约定的从其约定。\n\n第三条 员工入职时应认真阅读本手册并签署确认。本手册自生效之日起执行，此前发布的规定与本手册不一致的，以本手册为准。\n\n## 第二章 入职与试用期\n\n第四条 新员工报到时须提交以下材料：身份证原件及复印件、最高学历与学位证书、离职证明、体检报告、银行卡复印件、一寸照片两张。学历信息由人力资源部通过学信网核验。\n\n第五条 提供虚假材料的，公司有权解除劳动合同且不支付经济补偿。已入职后发现的，按严重违纪处理。\n\n第六条 试用期依据劳动合同期限确定：\n\n- 劳动合同期限 1 年以上不满 3 年的，试用期 2 个月\n- 劳动合同期限 3 年以上的，试用期 6 个月\n- 劳动合同期限 3 个月以上不满 1 年的，试用期 1 个月\n\n第七条 试用期工资为转正工资的 80%，且不低于公司所在地最低工资标准。研发岗位试用期工资为转正工资的 90%。\n\n第八条 试用期届满前 15 个工作日，员工提交转正申请，直属主管填写评估意见，部门负责人审批。评估维度包括工作产出、专业能力、协作意识、文化认同四项，任一项不合格的可延长试用期一次，延长期限不超过 1 个月，且总试用期不超过法定上限。\n\n第九条 试用期内员工离职提前 3 日以书面形式通知；正式员工离职提前 30 日以书面形式通知。\n\n## 第三章 工作时间\n\n第十条 公司实行标准工时制，每日工作 8 小时，每周工作 5 天。上班时间为 9:00 至 18:00，其中 12:00 至 13:00 为午休时间。\n\n第十一条 生产部门实行综合计算工时制，以月为周期，月度总工时不超过法定标准。具体排班由生产部制定并报人力资源部备案。\n\n第十二条 弹性工作：研发、设计、产品岗位可申请弹性上下班，上班时间在 8:30 至 10:00 之间自行选择，当日工作满 8 小时即可。核心工作时间为 10:00 至 16:00，此时段内不得擅自离岗。\n\n第十三条 加班须提前在 OA 系统提交加班申请，经直属主管审批后有效。未经审批的自愿延时工作不视为加班。加班可选择调休或按规定支付加班费，调休有效期为加班之日起 3 个月内。\n\n## 第四章 薪酬与福利\n\n第十四条 薪酬结构为：月度总收入 = 基本工资 + 岗位工资 + 绩效工资 + 补贴。基本工资与岗位工资固定发放，绩效工资按季度考核结果浮动。', 1199, NULL, NULL, NULL, '待向量化', '2026-09-04 02:18:44', '2026-09-04 02:18:44');
INSERT INTO `knowledge_chunk` VALUES (180, 207, 129, 179, 0, '子块', '# 广联智造股份有限公司 员工手册\n\n文档编号：GL-HR-2024-001\n版本：V4.1\n生效日期：2024 年 7 月 1 日\n解释部门：人力资源部\n\n## 第一章 总则\n\n第一条 为规范公司管理，明确员工的权利与义务，依据《中华人民共和国劳动法》《中华人民共和国劳动合同法》及相关法律法规，结合公司实际情况，制定本手册。\n\n第二条 本手册适用于与公司签订劳动合同的全体员工，包括正式员工、试用期员工。实习生、劳务派遣人员参照执行，另有约定的从其约定。\n\n第三条 员工入职时应认真阅读本手册并签署确认。本手册自生效之日起执行，此前发布的规定与本手册不一致的，以本手册为准。\n\n## 第二章 入职', 300, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:23:17');
