INSERT INTO `knowledge_chunk` VALUES (183, 207, 129, 179, 3, '子块', '周工作 5 天。上班时间为 9:00 至 18:00，其中 12:00 至 13:00 为午休时间。\n\n第十一条 生产部门实行综合计算工时制，以月为周期，月度总工时不超过法定标准。具体排班由生产部制定并报人力资源部备案。\n\n第十二条 弹性工作：研发、设计、产品岗位可申请弹性上下班，上班时间在 8:30 至 10:00 之间自行选择，当日工作满 8 小时即可。核心工作时间为 10:00 至 16:00，此时段内不得擅自离岗。\n\n第十三条 加班须提前在 OA 系统提交加班申请，经直属主管审批后有效。未经审批的自愿延时工作不视为加班。加班可选择调休或按规定支付加班费，调休有效期为加班之日起 3 个月', 300, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:23:17');
INSERT INTO `knowledge_chunk` VALUES (184, 207, 129, 179, 4, '子块', '选择调休或按规定支付加班费，调休有效期为加班之日起 3 个月内。\n\n## 第四章 薪酬与福利\n\n第十四条 薪酬结构为：月度总收入 = 基本工资 + 岗位工资 + 绩效工资 + 补贴。基本工资与岗位工资固定发放，绩效工资按季度考核结果浮动。', 119, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:23:17');
INSERT INTO `knowledge_chunk` VALUES (185, 207, 129, NULL, 1, '父块', '第十五条 工资发放日为每月 15 日，遇节假日提前至最近一个工作日。工资通过银行转账发放，个人所得税由公司代扣代缴。\n\n第十六条 公司按国家规定为员工缴纳养老、医疗、失业、工伤、生育五项社会保险及住房公积金，缴纳基数按上年度月平均工资核定，公积金缴存比例为 12%。\n\n第十七条 补贴项目：\n\n- 餐补：每工作日 30 元，随工资发放\n- 交通补贴：每月 200 元，外勤岗位每月 500 元\n- 通讯补贴：每月 100 元，销售与售后岗位每月 300 元\n- 高温补贴：6 月至 9 月，每月 300 元\n- 现场驻场补贴：客户现场连续驻场满 5 个工作日的，每日 150 元\n\n第十八条 年度福利包括：年度体检一次、生日礼金 500 元、结婚贺金 1000 元、生育贺金 1000 元、春节与中秋节日礼品。工龄满 3 年的员工，年度体检升级为深度套餐。\n\n第十九条 年终奖与公司年度经营情况和个人绩效挂钩，一般在次年 2 月发放。发放时已离职的员工不参与分配。\n\n## 第五章 绩效管理\n\n第二十条 公司实行季度绩效考核，考核周期为每年 1-3 月、4-6 月、7-9 月、10-12 月。\n\n第二十一条 考核等级分为 S、A、B、C、D 五级，对应的绩效系数为 1.5、1.2、1.0、0.8、0。部门内 S 级比例不超过 10%，A 级不超过 30%。\n\n第二十二条 连续两个季度考核为 C 的员工，进入为期 3 个月的绩效改进计划。改进期结束仍未达标的，公司可调岗或依法解除劳动合同。\n\n第二十三条 单季度考核为 D 的，当季绩效工资为零，并由部门负责人与人力资源部共同面谈。\n\n## 第六章 培训与发展\n\n第二十四条 新员工入职后参加为期 3 天的入职培训，内容包括公司概况、产品知识、规章制度、信息安全。培训考核不合格的补考一次。\n\n第二十五条 技术岗位每年安排不少于 40 学时的专业培训。公司承担费用的外部培训，单次费用超过 5000 元的，员工须签订培训服务期协议，服务期为 2 年。服务期内主动离职的，按未履行月份比例返还培训费用。\n\n第二十六条 员工可申请内部转岗，入职满 1 年且当前岗位绩效为 B 及以上的具备申请资格。转岗须经原部门与接收部门共同同意，转岗后重新计算 1 个月的岗位适应期。\n\n## 第七章 行为规范\n\n第二十七条 员工应遵守职业道德，不得从事与公司业务存在竞争关系的兼职，不得利用职务便利谋取私利。\n\n第二十八条 员工不得收受供应商、客户的现金、有价证券或贵重物品。因业务往来收到的礼品价值超过 500 元的，应上交行政部登记处理。\n\n第二十九条 涉密岗位员工离职时须完成保密事项交接，并遵守竞业限制协议约定。竞业限制期限最长不超过 2 年，公司按月支付补偿金。\n\n第三十条 严重违纪情形包括但不限于：泄露公司商业秘密、伪造报销单据、连续旷工 3 天', 1199, NULL, NULL, NULL, '待向量化', '2026-09-04 02:18:44', '2026-09-04 02:18:44');
INSERT INTO `knowledge_chunk` VALUES (186, 207, 129, 185, 5, '子块', '第十五条 工资发放日为每月 15 日，遇节假日提前至最近一个工作日。工资通过银行转账发放，个人所得税由公司代扣代缴。\n\n第十六条 公司按国家规定为员工缴纳养老、医疗、失业、工伤、生育五项社会保险及住房公积金，缴纳基数按上年度月平均工资核定，公积金缴存比例为 12%。\n\n第十七条 补贴项目：\n\n- 餐补：每工作日 30 元，随工资发放\n- 交通补贴：每月 200 元，外勤岗位每月 500 元\n- 通讯补贴：每月 100 元，销售与售后岗位每月 300 元\n- 高温补贴：6 月至 9 月，每月 300 元\n- 现场驻场补贴：客户现场连续驻场满 5 个工作日的，每日 150 元\n\n第十八条 年度福利', 300, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:23:17');
INSERT INTO `knowledge_chunk` VALUES (187, 207, 129, 185, 6, '子块', '场满 5 个工作日的，每日 150 元\n\n第十八条 年度福利包括：年度体检一次、生日礼金 500 元、结婚贺金 1000 元、生育贺金 1000 元、春节与中秋节日礼品。工龄满 3 年的员工，年度体检升级为深度套餐。\n\n第十九条 年终奖与公司年度经营情况和个人绩效挂钩，一般在次年 2 月发放。发放时已离职的员工不参与分配。\n\n## 第五章 绩效管理\n\n第二十条 公司实行季度绩效考核，考核周期为每年 1-3 月、4-6 月、7-9 月、10-12 月。\n\n第二十一条 考核等级分为 S、A、B、C、D 五级，对应的绩效系数为 1.5、1.2、1.0、0.8、0。部门内 S 级比例不超过 10%，A', 300, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:23:17');
INSERT INTO `knowledge_chunk` VALUES (188, 207, 129, 185, 7, '子块', '2、1.0、0.8、0。部门内 S 级比例不超过 10%，A 级不超过 30%。\n\n第二十二条 连续两个季度考核为 C 的员工，进入为期 3 个月的绩效改进计划。改进期结束仍未达标的，公司可调岗或依法解除劳动合同。\n\n第二十三条 单季度考核为 D 的，当季绩效工资为零，并由部门负责人与人力资源部共同面谈。\n\n## 第六章 培训与发展\n\n第二十四条 新员工入职后参加为期 3 天的入职培训，内容包括公司概况、产品知识、规章制度、信息安全。培训考核不合格的补考一次。\n\n第二十五条 技术岗位每年安排不少于 40 学时的专业培训。公司承担费用的外部培训，单次费用超过 5000 元的，员工须签订培训服务期', 300, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:23:17');
INSERT INTO `knowledge_chunk` VALUES (189, 207, 129, 185, 8, '子块', '外部培训，单次费用超过 5000 元的，员工须签订培训服务期协议，服务期为 2 年。服务期内主动离职的，按未履行月份比例返还培训费用。\n\n第二十六条 员工可申请内部转岗，入职满 1 年且当前岗位绩效为 B 及以上的具备申请资格。转岗须经原部门与接收部门共同同意，转岗后重新计算 1 个月的岗位适应期。\n\n## 第七章 行为规范\n\n第二十七条 员工应遵守职业道德，不得从事与公司业务存在竞争关系的兼职，不得利用职务便利谋取私利。\n\n第二十八条 员工不得收受供应商、客户的现金、有价证券或贵重物品。因业务往来收到的礼品价值超过 500 元的，应上交行政部登记处理。\n\n第二十九条 涉密岗位员工离职时须完成', 300, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:23:17');
INSERT INTO `knowledge_chunk` VALUES (190, 207, 129, 185, 9, '子块', '上交行政部登记处理。\n\n第二十九条 涉密岗位员工离职时须完成保密事项交接，并遵守竞业限制协议约定。竞业限制期限最长不超过 2 年，公司按月支付补偿金。\n\n第三十条 严重违纪情形包括但不限于：泄露公司商业秘密、伪造报销单据、连续旷工 3 天', 119, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:23:17');
INSERT INTO `knowledge_chunk` VALUES (191, 207, 129, NULL, 2, '父块', '或年累计旷工 5 天、在工作场所打架斗殴、严重失职造成重大经济损失。发生上述情形的，公司可即时解除劳动合同。\n\n## 第八章 离职管理\n\n第三十一条 员工离职须完成工作交接，交接内容包括在办事项、文档资料、办公设备、门禁卡、账号权限。交接完成并经双方签字确认后，人力资源部办理离职手续。\n\n第三十二条 公司在解除或终止劳动合同时出具离职证明，并在 15 日内为员工办理档案和社会保险关系转移手续。\n\n第三十三条 离职当月工资在下一个正常发薪日随薪资一并发放。未休完的法定年休假按日工资的 300% 折算支付。\n\n## 第九章 附则\n\n第三十四条 本手册由人力资源部负责解释和修订。修订后的版本经总经理办公会审议通过后发布，发布之日起生效。\n\n第三十五条 本手册未尽事宜，按国家法律法规及公司其他制度执行。', 352, NULL, NULL, NULL, '待向量化', '2026-09-04 02:18:44', '2026-09-04 02:18:44');
INSERT INTO `knowledge_chunk` VALUES (192, 207, 129, 191, 10, '子块', '或年累计旷工 5 天、在工作场所打架斗殴、严重失职造成重大经济损失。发生上述情形的，公司可即时解除劳动合同。\n\n## 第八章 离职管理\n\n第三十一条 员工离职须完成工作交接，交接内容包括在办事项、文档资料、办公设备、门禁卡、账号权限。交接完成并经双方签字确认后，人力资源部办理离职手续。\n\n第三十二条 公司在解除或终止劳动合同时出具离职证明，并在 15 日内为员工办理档案和社会保险关系转移手续。\n\n第三十三条 离职当月工资在下一个正常发薪日随薪资一并发放。未休完的法定年休假按日工资的 300% 折算支付。\n\n## 第九章 附则\n\n第三十四条 本手册由人力资源部负责解释和修订。修订后的版本经总经理', 300, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:23:18');
INSERT INTO `knowledge_chunk` VALUES (193, 207, 129, 191, 11, '子块', '四条 本手册由人力资源部负责解释和修订。修订后的版本经总经理办公会审议通过后发布，发布之日起生效。\n\n第三十五条 本手册未尽事宜，按国家法律法规及公司其他制度执行。', 82, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:23:18');
INSERT INTO `knowledge_chunk` VALUES (194, 207, 130, NULL, 0, '父块', '广联智造股份有限公司 差旅与费用报销管理制度\n\n文档编号：GL-FIN-2024-004\n\n版本：V3.5\n\n生效日期：2024 年 9 月 1 日\n\n归口部门：财务部\n\n第一章 总则\n\n第一条 为规范公司差旅与费用报销管理，控制成本、提高效率，制定本制度。本制度适用于公司全体员工因公出差、日常费用垫付及各类费用报销业务。\n\n第二条 报销遵循先审批后支出、实事求是、单据合规三项原则。未经审批发生的费用，公司有权拒绝报销。\n\n第二章 出差管理\n\n第三条 出差前须在 OA 系统提交出差申请，注明出差事由、目的地、起止日期、同行人员、预计费用。审批通过后方可订票。紧急出差可先行前往，但须在出发后 1 个工作日内补交申请。\n\n第四条 出差审批权限：3 天以内由部门负责人审批；3 天以上至 7 天由分管副总审批；7 天以上或出境由总经理审批。\n\n第五条 交通工具标准：\n\n单程飞行时间超过 3 小时或火车运行时间超过 6 小时的，普通员工可申请升舱，需分管副总批准。\n\n第六条 住宿标准（每人每晚，含税）：\n\n超标准住宿需事前申请并说明原因，事后补报的一律按标准上限报销，差额自理。两名同性别员工同行的，鼓励合住标准间，节省部分按每人每晚 50 元给予补贴。\n\n第七条 出差补贴（每人每天）：\n\n出差当日往返不足 8 小时的不发放补贴；客户或合作方已安排餐食的，当餐补贴不予发放。客户现场连续驻场满 5 个工作日的，另按员工手册第十七条发放驻场补贴。\n\n第三章 费用报销\n\n第八条 报销时限：费用发生后 30 日内提交报销单，跨年度费用最迟在次年 1 月 15 日前提交，逾期不予受理。\n\n第九条 单据要求：发票抬头须为公司全称，纳税人识别号准确；增值税专用发票需在开票之日起 360 日内认证；餐费、住宿费须附消费明细；打车费须提供行程单而非仅支付截图。\n\n第十条 报销审批权限：\n\n第十一条 付款周期：每月 10 日、25 日为固定付款日。报销单在付款日前 3 个工作日完成财务审核的，纳入本期付款，否则顺延至下一期。\n\n第十二条 借款管理：单笔预借款不超过预计费用的 80%，出差结束后 10 个工作日内核销。前次借款未核销的，不得再次借款。\n\n第四章 违规处理\n\n第十三条 虚开发票、虚报费用、拆分单据规避审批的，全额追回并按员工手册第三十条按严重违纪处理。\n\n第十四条 财务部每季度抽查报销单据，抽查比例不低于 10%，抽查结果报总经理。\n\n第五章 附则\n\n第十五条 本制度由财务部负责解释，自生效之日起施行。\n\n| 职级 | 飞机 | 火车 | 市内交通 |\n| --- | --- | --- | --- |\n| 总经理及以上 | 公务舱 | 商务座 | 实报实销 |\n| 总监 / 分管副总 | 经济舱 | 一等座 | 实报实销 |\n| 经理 / 主管 | 经济舱 | 二等座 | 每', 1200, NULL, NULL, NULL, '待向量化', '2026-09-04 02:18:44', '2026-09-04 02:18:44');
INSERT INTO `knowledge_chunk` VALUES (195, 207, 130, 194, 0, '子块', '广联智造股份有限公司 差旅与费用报销管理制度\n\n文档编号：GL-FIN-2024-004\n\n版本：V3.5\n\n生效日期：2024 年 9 月 1 日\n\n归口部门：财务部\n\n第一章 总则\n\n第一条 为规范公司差旅与费用报销管理，控制成本、提高效率，制定本制度。本制度适用于公司全体员工因公出差、日常费用垫付及各类费用报销业务。\n\n第二条 报销遵循先审批后支出、实事求是、单据合规三项原则。未经审批发生的费用，公司有权拒绝报销。\n\n第二章 出差管理\n\n第三条 出差前须在 OA 系统提交出差申请，注明出差事由、目的地、起止日期、同行人员、预计费用。审批通过后方可订票。紧急出差可先行前往，但须在出发后 1', 300, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:22:24');
INSERT INTO `knowledge_chunk` VALUES (196, 207, 130, 194, 1, '子块', '用。审批通过后方可订票。紧急出差可先行前往，但须在出发后 1 个工作日内补交申请。\n\n第四条 出差审批权限：3 天以内由部门负责人审批；3 天以上至 7 天由分管副总审批；7 天以上或出境由总经理审批。\n\n第五条 交通工具标准：\n\n单程飞行时间超过 3 小时或火车运行时间超过 6 小时的，普通员工可申请升舱，需分管副总批准。\n\n第六条 住宿标准（每人每晚，含税）：\n\n超标准住宿需事前申请并说明原因，事后补报的一律按标准上限报销，差额自理。两名同性别员工同行的，鼓励合住标准间，节省部分按每人每晚 50 元给予补贴。\n\n第七条 出差补贴（每人每天）：\n\n出差当日往返不足 8 小时的不发放补贴；客户', 300, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:22:24');
INSERT INTO `knowledge_chunk` VALUES (197, 207, 130, 194, 2, '子块', '每人每天）：\n\n出差当日往返不足 8 小时的不发放补贴；客户或合作方已安排餐食的，当餐补贴不予发放。客户现场连续驻场满 5 个工作日的，另按员工手册第十七条发放驻场补贴。\n\n第三章 费用报销\n\n第八条 报销时限：费用发生后 30 日内提交报销单，跨年度费用最迟在次年 1 月 15 日前提交，逾期不予受理。\n\n第九条 单据要求：发票抬头须为公司全称，纳税人识别号准确；增值税专用发票需在开票之日起 360 日内认证；餐费、住宿费须附消费明细；打车费须提供行程单而非仅支付截图。\n\n第十条 报销审批权限：\n\n第十一条 付款周期：每月 10 日、25 日为固定付款日。报销单在付款日前 3 个工作日完成财', 300, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:22:24');
INSERT INTO `knowledge_chunk` VALUES (198, 207, 130, 194, 3, '子块', '、25 日为固定付款日。报销单在付款日前 3 个工作日完成财务审核的，纳入本期付款，否则顺延至下一期。\n\n第十二条 借款管理：单笔预借款不超过预计费用的 80%，出差结束后 10 个工作日内核销。前次借款未核销的，不得再次借款。\n\n第四章 违规处理\n\n第十三条 虚开发票、虚报费用、拆分单据规避审批的，全额追回并按员工手册第三十条按严重违纪处理。\n\n第十四条 财务部每季度抽查报销单据，抽查比例不低于 10%，抽查结果报总经理。\n\n第五章 附则\n\n第十五条 本制度由财务部负责解释，自生效之日起施行。\n\n| 职级 | 飞机 | 火车 | 市内交通 |\n| --- | --- | --- | ---', 299, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:22:24');
INSERT INTO `knowledge_chunk` VALUES (199, 207, 130, 194, 4, '子块', '内交通 |\n| --- | --- | --- | --- |\n| 总经理及以上 | 公务舱 | 商务座 | 实报实销 |\n| 总监 / 分管副总 | 经济舱 | 一等座 | 实报实销 |\n| 经理 / 主管 | 经济舱 | 二等座 | 每', 120, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:22:24');
