INSERT INTO `knowledge_chunk` VALUES (214, 207, 131, 209, 9, '子块', '表，发送至各部门负责人确认。\n\n第二十六条 员工对考勤记录有异议的，在收到报表后 2 个工作日内向人力资源部提出申诉，并提供门禁记录、工作邮件、系统操作日志等佐证材料。逾期未申诉的视为认可。\n\n第二十七条 考勤结果作为绩效考核、年终奖发放', 119, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:23:19');
INSERT INTO `knowledge_chunk` VALUES (215, 207, 131, NULL, 2, '父块', '、评优评先的依据之一。\n\n第六章 附则\n\n第二十八条 本办法由人力资源部负责解释，与员工手册不一致的以本办法为准。\n\n第二十九条 本办法自发布之日起施行，原《考勤管理规定》（GL-HR-2022-006）同时废止。', 107, NULL, NULL, NULL, '待向量化', '2026-09-04 02:18:44', '2026-09-04 02:18:44');
