INSERT INTO `knowledge_chunk` VALUES (217, 207, 132, NULL, 0, '父块', '# 广联智造股份有限公司 信息安全与数据保护管理规范\n\n文档编号：GL-SEC-2024-003\n版本：V2.8\n生效日期：2024 年 11 月 1 日\n归口部门：信息技术部\n\n## 第一章 总则\n\n第一条 为保护公司信息资产与客户数据安全，防范信息泄露、篡改、丢失，依据《中华人民共和国网络安全法》《中华人民共和国数据安全法》《中华人民共和国个人信息保护法》，结合公司实际，制定本规范。\n\n第二条 本规范适用于公司全体员工、实习生、外包人员，以及因业务需要接触公司信息系统的第三方人员。\n\n第三条 信息安全实行\"谁主管谁负责、谁使用谁负责\"的原则。信息技术部负责技术措施与日常监督，各部门负责人为本部门信息安全第一责任人。\n\n## 第二章 信息资产分级\n\n第四条 公司信息资产按敏感程度分为四级：\n\n**绝密**：核心源代码、固件签名私钥、未公开的产品设计图纸、并购与融资材料。仅限授权名单内人员访问，访问全程留痕。\n\n**机密**：客户名单与联系方式、合同与报价、员工薪酬数据、生产工艺参数、客户现场的点位配置文件。按岗位授权访问。\n\n**内部**：内部管理制度、会议纪要、项目周报、培训材料。全体员工可访问，不得对外传播。\n\n**公开**：产品彩页、公开发布的技术手册、官网内容、新闻稿。无访问限制。\n\n第五条 文件创建者负责标注密级。未标注的默认按\"内部\"处理。密级需要变更的，由原创建者提出，部门负责人审批。\n\n## 第三章 账号与权限\n\n第六条 员工入职时由信息技术部按岗位开通账号，包括域账号、OA、邮箱、代码仓库、生产系统等。账号遵循最小权限原则，只开通履行岗位职责所必需的权限。\n\n第七条 账号实行实名制，严禁共用账号、出借账号。因共用账号造成的安全事件，由账号所有人承担责任。\n\n第八条 密码要求：长度不少于 12 位，包含大写字母、小写字母、数字、特殊字符四类中的至少三类，不得使用姓名、生日、工号、连续字符。密码每 90 天强制更换，新密码不得与前 5 次重复。\n\n第九条 涉及绝密与机密资产的系统必须启用双因素认证。远程访问公司内网必须通过 VPN，且 VPN 强制双因素认证。\n\n第十条 权限变更：员工转岗后 3 个工作日内由原部门提交权限回收申请；离职当日冻结全部账号，30 日后删除。信息技术部每季度做一次权限复核，清理僵尸账号与超范围权限。\n\n## 第四章 终端与网络安全\n\n第十一条 办公终端必须安装公司统一的终端管理软件与杀毒软件，禁止卸载或停用。系统补丁在发布后 30 日内完成安装，高危漏洞补丁在 7 日内完成。\n\n第十二条 终端必须启用磁盘加密与屏幕锁，锁屏时间不超过 10 分钟。笔记本电脑离开办公区时须随身携带，不得放置在车内或无人看管处。\n\n第十三条 未经批准，禁止在办公终端安装破解软件、来源不明的工具、远程控制软件。研发调试确需使用的，向信息技', 1200, NULL, NULL, NULL, '待向量化', '2026-09-04 02:18:44', '2026-09-04 02:18:44');
INSERT INTO `knowledge_chunk` VALUES (218, 207, 132, 217, 0, '子块', '# 广联智造股份有限公司 信息安全与数据保护管理规范\n\n文档编号：GL-SEC-2024-003\n版本：V2.8\n生效日期：2024 年 11 月 1 日\n归口部门：信息技术部\n\n## 第一章 总则\n\n第一条 为保护公司信息资产与客户数据安全，防范信息泄露、篡改、丢失，依据《中华人民共和国网络安全法》《中华人民共和国数据安全法》《中华人民共和国个人信息保护法》，结合公司实际，制定本规范。\n\n第二条 本规范适用于公司全体员工、实习生、外包人员，以及因业务需要接触公司信息系统的第三方人员。\n\n第三条 信息安全实行\"谁主管谁负责、谁使用谁负责\"的原则。信息技术部负责技术措施与日常监督，各部门负责人为', 300, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:23:20');
INSERT INTO `knowledge_chunk` VALUES (219, 207, 132, 217, 1, '子块', '责\"的原则。信息技术部负责技术措施与日常监督，各部门负责人为本部门信息安全第一责任人。\n\n## 第二章 信息资产分级\n\n第四条 公司信息资产按敏感程度分为四级：\n\n**绝密**：核心源代码、固件签名私钥、未公开的产品设计图纸、并购与融资材料。仅限授权名单内人员访问，访问全程留痕。\n\n**机密**：客户名单与联系方式、合同与报价、员工薪酬数据、生产工艺参数、客户现场的点位配置文件。按岗位授权访问。\n\n**内部**：内部管理制度、会议纪要、项目周报、培训材料。全体员工可访问，不得对外传播。\n\n**公开**：产品彩页、公开发布的技术手册、官网内容、新闻稿。无访问限制。\n\n第五条 文件创建者负责标注密', 300, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:23:20');
INSERT INTO `knowledge_chunk` VALUES (220, 207, 132, 217, 2, '子块', '网内容、新闻稿。无访问限制。\n\n第五条 文件创建者负责标注密级。未标注的默认按\"内部\"处理。密级需要变更的，由原创建者提出，部门负责人审批。\n\n## 第三章 账号与权限\n\n第六条 员工入职时由信息技术部按岗位开通账号，包括域账号、OA、邮箱、代码仓库、生产系统等。账号遵循最小权限原则，只开通履行岗位职责所必需的权限。\n\n第七条 账号实行实名制，严禁共用账号、出借账号。因共用账号造成的安全事件，由账号所有人承担责任。\n\n第八条 密码要求：长度不少于 12 位，包含大写字母、小写字母、数字、特殊字符四类中的至少三类，不得使用姓名、生日、工号、连续字符。密码每 90 天强制更换，新密码不得与前 5', 299, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:23:20');
INSERT INTO `knowledge_chunk` VALUES (221, 207, 132, 217, 3, '子块', '号、连续字符。密码每 90 天强制更换，新密码不得与前 5 次重复。\n\n第九条 涉及绝密与机密资产的系统必须启用双因素认证。远程访问公司内网必须通过 VPN，且 VPN 强制双因素认证。\n\n第十条 权限变更：员工转岗后 3 个工作日内由原部门提交权限回收申请；离职当日冻结全部账号，30 日后删除。信息技术部每季度做一次权限复核，清理僵尸账号与超范围权限。\n\n## 第四章 终端与网络安全\n\n第十一条 办公终端必须安装公司统一的终端管理软件与杀毒软件，禁止卸载或停用。系统补丁在发布后 30 日内完成安装，高危漏洞补丁在 7 日内完成。\n\n第十二条 终端必须启用磁盘加密与屏幕锁，锁屏时间不超过 10', 300, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:23:20');
INSERT INTO `knowledge_chunk` VALUES (222, 207, 132, 217, 4, '子块', '第十二条 终端必须启用磁盘加密与屏幕锁，锁屏时间不超过 10 分钟。笔记本电脑离开办公区时须随身携带，不得放置在车内或无人看管处。\n\n第十三条 未经批准，禁止在办公终端安装破解软件、来源不明的工具、远程控制软件。研发调试确需使用的，向信息技', 120, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:23:20');
INSERT INTO `knowledge_chunk` VALUES (223, 207, 132, NULL, 1, '父块', '术部申请白名单。\n\n第十四条 USB 存储设备默认禁用。确需使用的，申请开通并使用公司统一发放的加密 U 盘，加密 U 盘丢失须在 24 小时内报告。\n\n第十五条 办公网、生产网、访客网物理或逻辑隔离。访客 Wi-Fi 仅提供互联网访问，不能访问任何内部系统。生产网设备不得直接接入互联网，需要外网访问时经堡垒机或工业防火墙代理。\n\n## 第五章 数据保护\n\n第十六条 客户数据的收集遵循最小必要原则，只收集业务必需的字段，收集前告知用途并取得授权。\n\n第十七条 客户现场的点位配置文件、运行日志属于机密资产，导出后须存放在公司指定的加密存储空间，禁止存放在个人网盘、个人邮箱、微信文件传输助手。\n\n第十八条 数据传输：机密及以上级别的数据对外传输必须加密。邮件发送时使用加密压缩包，密码通过另一渠道告知接收方。禁止使用未经审批的第三方文件传输工具。\n\n第十九条 数据备份：核心业务系统每日增量备份、每周全量备份，备份数据异地保存，保留期不少于 6 个月。信息技术部每半年做一次恢复演练，验证备份可用性。\n\n第二十条 数据销毁：存储介质报废前须做物理销毁或不可恢复的擦除，由信息技术部统一执行并登记。纸质机密文件使用碎纸机销毁，不得直接投入垃圾桶。\n\n第二十一条 个人信息处理遵循《个人信息保护法》，涉及员工与客户个人信息的系统，须记录处理日志并保存不少于 3 年。\n\n## 第六章 开发安全\n\n第二十二条 源代码统一存放在公司代码仓库，禁止上传到 GitHub、Gitee 等公共平台。开源组件引入前须做许可证合规审查，禁止在闭源产品中使用 GPL 类传染性协议的组件。\n\n第二十三条 代码中禁止硬编码密码、密钥、令牌。敏感配置通过配置中心或环境变量注入，配置中心的访问受权限控制并全程审计。\n\n第二十四条 固件签名私钥保存在硬件加密机中，签名操作需两名授权人共同发起。私钥不得导出、不得复制到任何终端。\n\n第二十五条 版本发布前须完成安全测试，包括依赖组件漏洞扫描、静态代码扫描、接口越权测试。高危问题未修复的不得发布。\n\n第二十六条 生产环境数据禁止直接用于开发与测试。确需使用的，先做脱敏处理，脱敏方案由信息技术部审核。\n\n## 第七章 第三方管理\n\n第二十七条 与第三方合作前签署保密协议，明确数据使用范围、保存期限、销毁要求与违约责任。\n\n第二十八条 外包人员账号单独标识，权限仅限项目范围，合同结束后立即回收。外包人员不得接触绝密级资产。\n\n第二十九条 第三方接入公司网络的设备须先经信息技术部安全检查，检查项包括补丁状态、杀毒软件、是否存在恶意程序。\n\n## 第八章 安全事件处置\n\n第三十条 发现以下情形应在 1 小时内报告信息技术部：账号异常登录、终端感染病毒或勒索软件、机密文件外泄、设备或存储介质丢失、收到可疑钓鱼邮件并已点击。\n\n第三十一条 安全事件处置流程：报告 → 隔离', 1200, NULL, NULL, NULL, '待向量化', '2026-09-04 02:18:44', '2026-09-04 02:18:44');
INSERT INTO `knowledge_chunk` VALUES (224, 207, 132, 223, 5, '子块', '术部申请白名单。\n\n第十四条 USB 存储设备默认禁用。确需使用的，申请开通并使用公司统一发放的加密 U 盘，加密 U 盘丢失须在 24 小时内报告。\n\n第十五条 办公网、生产网、访客网物理或逻辑隔离。访客 Wi-Fi 仅提供互联网访问，不能访问任何内部系统。生产网设备不得直接接入互联网，需要外网访问时经堡垒机或工业防火墙代理。\n\n## 第五章 数据保护\n\n第十六条 客户数据的收集遵循最小必要原则，只收集业务必需的字段，收集前告知用途并取得授权。\n\n第十七条 客户现场的点位配置文件、运行日志属于机密资产，导出后须存放在公司指定的加密存储空间，禁止存放在个人网盘、个人邮箱、微信文件传输助手。', 298, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:23:20');
INSERT INTO `knowledge_chunk` VALUES (225, 207, 132, 223, 6, '子块', '储空间，禁止存放在个人网盘、个人邮箱、微信文件传输助手。\n\n第十八条 数据传输：机密及以上级别的数据对外传输必须加密。邮件发送时使用加密压缩包，密码通过另一渠道告知接收方。禁止使用未经审批的第三方文件传输工具。\n\n第十九条 数据备份：核心业务系统每日增量备份、每周全量备份，备份数据异地保存，保留期不少于 6 个月。信息技术部每半年做一次恢复演练，验证备份可用性。\n\n第二十条 数据销毁：存储介质报废前须做物理销毁或不可恢复的擦除，由信息技术部统一执行并登记。纸质机密文件使用碎纸机销毁，不得直接投入垃圾桶。\n\n第二十一条 个人信息处理遵循《个人信息保护法》，涉及员工与客户个人信息的系统，须记录处理', 300, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:23:20');
INSERT INTO `knowledge_chunk` VALUES (226, 207, 132, 223, 7, '子块', '《个人信息保护法》，涉及员工与客户个人信息的系统，须记录处理日志并保存不少于 3 年。\n\n## 第六章 开发安全\n\n第二十二条 源代码统一存放在公司代码仓库，禁止上传到 GitHub、Gitee 等公共平台。开源组件引入前须做许可证合规审查，禁止在闭源产品中使用 GPL 类传染性协议的组件。\n\n第二十三条 代码中禁止硬编码密码、密钥、令牌。敏感配置通过配置中心或环境变量注入，配置中心的访问受权限控制并全程审计。\n\n第二十四条 固件签名私钥保存在硬件加密机中，签名操作需两名授权人共同发起。私钥不得导出、不得复制到任何终端。\n\n第二十五条 版本发布前须完成安全测试，包括依赖组件漏洞扫描、静态代码扫', 300, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:23:20');
INSERT INTO `knowledge_chunk` VALUES (227, 207, 132, 223, 8, '子块', '版本发布前须完成安全测试，包括依赖组件漏洞扫描、静态代码扫描、接口越权测试。高危问题未修复的不得发布。\n\n第二十六条 生产环境数据禁止直接用于开发与测试。确需使用的，先做脱敏处理，脱敏方案由信息技术部审核。\n\n## 第七章 第三方管理\n\n第二十七条 与第三方合作前签署保密协议，明确数据使用范围、保存期限、销毁要求与违约责任。\n\n第二十八条 外包人员账号单独标识，权限仅限项目范围，合同结束后立即回收。外包人员不得接触绝密级资产。\n\n第二十九条 第三方接入公司网络的设备须先经信息技术部安全检查，检查项包括补丁状态、杀毒软件、是否存在恶意程序。\n\n## 第八章 安全事件处置\n\n第三十条 发现以下情', 299, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:23:20');
INSERT INTO `knowledge_chunk` VALUES (228, 207, 132, 223, 9, '子块', '程序。\n\n## 第八章 安全事件处置\n\n第三十条 发现以下情形应在 1 小时内报告信息技术部：账号异常登录、终端感染病毒或勒索软件、机密文件外泄、设备或存储介质丢失、收到可疑钓鱼邮件并已点击。\n\n第三十一条 安全事件处置流程：报告 → 隔离', 120, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:23:20');
INSERT INTO `knowledge_chunk` VALUES (229, 207, 132, NULL, 2, '父块', '受影响系统 → 评估影响范围 → 处置与恢复 → 复盘并输出改进措施。重大事件由信息技术部报总经理，并按法规要求在规定时限内向监管部门报告。\n\n第三十二条 隐瞒不报或延迟报告导致损失扩大的，按员工手册第三十条从严处理。\n\n## 第九章 培训与考核\n\n第三十三条 新员工入职培训包含信息安全模块，考核不通过的不予转正。全体员工每年参加一次信息安全复训，复训包含钓鱼邮件演练。\n\n第三十四条 信息技术部每半年组织一次全员钓鱼邮件演练，点击率纳入部门管理考核。同一员工连续两次中招的，安排专项辅导。\n\n## 第十章 附则\n\n第三十五条 本规范由信息技术部负责解释，与国家法律法规冲突的，以法律法规为准。\n\n第三十六条 本规范自生效之日起施行，原《信息安全管理办法》（GL-SEC-2022-003）同时废止。', 351, NULL, NULL, NULL, '待向量化', '2026-09-04 02:18:44', '2026-09-04 02:18:44');
INSERT INTO `knowledge_chunk` VALUES (230, 207, 132, 229, 10, '子块', '受影响系统 → 评估影响范围 → 处置与恢复 → 复盘并输出改进措施。重大事件由信息技术部报总经理，并按法规要求在规定时限内向监管部门报告。\n\n第三十二条 隐瞒不报或延迟报告导致损失扩大的，按员工手册第三十条从严处理。\n\n## 第九章 培训与考核\n\n第三十三条 新员工入职培训包含信息安全模块，考核不通过的不予转正。全体员工每年参加一次信息安全复训，复训包含钓鱼邮件演练。\n\n第三十四条 信息技术部每半年组织一次全员钓鱼邮件演练，点击率纳入部门管理考核。同一员工连续两次中招的，安排专项辅导。\n\n## 第十章 附则\n\n第三十五条 本规范由信息技术部负责解释，与国家法律法规冲突的，以法律法规为准。', 298, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:23:20');
INSERT INTO `knowledge_chunk` VALUES (231, 207, 132, 229, 11, '子块', '息技术部负责解释，与国家法律法规冲突的，以法律法规为准。\n\n第三十六条 本规范自生效之日起施行，原《信息安全管理办法》（GL-SEC-2022-003）同时废止。', 81, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:23:20');
INSERT INTO `knowledge_chunk` VALUES (232, 208, 133, NULL, 0, '普通块', '【第 1 页】\n广联智造股份有限公司\n售后服务政策与质量保证条款\n文档编号：GL-SVC-2024-002\n版本：V4.2\n生效日期：2024 年 8 月 1 日\n归口部门：客户服务中心\n第一条 适用范围\n本条款适用于客户向广联智造股份有限公司采购的 GTE 系列工业智能\n网关及其配件。销售合同中另有约定的，以合同约定为准；合同未约\n定的事项，按本条款执行。\n第二条 质量保证期\n一、GTE-3000、GTE-3000S、GTE-3000Pro 整机质量保证期为自出厂\n之日起 24 个月', 245, 1, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:22:26');
INSERT INTO `knowledge_chunk` VALUES (233, 208, 133, NULL, 1, '普通块', '。质保期以设备铭牌标注的出厂日期为准。\n二、客户能提供有效购买凭证的，可按购买日期起算，最长顺延 3 个\n月。\n三、电源适配器、天线、端子、导轨卡扣等配件的保修期为 12 个月。\n四、单独采购的备件自签收之日起保修 6 个月；随整机维修更换的备\n件跟随整机剩余质保期，剩余不足 3 个月的按 3 个月计。\n五、质保期内经两次维修仍未解决同一故障的，客户可申请换货，换\n新设备的质保期按原设备剩余质保期计算，剩余不足 3 个月的按 3 个\n月计', 221, 1, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:22:26');
INSERT INTO `knowledge_chunk` VALUES (234, 208, 133, NULL, 2, '普通块', '。\n第三条 免费保修范围\n质保期内，因设计、材料、制造工艺缺陷导致的功能性故障，公司提\n供免费维修或更换，包括但不限于：主板元器件失效、接口虚焊、电\n源模块异常、无线模组不识别、存储芯片写入失败。\n第四条 不属于免费保修的情形\n一、超出质量保证期。\n二、未按产品手册要求使用，例如输入电压超出 DC 9V 至 36V 范围、\n\n【第 2 页】\n环境温度长期超过 70℃、未做接地导致的通信板损坏。\n三、客户自行拆机、改装，或设备封条破损。\n四、水浸、火灾、雷击、地震、电涌等不可抗力造成的损坏', 246, 2, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:22:26');
INSERT INTO `knowledge_chunk` VALUES (235, 208, 133, NULL, 3, '普通块', '。\n四、水浸、火灾、雷击、地震、电涌等不可抗力造成的损坏。\n五、外壳明显机械性损伤，例如摔落导致的结构变形。\n六、使用非广联智造发布的固件，或安装未经授权的第三方软件导致\n的故障。\n七、正常使用产生的外观磨损、丝印褪色，不影响功能的，不在保修\n范围也不影响其他部件的保修。\n第五条 服务响应时效\n一、服务热线 400-820-9600，工作日 8:30 至 20:30，节假日 9:00\n至 18:00。\n二、远程支持：接到报修后 2 小时内响应，通过电话、远程桌面或日\n志分析协助排查', 243, 2, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:22:26');
INSERT INTO `knowledge_chunk` VALUES (236, 208, 133, NULL, 4, '普通块', '。\n三、寄修服务：我方收到设备起 5 个工作日内完成检测与维修并寄\n回。质保期内往返运费由公司承担；质保期外，客户承担寄出运费，\n公司承担寄回运费。\n四、上门服务：适用于购买上门服务包的客户，或单笔采购 50 台以\n上的项目客户。省会城市 24 小时内到达现场，其他地级市 48 小时内\n到达，偏远地区双方另行约定。\n第六条 备机借用\n签订年度服务协议的客户，在设备返修期间可申请备机借用，借用期\n最长 15 天。备机为同型号或更高型号，配置由我方工程师协助导入', 231, 2, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:22:26');
INSERT INTO `knowledge_chunk` VALUES (237, 208, 133, NULL, 5, '普通块', '。备机为同型号或更高型号，配置由我方工程师协助导入。\n逾期未归还的，按设备原价的 1% 每日收取占用费。\n第七条 有偿维修\n一、不属于免费保修范围的故障，按实际更换的物料成本加人工费计\n收，维修前提供报价单，客户确认后实施。\n二、有偿维修的部件自维修完成之日起保修 3 个月。\n\n【第 3 页】\n三、检测后确认无故障的，收取检测费 200 元；客户放弃维修的，设\n备原样寄回，运费由客户承担。\n第八条 技术支持内容\n一、产品选型建议、点位规划建议', 223, 3, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:22:26');
INSERT INTO `knowledge_chunk` VALUES (238, 208, 133, NULL, 6, '普通块', '。\n第八条 技术支持内容\n一、产品选型建议、点位规划建议。\n二、首次部署的远程指导，含管理口配置、南向设备接入、北向平台\n对接。\n三、固件升级方案制定与升级过程陪同。\n四、二次开发接口文档与示例代码，接口包括 RESTful API 与 OPC UA\nServer。\n第九条 停产型号的支持\n产品停产后，公司继续提供不少于 3 年的备件与维修支持。GTE-2000\n系列已于 2023 年 12 月停产，支持期至 2026 年 12 月 31 日', 223, 3, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:22:26');
INSERT INTO `knowledge_chunk` VALUES (239, 208, 133, NULL, 7, '普通块', '。支持期\n内按库存供应备件，库存售罄后提供以旧换新或迁移方案。\n第十条 责任限制\n一、公司对设备故障承担的赔偿责任以该设备的采购金额为上限。\n二、公司不对因设备故障导致的间接损失承担责任，包括产线停机损\n失、数据丢失导致的经营损失、第三方索赔。\n三、客户应自行做好数据的中心侧备份，设备本地缓存不作为长期存\n储手段。\n第十一条 争议解决\n因本条款产生的争议，双方应协商解决；协商不成的，提交公司所在\n地有管辖权的人民法院诉讼解决', 214, 3, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:22:26');
INSERT INTO `knowledge_chunk` VALUES (240, 208, 133, NULL, 8, '普通块', '。\n第十二条 附则\n本条款由客户服务中心负责解释，自生效之日起施行，原《售后服务\n条款》（GL-SVC-2022-002）同时废止。', 66, 3, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:22:26');
INSERT INTO `knowledge_chunk` VALUES (260, 208, 135, NULL, 0, '普通块', '广联智造股份有限公司 备件供应与退换货说明\n\n文档编号：GL-SVC-2024-018\n版本：V3.1\n归口部门：客户服务中心 / 供应链部\n生效日期：2024 年 10 月 1 日\n\n一、适用范围\n\n本说明适用于广联智造 GTE 系列工业智能网关及其配件的备件采购、退货、换货业务。项目合同中另有约定的，以合同条款为准', 160, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:23:22');
INSERT INTO `knowledge_chunk` VALUES (261, 208, 135, NULL, 1, '普通块', '。\n\n二、备件目录与价格\n\n常备备件及参考价格（含税，单位：元）：\n\nGTE-3000 主板                    1280\nGTE-3000S 主板                   1860\nGTE-3000Pro 主板                 3450\n24V/2A 工业电源适配器              120\n3 针电源凤凰端子                    15\n串口端子（5 针）                    18\nDIN 导轨卡扣', 247, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:23:22');
INSERT INTO `knowledge_chunk` VALUES (262, 208, 135, NULL, 2, '普通块', '18\nDIN 导轨卡扣                       25\n4G 吸盘天线（SMA 接口）             65\n5G 棒状天线（SMA 接口）             150\n防尘套件（IP54 升级）              280\n备用外壳（含铭牌重打）              420\n\n备件价格每半年调整一次，以下单当日官网公布价格为准', 186, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:23:22');
INSERT INTO `knowledge_chunk` VALUES (263, 208, 135, NULL, 3, '普通块', '。批量采购 20 件以上可申请折扣，由销售经理提交审批。\n\n三、备件供应周期\n\n常备备件：付款后 2 个工作日内发货。\n非常备备件（如停产型号主板）：需评估库存与生产计划，一般 20 个工作日内交付，无法供应的在 3 个工作日内书面答复。\n紧急备件：签订年度服务协议的客户可申请紧急发货，当日 15:00 前下单的当日发出，加收 15% 加急费。\n\n四、停产型号的备件支持\n\nGTE-2000 系列已于 2023 年 12 月停产，备件支持期至 2026 年 12 月 31 日', 239, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:23:22');
INSERT INTO `knowledge_chunk` VALUES (264, 208, 135, NULL, 4, '普通块', '。支持期内按现有库存供应，库存售罄后提供替代方案，包括以旧换新折价或迁移到 GTE-3000 系列。\n\n停产型号的备件不接受退货。\n\n五、退货政策\n\n（一）可退货情形\n\n1. 到货 7 日内，设备未拆封、包装完好、配件齐全，因客户方原因需要退货的，可申请无理由退货，客户承担往返运费，公司不收取折旧费。\n2. 到货 15 日内，经检测确认为设备本身质量问题且无法通过维修解决的，可退货，往返运费由公司承担，货款全额退回', 209, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:23:22');
INSERT INTO `knowledge_chunk` VALUES (265, 208, 135, NULL, 5, '普通块', '。\n3. 交付的型号、配置与合同不符，且客户不接受更换的，可退货，全部费用由公司承担', 42, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:23:22');
INSERT INTO `knowledge_chunk` VALUES (266, 208, 135, NULL, 6, '普通块', '。\n\n（二）不可退货情形\n\n1. 超过到货 15 日\n2. 设备已投入使用并产生磨损、划痕、端子变形\n3. 封条破损、自行拆机\n4. 定制固件或定制硬件配置的设备\n5. 试用转采购的设备（试用期即为验收期）\n6. 促销、清仓、样机特价销售的设备\n\n（三）退货流程\n\n1. 客户提交退货申请，注明设备序列号、采购单号、退货原因，附现场照片\n2. 客户服务中心 2 个工作日内审核并答复\n3. 审核通过后由客户寄回，包装内附退货申请单复印件\n4. 我方收货后 3 个工作日内完成外观与功能检测\n5. 检测', 250, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:23:22');
INSERT INTO `knowledge_chunk` VALUES (267, 208, 135, NULL, 7, '普通块', '. 我方收货后 3 个工作日内完成外观与功能检测\n5. 检测通过后 5 个工作日内办理退款，退款原路返回\n\n检测发现设备存在人为损坏的，退货申请作废，设备寄回客户，运费由客户承担', 89, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:23:22');
INSERT INTO `knowledge_chunk` VALUES (268, 208, 135, NULL, 8, '普通块', '。\n\n六、换货政策\n\n（一）质保期内的换货\n\n设备在质保期内出现同一故障且经过两次维修仍未解决的，可申请换货。换新设备的质保期按原设备剩余质保期计算，剩余不足 3 个月的按 3 个月计。\n\n到货 30 日内出现非人为的功能性故障的，可直接申请换新，不必先走维修。\n\n（二）型号升级换货\n\n采购后 90 日内，因项目需求变更需要升级到更高型号的（如 GTE-3000 换 GTE-3000S），可申请补差价换货。补差金额 = 新型号价格 - 原型号价格 × 0.9，其中 0.9 为使用折旧系数', 246, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:23:22');
INSERT INTO `knowledge_chunk` VALUES (269, 208, 135, NULL, 9, '普通块', '。设备须外观完好、功能正常', 13, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:23:22');
INSERT INTO `knowledge_chunk` VALUES (270, 208, 135, NULL, 10, '普通块', '。\n\n（三）换货流程\n\n1. 提交换货申请，注明原设备序列号与目标型号\n2. 审核通过后，公司先发新设备（需客户提供设备押金或签署《设备返还承诺函》）\n3. 客户收到新设备后 10 个工作日内寄回原设备\n4. 我方检测原设备无人为损坏后，退还押金或解除承诺函\n5. 逾期未寄回的，按新设备原价开票收费\n\n七、返修与退换的包装要求\n\n1. 使用原厂包装箱，无原箱时使用不小于 5 层瓦楞纸的硬质纸箱\n2. 设备四周填充不少于 3 厘米厚的防震材料\n3. 端子、天线等小件单独装袋，避免在运输中划伤主板', 249, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:23:23');
INSERT INTO `knowledge_chunk` VALUES (271, 208, 135, NULL, 11, '普通块', '材料\n3. 端子、天线等小件单独装袋，避免在运输中划伤主板\n4. 箱内必须附《返修/退换申请单》，写明序列号、故障现象、联系人、联系电话\n5. 寄件时选择可追踪的物流方式，不接受到付件\n\n包装不当导致运输途中新增损坏的，责任由寄件方承担', 118, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:23:23');
INSERT INTO `knowledge_chunk` VALUES (272, 208, 135, NULL, 12, '普通块', '。\n\n八、常见问题\n\n问：不知道设备序列号在哪看？\n答：序列号印在设备侧面铭牌上，格式 GL3000-YYWW-XXXXX，YY 为出厂年份后两位，WW 为出厂周数。也可在 Web 界面【运行监控】页面顶部查看。\n\n问：退货时发票怎么处理？\n答：已开具的增值税专用发票需退回原件，我方收到发票原件后再办理退款。发票已认证抵扣的，由客户开具红字信息表。\n\n问：能不能只换主板自己动手修？\n答：质保期内自行拆机会导致失去保修资格', 212, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:23:23');
INSERT INTO `knowledge_chunk` VALUES (273, 208, 135, NULL, 13, '普通块', '。质保期外可以购买主板自行更换，但更换后设备不再享有整机质保，仅备件本身享有 6 个月保修。\n\n问：备件也有质保吗？\n答：有。单独购买的备件自签收之日起保修 6 个月，随整机维修更换的备件跟随整机剩余质保期，剩余不足 3 个月的按 3 个月计。', 122, NULL, NULL, NULL, '已完成', '2026-09-04 02:18:44', '2026-09-04 10:23:23');
INSERT INTO `knowledge_chunk` VALUES (443, 208, 134, NULL, 0, '普通块', '# 广联智造 客户常见问题解答（FAQ）\n\n文档编号：GL-SVC-2024-011\n版本：V5.0\n维护部门：客户服务中心\n更新日期：2025 年 1 月 10 日\n\n## 一、订购与交付\n\n### Q1：GTE-3000 的标准交货周期是多久？\n\n常规型号现货库存充足时，付款后 3 个工作日内发货。GTE-3000Pro 及定制配置为订单式生产，交货周期为 15 个工作日。批量订单超过 100 台的，交货周期另行确认', 212, NULL, NULL, NULL, '已完成', '2026-09-04 04:32:54', '2026-09-04 12:32:55');
INSERT INTO `knowledge_chunk` VALUES (444, 208, 134, NULL, 1, '普通块', '。批量订单超过 100 台的，交货周期另行确认。\n\n### Q2：设备发货包含哪些配件？\n\n标准包装内含：网关主机 1 台、24V/2A 电源适配器 1 个、DIN 导轨卡扣 1 套、3 针电源端子 1 个、串口端子 2 个（GTE-3000S 与 GTE-3000Pro 为 4 个）、快速入门指南 1 份、合格证 1 张。天线为选配件，4G/5G 型号默认随机附送吸盘天线 1 根。\n\n### Q3：可以先试用再采购吗？\n\n支持。意向客户可申请 30 天试用，需提交试用申请单并由销售经理审批', 248, NULL, NULL, NULL, '已完成', '2026-09-04 04:32:54', '2026-09-04 12:32:55');
INSERT INTO `knowledge_chunk` VALUES (445, 208, 134, NULL, 2, '普通块', '。试用期内设备所有权归公司，试用结束后 7 日内返还或转为采购。试用设备的运费由客户承担，采购转化后运费可在货款中抵扣。\n\n### Q4：能否开具增值税专用发票？\n\n可以。客户提供开票信息（单位名称、纳税人识别号、地址电话、开户行及账号）后，随货或在收到货款后 5 个工作日内开具 13% 增值税专用发票。\n\n## 二、质保与维修\n\n### Q5：设备的质保期是多久？\n\nGTE 系列整机质量保证期为自出厂之日起 24 个月。电源适配器、天线等配件的保修期为 12 个月', 235, NULL, NULL, NULL, '已完成', '2026-09-04 04:32:54', '2026-09-04 12:32:55');
INSERT INTO `knowledge_chunk` VALUES (446, 208, 134, NULL, 3, '普通块', '。电源适配器、天线等配件的保修期为 12 个月。质保期以设备铭牌上的出厂日期为准，客户能提供有效购买凭证的，可按购买日期顺延，最长顺延 3 个月', 72, NULL, NULL, NULL, '已完成', '2026-09-04 04:32:54', '2026-09-04 12:32:55');
INSERT INTO `knowledge_chunk` VALUES (447, 208, 134, NULL, 4, '普通块', '。\n\n### Q6：哪些情况不在保修范围内？\n\n以下情形属于非保修范围，维修按有偿处理：\n\n- 超出质保期\n- 未按手册要求使用，例如输入电压超出 DC 9V~36V 范围导致烧毁\n- 自行拆机、改装，或封条破损\n- 因水浸、火灾、雷击、地震等不可抗力造成的损坏\n- 外壳明显机械性损伤，例如摔落导致的结构变形\n- 使用非广联智造提供的固件或第三方非授权软件导致的故障\n\n### Q7：设备坏了怎么报修', 201, NULL, NULL, NULL, '已完成', '2026-09-04 04:32:54', '2026-09-04 12:32:55');
INSERT INTO `knowledge_chunk` VALUES (448, 208, 134, NULL, 5, '普通块', '？\n\n三种方式任选其一：\n\n1. 拨打服务热线 400-820-9600，工作日 8:30 至 20:30，节假日 9:00 至 18:00\n2. 在广联智造官网【服务支持】提交在线工单\n3. 联系对接的销售经理或售后工程师\n\n报修时请提供设备序列号（SN）、故障现象描述、故障发生时间、现场照片或日志文件', 153, NULL, NULL, NULL, '已完成', '2026-09-04 04:32:54', '2026-09-04 12:32:55');
INSERT INTO `knowledge_chunk` VALUES (449, 208, 134, NULL, 6, '普通块', '。序列号在设备侧面铭牌上，格式为 GL3000-YYWW-XXXXX。\n\n### Q8：维修一般要多久？\n\n寄修方式：客户寄出后，我方收到设备起 5 个工作日内完成检测与维修并寄回。质保期内往返运费由公司承担，质保期外客户承担寄出运费。\n\n上门方式：仅适用于购买了上门服务包的客户，或单笔采购超过 50 台的项目客户。省会城市 24 小时内到达现场，其他地级市 48 小时内到达。\n\n### Q9：有备机可以借用吗？\n\n签订年度服务协议的客户可申请备机借用，借用期最长 15 天', 239, NULL, NULL, NULL, '已完成', '2026-09-04 04:32:54', '2026-09-04 12:32:55');
INSERT INTO `knowledge_chunk` VALUES (450, 208, 134, NULL, 7, '普通块', '。备机为同型号或更高型号，借用期间的配置由我方工程师协助导入。逾期未归还的按设备原价的 1% 每日收取占用费。\n\n## 三、安装与调试\n\n### Q10：设备管理口 IP 忘了怎么办？\n\n长按设备面板 RESET 按钮 10 秒以上，设备恢复出厂设置，管理口 IP 恢复为 192.168.1.10，默认账号 admin，默认密码 Gl@2024。恢复出厂会清空全部点位配置，请务必先尝试其他方式找回，例如用网络扫描工具在网段内查找设备 MAC 前缀 8C:1F:64 的主机', 238, NULL, NULL, NULL, '已完成', '2026-09-04 04:32:54', '2026-09-04 12:32:55');
INSERT INTO `knowledge_chunk` VALUES (451, 208, 134, NULL, 8, '普通块', '。\n\n### Q11：RS485 通信一直超时，怎么排查', 28, NULL, NULL, NULL, '已完成', '2026-09-04 04:32:54', '2026-09-04 12:32:55');
INSERT INTO `knowledge_chunk` VALUES (452, 208, 134, NULL, 9, '普通块', '？\n\n按以下顺序排查：\n\n1. 确认 A、B 两线未接反，接反时通信完全无响应\n2. 确认串口参数与从站一致，重点核对波特率、数据位、停止位、校验方式\n3. 确认从站地址正确，Modbus 从站地址范围 1 至 247\n4. 确认总线两端接了 120Ω 终端电阻，距离超过 300 米时必须接\n5. 确认设备 PE 端子已接地，车间变频器多的场合干扰强，不接地极易丢帧\n6. 用【运行监控】→【通信质量】面板看响应耗时与超时率，定位是全部从站异常还是个别从站异常\n\n### Q12：数据上云后平台收不', 250, NULL, NULL, NULL, '已完成', '2026-09-04 04:32:54', '2026-09-04 12:32:55');
INSERT INTO `knowledge_chunk` VALUES (453, 208, 134, NULL, 10, '普通块', '站异常还是个别从站异常\n\n### Q12：数据上云后平台收不到，从哪查起', 36, NULL, NULL, NULL, '已完成', '2026-09-04 04:32:54', '2026-09-04 12:32:56');
INSERT INTO `knowledge_chunk` VALUES (454, 208, 134, NULL, 11, '普通块', '？\n\n先在【数据转发】页面看连接状态', 18, NULL, NULL, NULL, '已完成', '2026-09-04 04:32:54', '2026-09-04 12:32:56');
INSERT INTO `knowledge_chunk` VALUES (455, 208, 134, NULL, 12, '普通块', '。状态为\"已连接\"说明网络与鉴权正常，问题多在主题映射或平台侧订阅；状态为\"重连中\"说明网络或证书有问题，检查设备是否能 ping 通平台域名、证书是否过期、系统时间是否准确。系统时间偏差超过 5 分钟会导致 TLS 握手失败。\n\n### Q13：点位配置能批量导入吗？\n\n可以。在【设备管理】→【点位管理】下载 Excel 模板，按模板填写点位名称、寄存器地址、数据类型、缩放系数、单位等字段后导入。单次导入不超过 5000 行，超出时分批导入', 223, NULL, NULL, NULL, '已完成', '2026-09-04 04:32:54', '2026-09-04 12:32:56');
INSERT INTO `knowledge_chunk` VALUES (456, 208, 134, NULL, 13, '普通块', '。单次导入不超过 5000 行，超出时分批导入。导入前系统会做格式校验，校验不通过的行会标红并给出原因，修正后重新导入。\n\n## 四、故障与告警\n\n### Q14：设备报 ERR-5021 是什么意思？\n\nERR-5021 是点位配置与协议栈不兼容，常见于跨大版本升级固件之后。处理方式是回退到升级前的固件版本，按《固件升级与版本发布说明》先升到过渡版本再升级目标版本。\n\n### Q15：设备频繁重启是什么原因？\n\n最常见的三个原因：\n\n1. 供电不稳', 227, NULL, NULL, NULL, '已完成', '2026-09-04 04:32:54', '2026-09-04 12:32:56');
INSERT INTO `knowledge_chunk` VALUES (457, 208, 134, NULL, 14, '普通块', '。用万用表测量输入电压，低于 9V 时设备会掉电重启，优先排查电源适配器和线路压降。\n2. 环境温度过高。长期高于 60℃ 会触发保护重启，检查安装位置是否靠近热源、机柜是否有散热。\n3. 边缘规则或模型占用内存过高。GTE-3000Pro 同时运行超过 3 个模型时可能触发内存保护，减少模型数量。\n\n### Q16：断网期间的数据会丢吗？\n\n不会立即丢失。断网时数据进入本地缓存，GTE-3000 可缓存 10 万条，GTE-3000S 为 50 万条，GTE-3000Pro 为 500 万条', 249, NULL, NULL, NULL, '已完成', '2026-09-04 04:32:54', '2026-09-04 12:32:56');
INSERT INTO `knowledge_chunk` VALUES (458, 208, 134, NULL, 15, '普通块', '。网络恢复后自动补传。只有当缓存写满仍未恢复网络时，才会按先进先出丢弃最旧的数据。\n\n## 五、账号与安全\n\n### Q17：忘记 Web 管理密码怎么办？\n\n管理员密码无法找回，只能通过恢复出厂设置重置。运维员和访客账号的密码可由管理员在【系统维护】→【用户管理】重置。建议在部署时保留至少两个管理员账号。\n\n### Q18：设备支持哪些安全加固措施？\n\n出厂默认关闭 Telnet 与 FTP，只开放 HTTPS 与 SSH', 214, NULL, NULL, NULL, '已完成', '2026-09-04 04:32:54', '2026-09-04 12:32:56');
INSERT INTO `knowledge_chunk` VALUES (459, 208, 134, NULL, 16, '普通块', '。可进一步做的加固包括：修改 SSH 默认端口、禁用 SSH 密码登录改用密钥、为北向 MQTT 启用双向证书认证、按角色分配账号避免共用管理员、定期在【系统维护】下载并归档日志。\n\n### Q19：固件会自动升级吗？\n\n不会。设备不做自动升级，所有升级均需人工在 Web 界面或设备管理平台上触发，避免生产时段意外中断采集。\n\n## 六、其他\n\n### Q20：产品有哪些认证？\n\nGTE 系列已取得 CE、FCC、CCC、RoHS 认证，4G/5G 型号另有工信部进网许可证', 239, NULL, NULL, NULL, '已完成', '2026-09-04 04:32:54', '2026-09-04 12:32:56');
INSERT INTO `knowledge_chunk` VALUES (460, 208, 134, NULL, 17, '普通块', '。认证证书可向销售经理索取电子版。\n\n### Q21：老型号 GTE-2000 还能买到吗？\n\nGTE-2000 已于 2023 年 12 月停产，目前仅提供备件与维修支持，支持期至 2026 年 12 月。新项目建议直接选用 GTE-3000 系列，点位配置文件可通过转换工具从 GTE-2000 迁移。\n\n### Q22：能提供二次开发接口吗？\n\n可以。设备提供 RESTful API 与 OPC UA Server 两种对接方式，API 文档可在官网【开发者】板块下载', 238, NULL, NULL, NULL, '已完成', '2026-09-04 04:32:54', '2026-09-04 12:32:56');
INSERT INTO `knowledge_chunk` VALUES (461, 208, 134, NULL, 18, '普通块', '。GTE-3000Pro 另支持部署自定义容器，需签订技术合作协议后由我方开放权限。', 42, NULL, NULL, NULL, '已完成', '2026-09-04 04:32:54', '2026-09-04 12:32:56');
INSERT INTO `knowledge_document` VALUES (125, 206, 'GTE-3000 系列产品技术手册', 'GTE-3000系列产品技术手册.md', 'http://127.0.0.1:9090/files/download/GTE-3000系列产品技术手册.md', 'MARKDOWN', 7756, '解析完成', NULL, '# GTE-3000 系列工业智能网关 产品技术手册\n\n文档编号：GL-PRD-2024-017\n版本：V3.2\n适用型号：GTE-3000、GTE-3000S、GTE-3000Pro\n发布单位：广联智造股份有限公司 产品部\n\n## 1. 产品概述\n\nGTE-3000 系列是广联智造面向离散制造和流程工业推出的工业智能网关，部署在产线设备与上层系统之间，负责协议转换、边缘计算和数据上云。设备采用无风扇铝合金外壳设计，支持 DIN 导轨安装和壁挂安装两种方式。\n\n系列内共三款型号，硬件平台一致，差异集中在算力、接口数量和无线能力上：\n\n| 型号 | 处理器 | 内存 | 存储 | 以太网口 | 串口 | 无线 | 典型功耗 |\n| --- | --- | --- | --- | --- | --- | --- | --- |\n| GTE-3000 | 四核 1.2GHz | 2GB | 8GB eMMC | 2 × 千兆 | 2 × RS485 | 无 | 6.5W |\n| GTE-3000S | 四核 1.2GHz | 4GB | 16GB eMMC | 4 × 千兆 | 4 × RS485/RS232 | 4G 全网通 | 9.2W |\n| GTE-3000Pro | 八核 1.8GHz | 8GB | 64GB eMMC | 4 × 千兆 | 4 × RS485/RS232 | 5G + Wi-Fi 6 | 15.8W |\n\nGTE-3000 是基础款，适合单产线小规模采集；GTE-3000S 增加了 4G 上行和更多串口，适合没有有线网络的车间；GTE-3000Pro 具备本地推理能力，可在边缘侧运行轻量视觉检测模型。\n\n## 2. 环境参数\n\n| 项目 | 指标 |\n| --- | --- |\n| 工作温度 | -20℃ ~ +70℃ |\n| 存储温度 | -40℃ ~ +85℃ |\n| 相对湿度 | 5% ~ 95%，无凝露 |\n| 防护等级 | IP40（配防尘套件后可达 IP54） |\n| 输入电压 | DC 9V ~ 36V，标配 24V 电源适配器 |\n| 抗震动 | 5 ~ 500Hz，2Grms |\n| 平均无故障时间 | MTBF ≥ 100000 小时 |\n\n安装现场环境温度长期高于 60℃ 时，必须加装导流风道或将设备移出高温区，否则处理器会触发降频保护，表现为采集周期变长、数据延迟增大。\n\n## 3. 接口说明\n\n### 3.1 电源接口\n\n设备左侧为 3 针凤凰端子，从左到右依次为 V+、V-、PE。PE 为保护接地，车间强电干扰较大时必须接地，否则 RS485 通信容易出现校验错误。\n\n### 3.2 以太网口\n\nLAN1 默认为管理口，出厂 IP 为 192.168.1.10，子网掩码 255.255.255.0。LAN2 默认为业务口，出厂配置为 DHCP 客户端。GTE-3000S 与 GTE-3000Pro 的 LAN3、LAN4 可配置为交换口，级联下游设备。\n\n管理口 IP 遗忘时，长按 RESET 按钮 10 秒以上，设备恢复出厂设置，管理口 IP 回到 192.168.1.10。恢复出厂设置会清空全部采集点位配置，操作前务必先导出配置文件。\n\n### 3.3 串口\n\nRS485 采用 2 针端子，A、B 两线。串口参数支持 1200 ~ 115200bps，默认 9600bps、8 数据位、1 停止位、无校验。同一条 485 总线上最多挂接 32 个从站，总线两端需接 120Ω 终端电阻，GTE-3000S 与 GTE-3000Pro 内置可通过拨码开关启用的终端电阻。\n\n### 3.4 数字量输入输出\n\nGTE-3000Pro 提供 4 路 DI 和 2 路 DO。DI 为干接点输入，DO 为继电器输出，触点容量 30VDC/2A。DO 常用于联动声光报警器，在采集中断或阈值越限时输出信号。\n\n## 4. 协议支持\n\n设备南向（面向现场设备）支持的协议：\n\n- Modbus RTU / Modbus TCP\n- OPC UA Client\n- Siemens S7（S7-200 Smart / S7-1200 / S7-1500）\n- Mitsubishi MC 协议（3E 帧）\n- Omron FINS\n- 三菱 FX 系列编程口协议\n- CNC 设备的 FOCAS 协议（仅 GTE-3000Pro 支持）\n\n设备北向（面向上层系统）支持的协议：\n\n- MQTT 3.1.1 / MQTT 5.0，支持 TLS 加密和双向证书认证\n- HTTP / HTTPS 主动上报\n- OPC UA Server\n- 阿里云、华为云、AWS IoT 平台标准接入\n\n一台 GTE-3000 最多可配置 2000 个采集点位，GTE-3000S 为 5000 个，GTE-3000Pro 为 20000 个。超出点位上限后新增点位会被拒绝，Web 配置页提示\"点位数量超出当前型号上限\"。\n\n## 5. 采集与上报机制\n\n采集任务以\"采集组\"为单位组织。一个采集组包含若干点位、一个采集周期和一个上报策略。采集周期最小 100ms，最大 3600s。上报策略有三种：\n\n**周期上报**：按固定间隔把最新值打包上报，间隔独立于采集周期配置。适合趋势类数据，例如温度、电流。\n\n**变化上报**：只有当数值变化超过设定的死区阈值时才上报。适合状态类数据，能显著降低流量。死区阈值支持绝对值和百分比两种形式。\n\n**混合上报**：变化时立即上报，同时按一个较长的心跳周期兜底上报一次，保证上层系统即使错过变化事件也能拿到最新值。生产环境推荐这一种。\n\n断网时数据进入本地缓存，GTE-3000 缓存容量为 10 万条，GTE-3000S 为 50 万条，GTE-3000Pro 为 500 万条。网络恢复后按时间顺序补传，补传速率默认限制为 200 条/秒，避免瞬间冲垮上层系统。缓存写满后按先进先出丢弃最旧的数据。\n\n## 6. 边缘计算\n\nGTE-3000Pro 支持在设备上运行边缘规则和轻量模型。\n\n边缘规则用类 SQL 的语法编写，例如：\n\n```text\nSELECT device_id, temperature\nFROM stream\nWHERE temperature > 85\n```\n\n命中规则后可触发三类动作：上报告警消息、置位 DO 输出、调用下游设备的写指令。\n\n模型推理支持 ONNX 格式，模型文件不超过 200MB。典型场景是产品外观缺陷的初筛，在边缘侧过滤掉明显合格的图片，只把疑似缺陷的图片上传到中心侧复检，可减少 80% 以上的上行带宽占用。\n\n## 7. Web 配置界面\n\n浏览器访问 `https://192.168.1.10`，默认账号 admin，默认密码 Gl@2024。首次登录强制修改密码，新密码不少于 10 位，且必须包含大写字母、小写字母、数字、特殊字符四类中的至少三类。\n\n主要功能区：\n\n- 运行监控：CPU、内存、存储占用，各采集组的实时状态\n- 设备管理：南向设备与点位的增删改查，支持 Excel 批量导入\n- 数据转发：北向连接配置与主题映射\n- 边缘规则：规则编写与调试\n- 系统维护：固件升级、配置导入导出、日志下载、时间同步\n\n配置文件导出格式为加密的 .glcfg，导入时校验型号与版本，跨型号导入会被拒绝。GTE-3000 的配置可以导入 GTE-3000S，反向不行，因为高型号的点位数可能超出低型号上限。\n\n## 8. 安全机制\n\n设备默认关闭 Telnet 和 FTP，仅开放 HTTPS 与 SSH。SSH 默认端口 22，可在系统维护页修改。\n\n支持三级用户角色：管理员可做全部操作；运维员可查看监控、下载日志、重启采集任务，不能改点位配置；访客只读。\n\n固件包由广联智造签名，设备升级时校验签名，签名不通过直接拒绝并保留原固件。升级过程约 3 ~ 5 分钟，期间采集中断，升级完成后自动重启并恢复原有配置。\n\n## 9. 典型部署方式\n\n**单机部署**：一台 GTE-3000 接入一条产线的 PLC 与仪表，通过 LAN2 接入车间交换机，数据上报到厂级 MES。\n\n**双机热备**：两台 GTE-3000S 通过心跳线互联，主机故障时备机在 5 秒内接管，点位配置由主机自动同步给备机。热备要求两台设备型号、固件版本完全一致。\n\n**级联部署**：车间层用多台 GTE-3000 就近采集，汇聚到一台 GTE-3000Pro 做边缘计算与统一上云，减少公网连接数。\n\n## 10. 选型建议\n\n- 点位少于 500、有有线网络、无边缘计算需求：GTE-3000\n- 点位 500 ~ 3000、现场没有网线、需要 4G 上行：GTE-3000S\n- 点位超过 3000、需要边缘推理或 CNC 设备接入：GTE-3000Pro\n\n三款设备的点位配置格式完全兼容，后期从 GTE-3000 升级到 GTE-3000Pro 时，导出配置直接导入即可，无需重新录入点位。', '否', '否', 3786, 9, '已完成', 1, '2026-09-04 02:10:18', '2026-09-04 10:23:15');
INSERT INTO `knowledge_document` VALUES (126, 206, 'GTE 系列现场安装与维护作业指导书', 'GTE系列现场安装与维护作业指导书.docx', 'http://127.0.0.1:9090/files/download/GTE系列现场安装与维护作业指导书.docx', 'WORD', 39662, '解析完成', NULL, 'GTE 系列网关 现场安装与维护作业指导书\n\n文档编号：GL-OPS-2024-009\n\n版本：V2.6\n\n适用型号：GTE-3000 / GTE-3000S / GTE-3000Pro\n\n编制部门：技术服务部\n\n1. 作业前准备\n\n现场作业前须完成三项确认：一是确认安装位置的环境温度长期不超过 60℃，且远离变频器、大功率接触器等强干扰源；二是确认现场供电为 DC 9V 至 36V，并预留独立空开；三是确认网络条件，有线接入需提前布好网线，4G/5G 接入需确认现场信号强度不低于 -95dBm。\n\n作业工具清单：\n\n2. 安装步骤\n\n1. 断开现场电源，确认电源指示灯熄灭后再进行接线作业。\n\n2. 将网关卡扣对准 DIN 导轨，先挂上沿再向下扣紧，听到卡扣到位声即可；壁挂安装时使用 M4 螺丝固定四角。\n\n3. 接入电源：3 针端子从左到右依次为 V+、V-、PE，PE 必须接柜体接地排，接地电阻不大于 4Ω。\n\n4. 接入 RS485：A 接 A、B 接 B，总线两端启用 120Ω 终端电阻，屏蔽层单端接地。\n\n5. 接入以太网：LAN1 为管理口，LAN2 为业务口，网线做完后用测试仪确认线序为 T568B。\n\n6. 无线型号安装天线，天线尽量伸出金属柜体，柜内安装会导致信号衰减 10dB 以上。\n\n7. 上电，观察指示灯：PWR 常亮表示供电正常，SYS 每秒闪烁一次表示系统运行正常，COM 闪烁表示串口有数据收发。\n\n3. 调试与验收\n\n笔记本网口配置为 192.168.1.100/24，浏览器访问 https://192.168.1.10 登录 Web 界面，默认账号 admin，默认密码 Gl@2024，首次登录强制修改密码。\n\n依次完成：修改管理口 IP 为现场规划地址、配置业务口网络、添加南向设备与点位、配置北向 MQTT 连接、启动采集组、在运行监控页确认各采集组状态为运行中。\n\n验收标准：\n\n4. 日常维护\n\n月度维护：检查指示灯状态、查看 Web 界面的 CPU 与内存占用是否长期高于 80%、检查存储剩余空间是否低于 20%、导出并归档运行日志。\n\n季度维护：清理设备表面与散热片积灰、复紧电源与串口端子、核对系统时间偏差是否超过 1 分钟、导出一次完整配置文件备份。\n\n年度维护：检查电源适配器输出电压是否衰减、评估固件版本是否需要升级、对双机热备的设备做一次主备切换演练。\n\n5. 常见故障现场处理\n\nPWR 灯不亮：先测量端子输入电压，无电压查上级空开与线路，有电压但设备不亮则更换电源适配器。\n\nSYS 灯快闪：系统异常，先断电重启；重启后仍快闪的，导出日志联系技术服务部。\n\nCOM 灯不闪：串口无数据收发，按 A/B 接反、参数不一致、从站地址错误、终端电阻缺失的顺序排查。\n\n采集组报 ERR-5021：点位配置与协议栈不兼容，多见于跨大版本升级固件之后，回退固件后按过渡版本重新升级。\n\n设备频繁重启：依次排查供电是否稳定、环境温度是否超过 60℃、边缘模型数量是否超过 3 个。\n\n6. 安全注意事项\n\n带电接线严禁进行，必须断电验电后作业。\n\n拆装主板前佩戴防静电手环，主板边缘持拿，不触碰芯片引脚。\n\n高空作业系安全带，柜顶安装使用绝缘梯。\n\n作业完成后清点工具，防止金属工具遗留在柜内造成短路。\n\n| 工具名称 | 规格 | 用途 |\n| --- | --- | --- |\n| 十字螺丝刀 | PH1 / PH2 | 端子紧固与外壳拆装 |\n| 万用表 | 支持直流电压 0-100V | 测量输入电压与线路压降 |\n| 网线测试仪 | RJ45 | 确认网线通断与线序 |\n| 笔记本电脑 | 带网口或 USB 转网口 | 配置管理口与调试 |\n| 信号强度检测仪 | 支持 4G/5G | 无线型号安装前的信号勘测 |\n| 防静电手环 | - | 拆装主板时防止静电击穿 |\n\n| 验收项 | 合格标准 | 检查方式 |\n| --- | --- | --- |\n| 供电电压 | 端子处实测 22V 至 26V | 万用表测量 |\n| 接地电阻 | 不大于 4Ω | 接地电阻测试仪 |\n| 串口通信 | 各从站超时率低于 1% | 通信质量面板观察 10 分钟 |\n| 点位数据 | 抽查 10 个点位与现场仪表读数一致 | 现场比对 |\n| 上云链路 | 数据转发状态为已连接，平台侧能收到数据 | 平台侧核对 |\n| 断网补传 | 拔网线 5 分钟后恢复，数据无缺口 | 查询平台历史曲线 |\n| 重启恢复 | 断电重启后 90 秒内采集自动恢复 | 现场断电测试 |', '是', '否', 1930, 5, '已完成', 1, '2026-09-04 02:10:18', '2026-09-04 10:23:15');
INSERT INTO `knowledge_document` VALUES (127, 206, 'GTE 系列故障代码速查表', 'GTE系列故障代码速查表.xlsx', 'http://127.0.0.1:9090/files/download/GTE系列故障代码速查表.xlsx', 'EXCEL', 9275, '解析完成', NULL, '【工作表：故障代码】\n| 故障代码 | 名称 | 严重等级 | 触发条件 | 现场处理步骤 | 是否影响采集 |\n| --- | --- | --- | --- | --- | --- |\n| ERR-1001 | 输入电压过低 | 严重 | 输入电压持续低于 9V 超过 3 秒 | 测量端子实测电压，检查上级空开与线路压降，必要时更换电源适配器 | 是 |\n| ERR-1002 | 输入电压过高 | 严重 | 输入电压持续高于 36V 超过 1 秒 | 立即断电，核对电源规格，禁止使用非 24V 工业电源 | 是 |\n| ERR-1005 | 机内温度过高 | 警告 | 主板温度传感器读数超过 85℃ | 检查安装位置是否靠近热源，加装导流风道或移出高温区 | 否 |\n| ERR-2003 | eMMC 存储写入失败 | 严重 | 连续 3 次写入校验不通过 | 导出日志后返厂检测，存储芯片寿命耗尽需更换主板 | 是 |\n| ERR-2007 | 存储空间不足 | 警告 | 剩余存储空间低于 10% | 在系统维护页清理历史日志，或缩短本地缓存保留天数 | 否 |\n| ERR-3011 | RS485 通信超时 | 警告 | 同一从站连续 5 个采集周期无响应 | 按 A/B 接反、串口参数不一致、从站地址错误、终端电阻缺失的顺序排查 | 部分 |\n| ERR-3012 | RS485 校验错误率过高 | 警告 | 10 分钟内 CRC 校验失败率超过 5% | 检查 PE 是否接地、屏蔽层是否单端接地、总线长度是否超过 1200 米 | 部分 |\n| ERR-3020 | Modbus 从站返回异常码 | 提示 | 从站返回异常功能码 01/02/03 | 核对寄存器地址与数据类型，确认从站是否支持该功能码 | 部分 |\n| ERR-4002 | OPC UA 会话建立失败 | 警告 | 与 OPC UA Server 握手失败 | 核对端点地址、安全策略、用户名密码，检查证书是否过期 | 部分 |\n| ERR-4015 | S7 连接被拒绝 | 警告 | PLC 侧拒绝建立连接 | 确认 PLC 的机架号槽号配置，确认 PLC 允许的连接数未耗尽 | 部分 |\n| ERR-5021 | 点位配置与协议栈不兼容 | 严重 | 加载点位配置时字段解析失败 | 多见于跨大版本升级固件之后，回退固件后按过渡版本重新升级 | 是 |\n| ERR-5022 | 点位数量超出型号上限 | 警告 | 配置点位数超过当前型号上限 | 删减点位或升级到更高型号，GTE-3000 上限 2000、GTE-3000S 为 5000、GTE-3000Pro 为 20000 | 部分 |\n| ERR-6003 | MQTT 连接鉴权失败 | 严重 | Broker 返回 CONNACK 错误码 4 或 5 | 核对用户名密码与 ClientID，确认平台侧设备未被禁用 | 否 |\n| ERR-6008 | TLS 握手失败 | 严重 | 证书校验不通过或时间不同步 | 检查证书有效期与 CA 链，核对设备系统时间偏差是否超过 5 分钟 | 否 |\n| ERR-6012 | 本地缓存写满 | 警告 | 断网期间缓存条数达到型号上限 | 尽快恢复网络，缓存写满后按先进先出丢弃最旧数据 | 否 |\n| ERR-7001 | 边缘规则语法错误 | 提示 | 规则保存时语法解析失败 | 在边缘规则页面用调试功能定位错误行，确认字段名与流名称正确 | 否 |\n| ERR-7005 | 模型加载失败 | 警告 | ONNX 模型文件校验不通过或超过 200MB | 确认模型格式与算子版本，压缩或裁剪模型后重新上传 | 否 |\n| ERR-7009 | 边缘推理内存不足 | 严重 | 同时运行的模型占用内存超过阈值 | 减少同时运行的模型数量，单设备建议不超过 3 个 | 部分 |\n| ERR-8004 | 固件签名校验失败 | 严重 | 升级包签名与设备公钥不匹配 | 从官方渠道重新下载固件包，核对 SHA256 校验值 | 否 |\n| ERR-8006 | 固件型号不匹配 | 提示 | 升级包型号标识与设备型号不一致 | GTE-3000 与 GTE-3000S 固件不通用，检查包名中的型号标识 | 否 |\n| ERR-9002 | 双机热备心跳丢失 | 警告 | 连续 5 秒未收到对端心跳 | 检查心跳线连通性，确认两台设备型号与固件版本完全一致 | 否 |\n| ERR-9007 | 系统时间未同步 | 提示 | NTP 同步连续失败超过 24 小时 | 确认 NTP 服务器地址可达，无外网时改用内网 NTP 或手动设置时间 | 否 |\n\n【工作表：指示灯状态】\n| 指示灯 | 状态 | 含义 | 处理建议 |\n| --- | --- | --- | --- |\n| PWR | 常亮 | 供电正常 | 无需处理 |\n| PWR | 不亮 | 无供电或电源损坏 | 测量输入电压，更换电源适配器 |\n| SYS | 每秒闪烁一次 | 系统运行正常 | 无需处理 |\n| SYS | 快速闪烁 | 系统异常 | 断电重启，仍异常则导出日志报修 |\n| SYS | 常亮不闪 | 系统启动中或已卡死 | 等待 90 秒，仍常亮则断电重启 |\n| COM | 闪烁 | 串口有数据收发 | 无需处理 |\n| COM | 不闪 | 串口无数据 | 排查接线、串口参数、从站地址 |\n| NET | 常亮 | 北向连接已建立 | 无需处理 |\n| NET | 慢闪 | 正在重连 | 检查网络与证书，查看 ERR-6003 与 ERR-6008 |\n| ALM | 常亮 | 存在未确认的严重告警 | 登录 Web 界面查看告警列表 |', '是', '否', 2435, 6, '已完成', 1, '2026-09-04 02:10:18', '2026-09-04 10:23:16');
INSERT INTO `knowledge_document` VALUES (128, 206, '固件升级与版本发布说明', '固件升级与版本发布说明.txt', 'http://127.0.0.1:9090/files/download/固件升级与版本发布说明.txt', 'TXT', 4953, '解析完成', NULL, '广联智造 GTE 系列固件升级与版本发布说明\n\n文档编号：GL-PRD-2024-023\n版本：V1.8\n适用型号：GTE-3000、GTE-3000S、GTE-3000Pro\n维护部门：产品部 固件组\n\n一、固件版本命名规则\n\n固件版本号形如 3.2.14-r5，四段含义如下：\n\n3   主版本号，硬件平台大改或协议栈重构时递增\n2   次版本号，新增功能时递增\n14  修订号，缺陷修复时递增\nr5  发布批次，同一修订号的重新打包，功能不变\n\n主版本号不同的固件不能直接升级，例如 2.x 升 3.x 必须先升到 2.9.20 过渡版本，再升 3.0.0，跳版升级会导致配置文件无法解析，设备启动后点位全部丢失。\n\n二、当前在维版本\n\n3.2.14-r5   稳定版，2024 年 9 月发布，推荐生产环境使用\n3.3.6-r2    功能版，2024 年 12 月发布，新增 5G 双卡双待和 MQTT 5.0 支持\n2.9.20-r8   维护版，仅修复严重缺陷，2025 年 12 月 31 日停止维护\n\n三、3.3.6 主要变更\n\n新增功能：\n1. MQTT 5.0 支持，可使用共享订阅和主题别名，长连接场景下报文开销降低约 15%\n2. GTE-3000S 与 GTE-3000Pro 支持 5G 双卡双待，主卡故障时 30 秒内自动切换到备卡\n3. 采集组支持导入导出为 Excel，字段包括点位名称、寄存器地址、数据类型、缩放系数\n4. Web 界面新增\"通信质量\"面板，展示各南向设备的响应耗时与超时率\n5. 边缘规则支持窗口函数，可计算 5 分钟滑动平均值\n\n缺陷修复：\n1. 修复 RS485 在 115200bps 下长时间运行偶发丢帧的问题，原因是串口驱动缓冲区在高负载下未及时清空\n2. 修复断网补传时数据顺序错乱的问题，补传队列改为严格按时间戳排序\n3. 修复配置文件导入后 DO 输出状态未复位的问题\n4. 修复 OPC UA Server 在客户端异常断开后会话未释放，累计超过 64 个后拒绝新连接的问题\n5. 修复设备时间未同步时日志时间戳为 1970 年的问题\n\n已知问题：\n1. GTE-3000Pro 在同时运行 4 个以上 ONNX 模型时内存占用偏高，建议单设备模型数不超过 3 个\n2. FOCAS 协议连接部分老款 FANUC 系统时首次握手较慢，约需 20 秒\n\n四、升级前准备\n\n1. 在 Web 界面【系统维护】→【配置管理】导出当前配置，文件名建议带日期，例如 line3-gw01-20241220.glcfg\n2. 在【系统维护】→【日志下载】导出最近 7 天日志，便于升级后对比\n3. 确认设备电源稳定，升级过程中断电会导致固件损坏，需要返厂刷机\n4. 确认当前固件版本与目标固件版本主版本号一致\n5. 通知产线相关人员，升级期间数据采集中断 3 到 5 分钟\n\n五、升级操作步骤\n\n方式一：Web 界面升级（推荐）\n\n1. 浏览器访问设备管理口 https://192.168.1.10，用管理员账号登录\n2. 进入【系统维护】→【固件升级】\n3. 点击\"选择文件\"，上传 .glfw 固件包\n4. 系统自动校验签名和型号匹配，校验通过后\"开始升级\"按钮变为可点击\n5. 点击\"开始升级\"，页面显示进度条，此时不要关闭页面、不要断电\n6. 进度到 100% 后设备自动重启，约 60 秒后 Web 界面恢复访问\n7. 登录后在【运行监控】确认版本号已更新，各采集组状态为\"运行中\"\n\n方式二：批量升级\n\n超过 20 台设备时使用广联智造设备管理平台批量下发。平台按分组推送固件，支持分批灰度：先升级 10% 的设备，观察 24 小时无异常后再推送剩余设备。\n\n六、升级失败的处理\n\n现象一：上传固件包后提示\"签名校验失败\"\n原因是固件包不完整或来源不可信。重新从官方渠道下载，核对 SHA256 校验值。\n\n现象二：提示\"型号不匹配\"\nGTE-3000 与 GTE-3000S 的固件包不通用，检查包名中的型号标识。\n\n现象三：升级后设备无法访问\n先确认管理口 IP 是否变化，用直连方式访问 192.168.1.10。仍无法访问时长按 RESET 10 秒恢复出厂设置，再导入升级前导出的配置文件。\n\n现象四：升级后采集组不运行，日志报 ERR-5021\n这是点位配置与新版本协议栈不兼容，多见于 2.x 跨版本升到 3.x。回退到升级前版本，走 2.9.20 过渡版本重新升级。\n\n七、固件回退\n\n设备保留上一个版本的固件镜像，在【系统维护】→【固件升级】页面点击\"回退到上一版本\"即可，回退耗时约 2 分钟。回退只保留一个历史版本，连续升级两次后无法回退到更早的版本。\n\n回退后配置文件会自动降级适配，但新版本中新增的配置项会丢失，例如从 3.3.6 回退到 3.2.14 时，5G 双卡配置和窗口函数规则都会被清除。\n\n八、版本支持周期\n\n稳定版自发布之日起提供 24 个月的缺陷修复支持，功能版为 12 个月。停止维护的版本不再发布安全补丁，建议在停止维护前 3 个月完成升级规划。', '否', '否', 2134, 6, '已完成', 1, '2026-09-04 02:10:18', '2026-09-04 10:23:17');
INSERT INTO `knowledge_document` VALUES (129, 207, '员工手册', '员工手册.md', 'http://127.0.0.1:9090/files/download/员工手册.md', 'MARKDOWN', 7193, '解析完成', NULL, '# 广联智造股份有限公司 员工手册\n\n文档编号：GL-HR-2024-001\n版本：V4.1\n生效日期：2024 年 7 月 1 日\n解释部门：人力资源部\n\n## 第一章 总则\n\n第一条 为规范公司管理，明确员工的权利与义务，依据《中华人民共和国劳动法》《中华人民共和国劳动合同法》及相关法律法规，结合公司实际情况，制定本手册。\n\n第二条 本手册适用于与公司签订劳动合同的全体员工，包括正式员工、试用期员工。实习生、劳务派遣人员参照执行，另有约定的从其约定。\n\n第三条 员工入职时应认真阅读本手册并签署确认。本手册自生效之日起执行，此前发布的规定与本手册不一致的，以本手册为准。\n\n## 第二章 入职与试用期\n\n第四条 新员工报到时须提交以下材料：身份证原件及复印件、最高学历与学位证书、离职证明、体检报告、银行卡复印件、一寸照片两张。学历信息由人力资源部通过学信网核验。\n\n第五条 提供虚假材料的，公司有权解除劳动合同且不支付经济补偿。已入职后发现的，按严重违纪处理。\n\n第六条 试用期依据劳动合同期限确定：\n\n- 劳动合同期限 1 年以上不满 3 年的，试用期 2 个月\n- 劳动合同期限 3 年以上的，试用期 6 个月\n- 劳动合同期限 3 个月以上不满 1 年的，试用期 1 个月\n\n第七条 试用期工资为转正工资的 80%，且不低于公司所在地最低工资标准。研发岗位试用期工资为转正工资的 90%。\n\n第八条 试用期届满前 15 个工作日，员工提交转正申请，直属主管填写评估意见，部门负责人审批。评估维度包括工作产出、专业能力、协作意识、文化认同四项，任一项不合格的可延长试用期一次，延长期限不超过 1 个月，且总试用期不超过法定上限。\n\n第九条 试用期内员工离职提前 3 日以书面形式通知；正式员工离职提前 30 日以书面形式通知。\n\n## 第三章 工作时间\n\n第十条 公司实行标准工时制，每日工作 8 小时，每周工作 5 天。上班时间为 9:00 至 18:00，其中 12:00 至 13:00 为午休时间。\n\n第十一条 生产部门实行综合计算工时制，以月为周期，月度总工时不超过法定标准。具体排班由生产部制定并报人力资源部备案。\n\n第十二条 弹性工作：研发、设计、产品岗位可申请弹性上下班，上班时间在 8:30 至 10:00 之间自行选择，当日工作满 8 小时即可。核心工作时间为 10:00 至 16:00，此时段内不得擅自离岗。\n\n第十三条 加班须提前在 OA 系统提交加班申请，经直属主管审批后有效。未经审批的自愿延时工作不视为加班。加班可选择调休或按规定支付加班费，调休有效期为加班之日起 3 个月内。\n\n## 第四章 薪酬与福利\n\n第十四条 薪酬结构为：月度总收入 = 基本工资 + 岗位工资 + 绩效工资 + 补贴。基本工资与岗位工资固定发放，绩效工资按季度考核结果浮动。\n\n第十五条 工资发放日为每月 15 日，遇节假日提前至最近一个工作日。工资通过银行转账发放，个人所得税由公司代扣代缴。\n\n第十六条 公司按国家规定为员工缴纳养老、医疗、失业、工伤、生育五项社会保险及住房公积金，缴纳基数按上年度月平均工资核定，公积金缴存比例为 12%。\n\n第十七条 补贴项目：\n\n- 餐补：每工作日 30 元，随工资发放\n- 交通补贴：每月 200 元，外勤岗位每月 500 元\n- 通讯补贴：每月 100 元，销售与售后岗位每月 300 元\n- 高温补贴：6 月至 9 月，每月 300 元\n- 现场驻场补贴：客户现场连续驻场满 5 个工作日的，每日 150 元\n\n第十八条 年度福利包括：年度体检一次、生日礼金 500 元、结婚贺金 1000 元、生育贺金 1000 元、春节与中秋节日礼品。工龄满 3 年的员工，年度体检升级为深度套餐。\n\n第十九条 年终奖与公司年度经营情况和个人绩效挂钩，一般在次年 2 月发放。发放时已离职的员工不参与分配。\n\n## 第五章 绩效管理\n\n第二十条 公司实行季度绩效考核，考核周期为每年 1-3 月、4-6 月、7-9 月、10-12 月。\n\n第二十一条 考核等级分为 S、A、B、C、D 五级，对应的绩效系数为 1.5、1.2、1.0、0.8、0。部门内 S 级比例不超过 10%，A 级不超过 30%。\n\n第二十二条 连续两个季度考核为 C 的员工，进入为期 3 个月的绩效改进计划。改进期结束仍未达标的，公司可调岗或依法解除劳动合同。\n\n第二十三条 单季度考核为 D 的，当季绩效工资为零，并由部门负责人与人力资源部共同面谈。\n\n## 第六章 培训与发展\n\n第二十四条 新员工入职后参加为期 3 天的入职培训，内容包括公司概况、产品知识、规章制度、信息安全。培训考核不合格的补考一次。\n\n第二十五条 技术岗位每年安排不少于 40 学时的专业培训。公司承担费用的外部培训，单次费用超过 5000 元的，员工须签订培训服务期协议，服务期为 2 年。服务期内主动离职的，按未履行月份比例返还培训费用。\n\n第二十六条 员工可申请内部转岗，入职满 1 年且当前岗位绩效为 B 及以上的具备申请资格。转岗须经原部门与接收部门共同同意，转岗后重新计算 1 个月的岗位适应期。\n\n## 第七章 行为规范\n\n第二十七条 员工应遵守职业道德，不得从事与公司业务存在竞争关系的兼职，不得利用职务便利谋取私利。\n\n第二十八条 员工不得收受供应商、客户的现金、有价证券或贵重物品。因业务往来收到的礼品价值超过 500 元的，应上交行政部登记处理。\n\n第二十九条 涉密岗位员工离职时须完成保密事项交接，并遵守竞业限制协议约定。竞业限制期限最长不超过 2 年，公司按月支付补偿金。\n\n第三十条 严重违纪情形包括但不限于：泄露公司商业秘密、伪造报销单据、连续旷工 3 天或年累计旷工 5 天、在工作场所打架斗殴、严重失职造成重大经济损失。发生上述情形的，公司可即时解除劳动合同。\n\n## 第八章 离职管理\n\n第三十一条 员工离职须完成工作交接，交接内容包括在办事项、文档资料、办公设备、门禁卡、账号权限。交接完成并经双方签字确认后，人力资源部办理离职手续。\n\n第三十二条 公司在解除或终止劳动合同时出具离职证明，并在 15 日内为员工办理档案和社会保险关系转移手续。\n\n第三十三条 离职当月工资在下一个正常发薪日随薪资一并发放。未休完的法定年休假按日工资的 300% 折算支付。\n\n## 第九章 附则\n\n第三十四条 本手册由人力资源部负责解释和修订。修订后的版本经总经理办公会审议通过后发布，发布之日起生效。\n\n第三十五条 本手册未尽事宜，按国家法律法规及公司其他制度执行。', '否', '否', 2752, 12, '已完成', 1, '2026-09-04 02:10:18', '2026-09-04 10:23:18');
INSERT INTO `knowledge_document` VALUES (130, 207, '差旅与费用报销管理制度', '差旅与费用报销管理制度.docx', 'http://127.0.0.1:9090/files/download/差旅与费用报销管理制度.docx', 'WORD', 39066, '解析完成', NULL, '广联智造股份有限公司 差旅与费用报销管理制度\n\n文档编号：GL-FIN-2024-004\n\n版本：V3.5\n\n生效日期：2024 年 9 月 1 日\n\n归口部门：财务部\n\n第一章 总则\n\n第一条 为规范公司差旅与费用报销管理，控制成本、提高效率，制定本制度。本制度适用于公司全体员工因公出差、日常费用垫付及各类费用报销业务。\n\n第二条 报销遵循先审批后支出、实事求是、单据合规三项原则。未经审批发生的费用，公司有权拒绝报销。\n\n第二章 出差管理\n\n第三条 出差前须在 OA 系统提交出差申请，注明出差事由、目的地、起止日期、同行人员、预计费用。审批通过后方可订票。紧急出差可先行前往，但须在出发后 1 个工作日内补交申请。\n\n第四条 出差审批权限：3 天以内由部门负责人审批；3 天以上至 7 天由分管副总审批；7 天以上或出境由总经理审批。\n\n第五条 交通工具标准：\n\n单程飞行时间超过 3 小时或火车运行时间超过 6 小时的，普通员工可申请升舱，需分管副总批准。\n\n第六条 住宿标准（每人每晚，含税）：\n\n超标准住宿需事前申请并说明原因，事后补报的一律按标准上限报销，差额自理。两名同性别员工同行的，鼓励合住标准间，节省部分按每人每晚 50 元给予补贴。\n\n第七条 出差补贴（每人每天）：\n\n出差当日往返不足 8 小时的不发放补贴；客户或合作方已安排餐食的，当餐补贴不予发放。客户现场连续驻场满 5 个工作日的，另按员工手册第十七条发放驻场补贴。\n\n第三章 费用报销\n\n第八条 报销时限：费用发生后 30 日内提交报销单，跨年度费用最迟在次年 1 月 15 日前提交，逾期不予受理。\n\n第九条 单据要求：发票抬头须为公司全称，纳税人识别号准确；增值税专用发票需在开票之日起 360 日内认证；餐费、住宿费须附消费明细；打车费须提供行程单而非仅支付截图。\n\n第十条 报销审批权限：\n\n第十一条 付款周期：每月 10 日、25 日为固定付款日。报销单在付款日前 3 个工作日完成财务审核的，纳入本期付款，否则顺延至下一期。\n\n第十二条 借款管理：单笔预借款不超过预计费用的 80%，出差结束后 10 个工作日内核销。前次借款未核销的，不得再次借款。\n\n第四章 违规处理\n\n第十三条 虚开发票、虚报费用、拆分单据规避审批的，全额追回并按员工手册第三十条按严重违纪处理。\n\n第十四条 财务部每季度抽查报销单据，抽查比例不低于 10%，抽查结果报总经理。\n\n第五章 附则\n\n第十五条 本制度由财务部负责解释，自生效之日起施行。\n\n| 职级 | 飞机 | 火车 | 市内交通 |\n| --- | --- | --- | --- |\n| 总经理及以上 | 公务舱 | 商务座 | 实报实销 |\n| 总监 / 分管副总 | 经济舱 | 一等座 | 实报实销 |\n| 经理 / 主管 | 经济舱 | 二等座 | 每日限额 100 元 |\n| 普通员工 | 经济舱 | 二等座 | 每日限额 80 元 |\n\n| 城市类别 | 普通员工 | 经理/主管 | 总监及以上 |\n| --- | --- | --- | --- |\n| 一类城市（北上广深） | 500 元 | 700 元 | 1000 元 |\n| 二类城市（省会及计划单列市） | 400 元 | 550 元 | 800 元 |\n| 三类城市（其他地级市） | 300 元 | 400 元 | 600 元 |\n| 县城及乡镇 | 220 元 | 300 元 | 450 元 |\n\n| 城市类别 | 伙食补贴 | 杂费补贴 |\n| --- | --- | --- |\n| 一类城市 | 120 元 | 30 元 |\n| 二类城市 | 100 元 | 30 元 |\n| 三类城市及以下 | 80 元 | 20 元 |\n\n| 单笔金额 | 审批人 |\n| --- | --- |\n| 1000 元以下 | 部门负责人 |\n| 1000 元至 5000 元 | 分管副总 |\n| 5000 元至 30000 元 | 总经理 |\n| 30000 元以上 | 总经理办公会 |', '是', '否', 1704, 7, '已完成', 1, '2026-09-04 02:10:18', '2026-09-04 10:23:18');
INSERT INTO `knowledge_document` VALUES (131, 207, '考勤与请假管理办法', '考勤与请假管理办法.txt', 'http://127.0.0.1:9090/files/download/考勤与请假管理办法.txt', 'TXT', 6375, '解析完成', NULL, '广联智造股份有限公司 考勤与请假管理办法\n\n文档编号：GL-HR-2024-006\n版本：V2.3\n生效日期：2024 年 7 月 1 日\n归口部门：人力资源部\n\n第一章 考勤规定\n\n第一条 全体员工均须参加考勤。考勤方式为企业微信定位打卡与门禁刷卡双记录，以企业微信记录为准，门禁记录用于异常核查。\n\n第二条 每日打卡两次：上班一次，下班一次。漏打卡当月不超过 3 次的，由本人在 OA 提交补卡申请，主管审批后不计异常；超过 3 次的，从第 4 次起每次按迟到处理。\n\n第三条 迟到与早退：\n上班时间后 30 分钟以内到岗记迟到，下班时间前 30 分钟以内离岗记早退。\n当月迟到或早退累计不超过 2 次的不扣款。\n第 3 次起每次扣款 50 元，当月累计超过 5 次的，绩效考核降一档。\n\n第四条 上班时间后超过 30 分钟到岗且未提前请假的，按旷工半天处理。全天未到岗且未办理请假手续的，按旷工一天处理。\n\n第五条 旷工处理：\n旷工一天扣发当日工资的 2 倍。\n连续旷工 3 天或年度累计旷工 5 天的，公司可依据员工手册第三十条解除劳动合同。\n\n第六条 外出与出差期间无法打卡的，在 OA 提交外勤或出差申请，审批通过后系统自动免打卡。客户现场驻场的，由项目经理在周报中统一确认出勤。\n\n第七条 弹性工作岗位按员工手册第十二条执行，打卡记录仅统计当日工时是否满 8 小时，不单独计迟到。核心时段 10:00 至 16:00 无故缺勤的，按早退或旷工处理。\n\n第二章 假期种类与标准\n\n第八条 法定年休假\n\n员工累计工作满 1 年不满 10 年的，年休假 5 天；满 10 年不满 20 年的，年休假 10 天；满 20 年的，年休假 15 天。累计工作年限包含在其他单位的工作年限，以社保缴纳记录或离职证明为准。\n\n第九条 公司福利年假\n\n在本公司司龄满 1 年的，额外增加福利年假 2 天；司龄满 3 年增加 4 天；司龄满 5 年增加 6 天。福利年假与法定年休假合并使用，当年有效，不跨年结转，也不折算工资。\n\n第十条 病假\n\n病假须提供二级及以上医院的病假条与挂号记录。当年病假累计不超过 10 天的，按基本工资的 80% 计发；超过 10 天的部分按当地最低工资标准的 80% 计发。\n连续病假超过 15 天的，须提交复工证明后方可返岗。\n医疗期按国家规定根据工龄核定，医疗期内公司不解除劳动合同。\n\n第十一条 事假\n\n事假为无薪假，按日工资标准扣除。日工资 = 月工资 ÷ 21.75。\n单次事假不超过 3 天的由部门负责人审批；超过 3 天的报分管副总审批；超过 10 天的报总经理审批。\n当年事假累计超过 20 天的，取消当年年终奖资格。\n\n第十二条 婚假\n\n依法登记结婚的享受婚假 13 天（含国家规定 3 天与地方奖励 10 天），含双休日与法定节假日。婚假须在领证之日起 12 个月内一次性休完，逾期作废。\n\n第十三条 产假与陪产假\n\n女员工生育享受产假 158 天，其中产前可休 15 天。难产增加 15 天，多胞胎每多生育一个婴儿增加 15 天。\n男员工享受陪产假 15 天，须在配偶生育之日起 3 个月内休完。\n女员工在婴儿满 1 周岁前，每日享有 1 小时哺乳时间，可合并使用为每日提前 1 小时下班。\n\n第十四条 育儿假\n\n夫妻双方在子女满 3 周岁前，每人每年享受育儿假 10 天。育儿假按出勤发放工资，当年不休不结转。\n\n第十五条 丧假\n\n直系亲属（父母、配偶、子女）去世的，丧假 3 天；祖父母、外祖父母、配偶父母去世的，丧假 1 天。需异地奔丧的，凭票据另给路程假，最多 2 天。\n\n第十六条 工伤假\n\n因工负伤经认定为工伤的，停工留薪期内工资福利待遇不变，由公司按月支付。停工留薪期一般不超过 12 个月，伤情严重的经劳动能力鉴定委员会确认可适当延长。\n\n第三章 请假流程\n\n第十七条 所有假期均须在 OA 系统提交申请，紧急情况可先电话通知直属主管，但须在返岗后 1 个工作日内补交申请，逾期未补的按旷工处理。\n\n第十八条 审批权限：\n\n请假 0.5 天至 1 天         直属主管审批\n请假 1 天以上至 3 天        部门负责人审批\n请假 3 天以上至 10 天       分管副总审批\n请假 10 天以上             总经理审批\n产假、工伤假               部门负责人审批后报人力资源部备案\n\n第十九条 年休假原则上须提前 5 个工作日申请，避开生产高峰期与项目关键节点。同一部门同期休假人数不超过部门人数的 30%。\n\n第二十条 请假期间的工作须指定代理人并完成交接，未交接导致工作延误的，追究请假人责任。\n\n第四章 加班与调休\n\n第二十一条 加班分为工作日加班、休息日加班、法定节假日加班三类，须提前在 OA 提交加班申请。\n\n第二十二条 加班补偿方式：\n\n工作日延时加班       按 1.5 倍折算调休时长，或按 1.5 倍支付加班费\n休息日加班           优先安排同等时长调休，无法调休的按 2 倍支付加班费\n法定节假日加班       按 3 倍支付加班费，不以调休替代\n\n第二十三条 调休须在加班之日起 3 个月内使用，逾期作废。调休以 0.5 天为最小单位。\n\n第二十四条 综合计算工时制岗位的加班，以月度周期总工时超出法定标准的部分计算，不按日计算。\n\n第五章 考勤统计与申诉\n\n第二十五条 人力资源部每月 3 日前生成上月考勤报表，发送至各部门负责人确认。\n\n第二十六条 员工对考勤记录有异议的，在收到报表后 2 个工作日内向人力资源部提出申诉，并提供门禁记录、工作邮件、系统操作日志等佐证材料。逾期未申诉的视为认可。\n\n第二十七条 考勤结果作为绩效考核、年终奖发放、评优评先的依据之一。\n\n第六章 附则\n\n第二十八条 本办法由人力资源部负责解释，与员工手册不一致的以本办法为准。\n\n第二十九条 本办法自发布之日起施行，原《考勤管理规定》（GL-HR-2022-006）同时废止。', '否', '否', 2507, 11, '已完成', 1, '2026-09-04 02:10:18', '2026-09-04 10:23:19');
INSERT INTO `knowledge_document` VALUES (132, 207, '信息安全与数据保护管理规范', '信息安全与数据保护管理规范.md', 'http://127.0.0.1:9090/files/download/信息安全与数据保护管理规范.md', 'MARKDOWN', 7564, '解析完成', NULL, '# 广联智造股份有限公司 信息安全与数据保护管理规范\n\n文档编号：GL-SEC-2024-003\n版本：V2.8\n生效日期：2024 年 11 月 1 日\n归口部门：信息技术部\n\n## 第一章 总则\n\n第一条 为保护公司信息资产与客户数据安全，防范信息泄露、篡改、丢失，依据《中华人民共和国网络安全法》《中华人民共和国数据安全法》《中华人民共和国个人信息保护法》，结合公司实际，制定本规范。\n\n第二条 本规范适用于公司全体员工、实习生、外包人员，以及因业务需要接触公司信息系统的第三方人员。\n\n第三条 信息安全实行\"谁主管谁负责、谁使用谁负责\"的原则。信息技术部负责技术措施与日常监督，各部门负责人为本部门信息安全第一责任人。\n\n## 第二章 信息资产分级\n\n第四条 公司信息资产按敏感程度分为四级：\n\n**绝密**：核心源代码、固件签名私钥、未公开的产品设计图纸、并购与融资材料。仅限授权名单内人员访问，访问全程留痕。\n\n**机密**：客户名单与联系方式、合同与报价、员工薪酬数据、生产工艺参数、客户现场的点位配置文件。按岗位授权访问。\n\n**内部**：内部管理制度、会议纪要、项目周报、培训材料。全体员工可访问，不得对外传播。\n\n**公开**：产品彩页、公开发布的技术手册、官网内容、新闻稿。无访问限制。\n\n第五条 文件创建者负责标注密级。未标注的默认按\"内部\"处理。密级需要变更的，由原创建者提出，部门负责人审批。\n\n## 第三章 账号与权限\n\n第六条 员工入职时由信息技术部按岗位开通账号，包括域账号、OA、邮箱、代码仓库、生产系统等。账号遵循最小权限原则，只开通履行岗位职责所必需的权限。\n\n第七条 账号实行实名制，严禁共用账号、出借账号。因共用账号造成的安全事件，由账号所有人承担责任。\n\n第八条 密码要求：长度不少于 12 位，包含大写字母、小写字母、数字、特殊字符四类中的至少三类，不得使用姓名、生日、工号、连续字符。密码每 90 天强制更换，新密码不得与前 5 次重复。\n\n第九条 涉及绝密与机密资产的系统必须启用双因素认证。远程访问公司内网必须通过 VPN，且 VPN 强制双因素认证。\n\n第十条 权限变更：员工转岗后 3 个工作日内由原部门提交权限回收申请；离职当日冻结全部账号，30 日后删除。信息技术部每季度做一次权限复核，清理僵尸账号与超范围权限。\n\n## 第四章 终端与网络安全\n\n第十一条 办公终端必须安装公司统一的终端管理软件与杀毒软件，禁止卸载或停用。系统补丁在发布后 30 日内完成安装，高危漏洞补丁在 7 日内完成。\n\n第十二条 终端必须启用磁盘加密与屏幕锁，锁屏时间不超过 10 分钟。笔记本电脑离开办公区时须随身携带，不得放置在车内或无人看管处。\n\n第十三条 未经批准，禁止在办公终端安装破解软件、来源不明的工具、远程控制软件。研发调试确需使用的，向信息技术部申请白名单。\n\n第十四条 USB 存储设备默认禁用。确需使用的，申请开通并使用公司统一发放的加密 U 盘，加密 U 盘丢失须在 24 小时内报告。\n\n第十五条 办公网、生产网、访客网物理或逻辑隔离。访客 Wi-Fi 仅提供互联网访问，不能访问任何内部系统。生产网设备不得直接接入互联网，需要外网访问时经堡垒机或工业防火墙代理。\n\n## 第五章 数据保护\n\n第十六条 客户数据的收集遵循最小必要原则，只收集业务必需的字段，收集前告知用途并取得授权。\n\n第十七条 客户现场的点位配置文件、运行日志属于机密资产，导出后须存放在公司指定的加密存储空间，禁止存放在个人网盘、个人邮箱、微信文件传输助手。\n\n第十八条 数据传输：机密及以上级别的数据对外传输必须加密。邮件发送时使用加密压缩包，密码通过另一渠道告知接收方。禁止使用未经审批的第三方文件传输工具。\n\n第十九条 数据备份：核心业务系统每日增量备份、每周全量备份，备份数据异地保存，保留期不少于 6 个月。信息技术部每半年做一次恢复演练，验证备份可用性。\n\n第二十条 数据销毁：存储介质报废前须做物理销毁或不可恢复的擦除，由信息技术部统一执行并登记。纸质机密文件使用碎纸机销毁，不得直接投入垃圾桶。\n\n第二十一条 个人信息处理遵循《个人信息保护法》，涉及员工与客户个人信息的系统，须记录处理日志并保存不少于 3 年。\n\n## 第六章 开发安全\n\n第二十二条 源代码统一存放在公司代码仓库，禁止上传到 GitHub、Gitee 等公共平台。开源组件引入前须做许可证合规审查，禁止在闭源产品中使用 GPL 类传染性协议的组件。\n\n第二十三条 代码中禁止硬编码密码、密钥、令牌。敏感配置通过配置中心或环境变量注入，配置中心的访问受权限控制并全程审计。\n\n第二十四条 固件签名私钥保存在硬件加密机中，签名操作需两名授权人共同发起。私钥不得导出、不得复制到任何终端。\n\n第二十五条 版本发布前须完成安全测试，包括依赖组件漏洞扫描、静态代码扫描、接口越权测试。高危问题未修复的不得发布。\n\n第二十六条 生产环境数据禁止直接用于开发与测试。确需使用的，先做脱敏处理，脱敏方案由信息技术部审核。\n\n## 第七章 第三方管理\n\n第二十七条 与第三方合作前签署保密协议，明确数据使用范围、保存期限、销毁要求与违约责任。\n\n第二十八条 外包人员账号单独标识，权限仅限项目范围，合同结束后立即回收。外包人员不得接触绝密级资产。\n\n第二十九条 第三方接入公司网络的设备须先经信息技术部安全检查，检查项包括补丁状态、杀毒软件、是否存在恶意程序。\n\n## 第八章 安全事件处置\n\n第三十条 发现以下情形应在 1 小时内报告信息技术部：账号异常登录、终端感染病毒或勒索软件、机密文件外泄、设备或存储介质丢失、收到可疑钓鱼邮件并已点击。\n\n第三十一条 安全事件处置流程：报告 → 隔离受影响系统 → 评估影响范围 → 处置与恢复 → 复盘并输出改进措施。重大事件由信息技术部报总经理，并按法规要求在规定时限内向监管部门报告。\n\n第三十二条 隐瞒不报或延迟报告导致损失扩大的，按员工手册第三十条从严处理。\n\n## 第九章 培训与考核\n\n第三十三条 新员工入职培训包含信息安全模块，考核不通过的不予转正。全体员工每年参加一次信息安全复训，复训包含钓鱼邮件演练。\n\n第三十四条 信息技术部每半年组织一次全员钓鱼邮件演练，点击率纳入部门管理考核。同一员工连续两次中招的，安排专项辅导。\n\n## 第十章 附则\n\n第三十五条 本规范由信息技术部负责解释，与国家法律法规冲突的，以法律法规为准。\n\n第三十六条 本规范自生效之日起施行，原《信息安全管理办法》（GL-SEC-2022-003）同时废止。', '否', '否', 2751, 12, '已完成', 1, '2026-09-04 02:10:18', '2026-09-04 10:23:20');
INSERT INTO `knowledge_document` VALUES (133, 208, '售后服务政策与质量保证条款', '售后服务政策与质量保证条款.pdf', 'http://127.0.0.1:9090/files/download/售后服务政策与质量保证条款.pdf', 'PDF', 67858, '解析完成', NULL, '【第 1 页】\n广联智造股份有限公司\n售后服务政策与质量保证条款\n文档编号：GL-SVC-2024-002\n版本：V4.2\n生效日期：2024 年 8 月 1 日\n归口部门：客户服务中心\n第一条 适用范围\n本条款适用于客户向广联智造股份有限公司采购的 GTE 系列工业智能\n网关及其配件。销售合同中另有约定的，以合同约定为准；合同未约\n定的事项，按本条款执行。\n第二条 质量保证期\n一、GTE-3000、GTE-3000S、GTE-3000Pro 整机质量保证期为自出厂\n之日起 24 个月。质保期以设备铭牌标注的出厂日期为准。\n二、客户能提供有效购买凭证的，可按购买日期起算，最长顺延 3 个\n月。\n三、电源适配器、天线、端子、导轨卡扣等配件的保修期为 12 个月。\n四、单独采购的备件自签收之日起保修 6 个月；随整机维修更换的备\n件跟随整机剩余质保期，剩余不足 3 个月的按 3 个月计。\n五、质保期内经两次维修仍未解决同一故障的，客户可申请换货，换\n新设备的质保期按原设备剩余质保期计算，剩余不足 3 个月的按 3 个\n月计。\n第三条 免费保修范围\n质保期内，因设计、材料、制造工艺缺陷导致的功能性故障，公司提\n供免费维修或更换，包括但不限于：主板元器件失效、接口虚焊、电\n源模块异常、无线模组不识别、存储芯片写入失败。\n第四条 不属于免费保修的情形\n一、超出质量保证期。\n二、未按产品手册要求使用，例如输入电压超出 DC 9V 至 36V 范围、\n\n【第 2 页】\n环境温度长期超过 70℃、未做接地导致的通信板损坏。\n三、客户自行拆机、改装，或设备封条破损。\n四、水浸、火灾、雷击、地震、电涌等不可抗力造成的损坏。\n五、外壳明显机械性损伤，例如摔落导致的结构变形。\n六、使用非广联智造发布的固件，或安装未经授权的第三方软件导致\n的故障。\n七、正常使用产生的外观磨损、丝印褪色，不影响功能的，不在保修\n范围也不影响其他部件的保修。\n第五条 服务响应时效\n一、服务热线 400-820-9600，工作日 8:30 至 20:30，节假日 9:00\n至 18:00。\n二、远程支持：接到报修后 2 小时内响应，通过电话、远程桌面或日\n志分析协助排查。\n三、寄修服务：我方收到设备起 5 个工作日内完成检测与维修并寄\n回。质保期内往返运费由公司承担；质保期外，客户承担寄出运费，\n公司承担寄回运费。\n四、上门服务：适用于购买上门服务包的客户，或单笔采购 50 台以\n上的项目客户。省会城市 24 小时内到达现场，其他地级市 48 小时内\n到达，偏远地区双方另行约定。\n第六条 备机借用\n签订年度服务协议的客户，在设备返修期间可申请备机借用，借用期\n最长 15 天。备机为同型号或更高型号，配置由我方工程师协助导入。\n逾期未归还的，按设备原价的 1% 每日收取占用费。\n第七条 有偿维修\n一、不属于免费保修范围的故障，按实际更换的物料成本加人工费计\n收，维修前提供报价单，客户确认后实施。\n二、有偿维修的部件自维修完成之日起保修 3 个月。\n\n【第 3 页】\n三、检测后确认无故障的，收取检测费 200 元；客户放弃维修的，设\n备原样寄回，运费由客户承担。\n第八条 技术支持内容\n一、产品选型建议、点位规划建议。\n二、首次部署的远程指导，含管理口配置、南向设备接入、北向平台\n对接。\n三、固件升级方案制定与升级过程陪同。\n四、二次开发接口文档与示例代码，接口包括 RESTful API 与 OPC UA\nServer。\n第九条 停产型号的支持\n产品停产后，公司继续提供不少于 3 年的备件与维修支持。GTE-2000\n系列已于 2023 年 12 月停产，支持期至 2026 年 12 月 31 日。支持期\n内按库存供应备件，库存售罄后提供以旧换新或迁移方案。\n第十条 责任限制\n一、公司对设备故障承担的赔偿责任以该设备的采购金额为上限。\n二、公司不对因设备故障导致的间接损失承担责任，包括产线停机损\n失、数据丢失导致的经营损失、第三方索赔。\n三、客户应自行做好数据的中心侧备份，设备本地缓存不作为长期存\n储手段。\n第十一条 争议解决\n因本条款产生的争议，双方应协商解决；协商不成的，提交公司所在\n地有管辖权的人民法院诉讼解决。\n第十二条 附则\n本条款由客户服务中心负责解释，自生效之日起施行，原《售后服务\n条款》（GL-SVC-2022-002）同时废止。', '否', '否', 1831, 9, '已完成', 1, '2026-09-04 02:10:18', '2026-09-04 10:23:20');
INSERT INTO `knowledge_document` VALUES (134, 208, '客户常见问题解答', '客户常见问题解答.md', 'http://127.0.0.1:9090/files/download/客户常见问题解答.md', 'MARKDOWN', 7801, '解析完成', NULL, '# 广联智造 客户常见问题解答（FAQ）\n\n文档编号：GL-SVC-2024-011\n版本：V5.0\n维护部门：客户服务中心\n更新日期：2025 年 1 月 10 日\n\n## 一、订购与交付\n\n### Q1：GTE-3000 的标准交货周期是多久？\n\n常规型号现货库存充足时，付款后 3 个工作日内发货。GTE-3000Pro 及定制配置为订单式生产，交货周期为 15 个工作日。批量订单超过 100 台的，交货周期另行确认。\n\n### Q2：设备发货包含哪些配件？\n\n标准包装内含：网关主机 1 台、24V/2A 电源适配器 1 个、DIN 导轨卡扣 1 套、3 针电源端子 1 个、串口端子 2 个（GTE-3000S 与 GTE-3000Pro 为 4 个）、快速入门指南 1 份、合格证 1 张。天线为选配件，4G/5G 型号默认随机附送吸盘天线 1 根。\n\n### Q3：可以先试用再采购吗？\n\n支持。意向客户可申请 30 天试用，需提交试用申请单并由销售经理审批。试用期内设备所有权归公司，试用结束后 7 日内返还或转为采购。试用设备的运费由客户承担，采购转化后运费可在货款中抵扣。\n\n### Q4：能否开具增值税专用发票？\n\n可以。客户提供开票信息（单位名称、纳税人识别号、地址电话、开户行及账号）后，随货或在收到货款后 5 个工作日内开具 13% 增值税专用发票。\n\n## 二、质保与维修\n\n### Q5：设备的质保期是多久？\n\nGTE 系列整机质量保证期为自出厂之日起 24 个月。电源适配器、天线等配件的保修期为 12 个月。质保期以设备铭牌上的出厂日期为准，客户能提供有效购买凭证的，可按购买日期顺延，最长顺延 3 个月。\n\n### Q6：哪些情况不在保修范围内？\n\n以下情形属于非保修范围，维修按有偿处理：\n\n- 超出质保期\n- 未按手册要求使用，例如输入电压超出 DC 9V~36V 范围导致烧毁\n- 自行拆机、改装，或封条破损\n- 因水浸、火灾、雷击、地震等不可抗力造成的损坏\n- 外壳明显机械性损伤，例如摔落导致的结构变形\n- 使用非广联智造提供的固件或第三方非授权软件导致的故障\n\n### Q7：设备坏了怎么报修？\n\n三种方式任选其一：\n\n1. 拨打服务热线 400-820-9600，工作日 8:30 至 20:30，节假日 9:00 至 18:00\n2. 在广联智造官网【服务支持】提交在线工单\n3. 联系对接的销售经理或售后工程师\n\n报修时请提供设备序列号（SN）、故障现象描述、故障发生时间、现场照片或日志文件。序列号在设备侧面铭牌上，格式为 GL3000-YYWW-XXXXX。\n\n### Q8：维修一般要多久？\n\n寄修方式：客户寄出后，我方收到设备起 5 个工作日内完成检测与维修并寄回。质保期内往返运费由公司承担，质保期外客户承担寄出运费。\n\n上门方式：仅适用于购买了上门服务包的客户，或单笔采购超过 50 台的项目客户。省会城市 24 小时内到达现场，其他地级市 48 小时内到达。\n\n### Q9：有备机可以借用吗？\n\n签订年度服务协议的客户可申请备机借用，借用期最长 15 天。备机为同型号或更高型号，借用期间的配置由我方工程师协助导入。逾期未归还的按设备原价的 1% 每日收取占用费。\n\n## 三、安装与调试\n\n### Q10：设备管理口 IP 忘了怎么办？\n\n长按设备面板 RESET 按钮 10 秒以上，设备恢复出厂设置，管理口 IP 恢复为 192.168.1.10，默认账号 admin，默认密码 Gl@2024。恢复出厂会清空全部点位配置，请务必先尝试其他方式找回，例如用网络扫描工具在网段内查找设备 MAC 前缀 8C:1F:64 的主机。\n\n### Q11：RS485 通信一直超时，怎么排查？\n\n按以下顺序排查：\n\n1. 确认 A、B 两线未接反，接反时通信完全无响应\n2. 确认串口参数与从站一致，重点核对波特率、数据位、停止位、校验方式\n3. 确认从站地址正确，Modbus 从站地址范围 1 至 247\n4. 确认总线两端接了 120Ω 终端电阻，距离超过 300 米时必须接\n5. 确认设备 PE 端子已接地，车间变频器多的场合干扰强，不接地极易丢帧\n6. 用【运行监控】→【通信质量】面板看响应耗时与超时率，定位是全部从站异常还是个别从站异常\n\n### Q12：数据上云后平台收不到，从哪查起？\n\n先在【数据转发】页面看连接状态。状态为\"已连接\"说明网络与鉴权正常，问题多在主题映射或平台侧订阅；状态为\"重连中\"说明网络或证书有问题，检查设备是否能 ping 通平台域名、证书是否过期、系统时间是否准确。系统时间偏差超过 5 分钟会导致 TLS 握手失败。\n\n### Q13：点位配置能批量导入吗？\n\n可以。在【设备管理】→【点位管理】下载 Excel 模板，按模板填写点位名称、寄存器地址、数据类型、缩放系数、单位等字段后导入。单次导入不超过 5000 行，超出时分批导入。导入前系统会做格式校验，校验不通过的行会标红并给出原因，修正后重新导入。\n\n## 四、故障与告警\n\n### Q14：设备报 ERR-5021 是什么意思？\n\nERR-5021 是点位配置与协议栈不兼容，常见于跨大版本升级固件之后。处理方式是回退到升级前的固件版本，按《固件升级与版本发布说明》先升到过渡版本再升级目标版本。\n\n### Q15：设备频繁重启是什么原因？\n\n最常见的三个原因：\n\n1. 供电不稳。用万用表测量输入电压，低于 9V 时设备会掉电重启，优先排查电源适配器和线路压降。\n2. 环境温度过高。长期高于 60℃ 会触发保护重启，检查安装位置是否靠近热源、机柜是否有散热。\n3. 边缘规则或模型占用内存过高。GTE-3000Pro 同时运行超过 3 个模型时可能触发内存保护，减少模型数量。\n\n### Q16：断网期间的数据会丢吗？\n\n不会立即丢失。断网时数据进入本地缓存，GTE-3000 可缓存 10 万条，GTE-3000S 为 50 万条，GTE-3000Pro 为 500 万条。网络恢复后自动补传。只有当缓存写满仍未恢复网络时，才会按先进先出丢弃最旧的数据。\n\n## 五、账号与安全\n\n### Q17：忘记 Web 管理密码怎么办？\n\n管理员密码无法找回，只能通过恢复出厂设置重置。运维员和访客账号的密码可由管理员在【系统维护】→【用户管理】重置。建议在部署时保留至少两个管理员账号。\n\n### Q18：设备支持哪些安全加固措施？\n\n出厂默认关闭 Telnet 与 FTP，只开放 HTTPS 与 SSH。可进一步做的加固包括：修改 SSH 默认端口、禁用 SSH 密码登录改用密钥、为北向 MQTT 启用双向证书认证、按角色分配账号避免共用管理员、定期在【系统维护】下载并归档日志。\n\n### Q19：固件会自动升级吗？\n\n不会。设备不做自动升级，所有升级均需人工在 Web 界面或设备管理平台上触发，避免生产时段意外中断采集。\n\n## 六、其他\n\n### Q20：产品有哪些认证？\n\nGTE 系列已取得 CE、FCC、CCC、RoHS 认证，4G/5G 型号另有工信部进网许可证。认证证书可向销售经理索取电子版。\n\n### Q21：老型号 GTE-2000 还能买到吗？\n\nGTE-2000 已于 2023 年 12 月停产，目前仅提供备件与维修支持，支持期至 2026 年 12 月。新项目建议直接选用 GTE-3000 系列，点位配置文件可通过转换工具从 GTE-2000 迁移。\n\n### Q22：能提供二次开发接口吗？\n\n可以。设备提供 RESTful API 与 OPC UA Server 两种对接方式，API 文档可在官网【开发者】板块下载。GTE-3000Pro 另支持部署自定义容器，需签订技术合作协议后由我方开放权限。', '否', '否', 3263, 19, '已完成', 1, '2026-09-04 02:10:18', '2026-09-04 12:32:56');
INSERT INTO `knowledge_document` VALUES (135, 208, '备件供应与退换货说明', '备件供应与退换货说明.txt', 'http://127.0.0.1:9090/files/download/备件供应与退换货说明.txt', 'TXT', 5542, '解析完成', NULL, '广联智造股份有限公司 备件供应与退换货说明\n\n文档编号：GL-SVC-2024-018\n版本：V3.1\n归口部门：客户服务中心 / 供应链部\n生效日期：2024 年 10 月 1 日\n\n一、适用范围\n\n本说明适用于广联智造 GTE 系列工业智能网关及其配件的备件采购、退货、换货业务。项目合同中另有约定的，以合同条款为准。\n\n二、备件目录与价格\n\n常备备件及参考价格（含税，单位：元）：\n\nGTE-3000 主板                    1280\nGTE-3000S 主板                   1860\nGTE-3000Pro 主板                 3450\n24V/2A 工业电源适配器              120\n3 针电源凤凰端子                    15\n串口端子（5 针）                    18\nDIN 导轨卡扣                       25\n4G 吸盘天线（SMA 接口）             65\n5G 棒状天线（SMA 接口）             150\n防尘套件（IP54 升级）              280\n备用外壳（含铭牌重打）              420\n\n备件价格每半年调整一次，以下单当日官网公布价格为准。批量采购 20 件以上可申请折扣，由销售经理提交审批。\n\n三、备件供应周期\n\n常备备件：付款后 2 个工作日内发货。\n非常备备件（如停产型号主板）：需评估库存与生产计划，一般 20 个工作日内交付，无法供应的在 3 个工作日内书面答复。\n紧急备件：签订年度服务协议的客户可申请紧急发货，当日 15:00 前下单的当日发出，加收 15% 加急费。\n\n四、停产型号的备件支持\n\nGTE-2000 系列已于 2023 年 12 月停产，备件支持期至 2026 年 12 月 31 日。支持期内按现有库存供应，库存售罄后提供替代方案，包括以旧换新折价或迁移到 GTE-3000 系列。\n\n停产型号的备件不接受退货。\n\n五、退货政策\n\n（一）可退货情形\n\n1. 到货 7 日内，设备未拆封、包装完好、配件齐全，因客户方原因需要退货的，可申请无理由退货，客户承担往返运费，公司不收取折旧费。\n2. 到货 15 日内，经检测确认为设备本身质量问题且无法通过维修解决的，可退货，往返运费由公司承担，货款全额退回。\n3. 交付的型号、配置与合同不符，且客户不接受更换的，可退货，全部费用由公司承担。\n\n（二）不可退货情形\n\n1. 超过到货 15 日\n2. 设备已投入使用并产生磨损、划痕、端子变形\n3. 封条破损、自行拆机\n4. 定制固件或定制硬件配置的设备\n5. 试用转采购的设备（试用期即为验收期）\n6. 促销、清仓、样机特价销售的设备\n\n（三）退货流程\n\n1. 客户提交退货申请，注明设备序列号、采购单号、退货原因，附现场照片\n2. 客户服务中心 2 个工作日内审核并答复\n3. 审核通过后由客户寄回，包装内附退货申请单复印件\n4. 我方收货后 3 个工作日内完成外观与功能检测\n5. 检测通过后 5 个工作日内办理退款，退款原路返回\n\n检测发现设备存在人为损坏的，退货申请作废，设备寄回客户，运费由客户承担。\n\n六、换货政策\n\n（一）质保期内的换货\n\n设备在质保期内出现同一故障且经过两次维修仍未解决的，可申请换货。换新设备的质保期按原设备剩余质保期计算，剩余不足 3 个月的按 3 个月计。\n\n到货 30 日内出现非人为的功能性故障的，可直接申请换新，不必先走维修。\n\n（二）型号升级换货\n\n采购后 90 日内，因项目需求变更需要升级到更高型号的（如 GTE-3000 换 GTE-3000S），可申请补差价换货。补差金额 = 新型号价格 - 原型号价格 × 0.9，其中 0.9 为使用折旧系数。设备须外观完好、功能正常。\n\n（三）换货流程\n\n1. 提交换货申请，注明原设备序列号与目标型号\n2. 审核通过后，公司先发新设备（需客户提供设备押金或签署《设备返还承诺函》）\n3. 客户收到新设备后 10 个工作日内寄回原设备\n4. 我方检测原设备无人为损坏后，退还押金或解除承诺函\n5. 逾期未寄回的，按新设备原价开票收费\n\n七、返修与退换的包装要求\n\n1. 使用原厂包装箱，无原箱时使用不小于 5 层瓦楞纸的硬质纸箱\n2. 设备四周填充不少于 3 厘米厚的防震材料\n3. 端子、天线等小件单独装袋，避免在运输中划伤主板\n4. 箱内必须附《返修/退换申请单》，写明序列号、故障现象、联系人、联系电话\n5. 寄件时选择可追踪的物流方式，不接受到付件\n\n包装不当导致运输途中新增损坏的，责任由寄件方承担。\n\n八、常见问题\n\n问：不知道设备序列号在哪看？\n答：序列号印在设备侧面铭牌上，格式 GL3000-YYWW-XXXXX，YY 为出厂年份后两位，WW 为出厂周数。也可在 Web 界面【运行监控】页面顶部查看。\n\n问：退货时发票怎么处理？\n答：已开具的增值税专用发票需退回原件，我方收到发票原件后再办理退款。发票已认证抵扣的，由客户开具红字信息表。\n\n问：能不能只换主板自己动手修？\n答：质保期内自行拆机会导致失去保修资格。质保期外可以购买主板自行更换，但更换后设备不再享有整机质保，仅备件本身享有 6 个月保修。\n\n问：备件也有质保吗？\n答：有。单独购买的备件自签收之日起保修 6 个月，随整机维修更换的备件跟随整机剩余质保期，剩余不足 3 个月的按 3 个月计。', '否', '否', 2312, 14, '已完成', 1, '2026-09-04 02:10:18', '2026-09-05 23:43:04');
INSERT INTO `message_feedback` VALUES (79, 454, 1, '点赞', NULL, '否', '2026-09-05 15:49:45');
INSERT INTO `message_reference` VALUES (90, 352, 203, 131, '广联智造股份有限公司 考勤与请假管理办法\n\n文档编号：GL-HR-2024-006\n版本：V2.3\n生效日期：2024 年 7 月 1 日\n归口部门：人力资源部\n\n第一章 考勤规定\n\n第一条 全体员工均须参加考勤。考勤方式为企业微信定位打卡与门禁刷卡双记录，以企业微信记录为准，门禁记录用于异常核查。\n\n第二条 每日打卡两次：上班一次，下班一次。漏打卡当月不超过 3 次的，由本人在 OA 提交补卡申请，主管审批后不计异常；超过 3 次的，从第 4 次起每次按迟到处理。\n\n第三条 迟到与早退：\n上班时间后 30 分钟以内到岗记迟到，下班时间前 30 分钟以内离岗记早退。\n当月迟到或早退累计不超过 2 次的不扣款。\n第 3 次起每次扣款 50 元，当月累计超过 5 次的，绩效考核降一档。\n\n第四条 上班时间后超过 30 分钟到岗且未提前请假的，按旷工半天处理。全天未到岗且未办理请假手续的，按旷工一天处理。\n\n第五条 旷工处理：\n旷工一天扣发当日工资的 2 倍。\n连续旷工 3 天或年度累计旷工 5 天的，公司可依据员工手册第三十条解除劳动合同。\n\n第六条 外出与出差期间无法打卡的，在 OA 提交外勤或出差申请，审批通过后系统自动免打卡。客户现场驻场的，由项目经理在周报中统一确认出勤。\n\n第七条 弹性工作岗位按员工手册第十二条执行，打卡记录仅统计当日工时是否满 8 小时，不单独计迟到。核心时段 10:00 至 16:00 无故缺勤的，按早退或旷工处理。\n\n第二章 假期种类与标准\n\n第八条 法定年休假\n\n员工累计工作满 1 年不满 10 年的，年休假 5 天；满 10 年不满 20 年的，年休假 10 天；满 20 年的，年休假 15 天。累计工作年限包含在其他单位的工作年限，以社保缴纳记录或离职证明为准。\n\n第九条 公司福利年假\n\n在本公司司龄满 1 年的，额外增加福利年假 2 天；司龄满 3 年增加 4 天；司龄满 5 年增加 6 天。福利年假与法定年休假合并使用，当年有效，不跨年结转，也不折算工资。\n\n第十条 病假\n\n病假须提供二级及以上医院的病假条与挂号记录。当年病假累计不超过 10 天的，按基本工资的 80% 计发；超过 10 天的部分按当地最低工资标准的 80% 计发。\n连续病假超过 15 天的，须提交复工证明后方可返岗。\n医疗期按国家规定根据工龄核定，医疗期内公司不解除劳动合同。\n\n第十一条 事假\n\n事假为无薪假，按日工资标准扣除。日工资 = 月工资 ÷ 21.75。\n单次事假不超过 3 天的由部门负责人审批；超过 3 天的报分管副总审批；超过 10 天的报总经理审批。\n当年事假累计超过 20 天的，取消当年年终奖资格。\n\n第十二条 婚假\n\n依法登记结婚的享受婚假 13 天（含国家规定 3 天与地方奖励 10 天），含双休日与法定节假日。婚假须在领证之日起', 0.362394, 1, 'BM25检索+向量检索→重排→父块回填', '2026-09-04 03:41:46');
INSERT INTO `message_reference` VALUES (91, 354, 254, 134, '。单次导入不超过 5000 行，超出时分批导入。导入前系统会做格式校验，校验不通过的行会标红并给出原因，修正后重新导入。\n\n## 四、故障与告警\n\n### Q14：设备报 ERR-5021 是什么意思？\n\nERR-5021 是点位配置与协议栈不兼容，常见于跨大版本升级固件之后。处理方式是回退到升级前的固件版本，按《固件升级与版本发布说明》先升到过渡版本再升级目标版本。\n\n### Q15：设备频繁重启是什么原因？\n\n最常见的三个原因：\n\n1. 供电不稳', 0.829305, 1, 'Agentic检索', '2026-09-04 03:41:51');
INSERT INTO `message_reference` VALUES (92, 354, 248, 134, '。备机为同型号或更高型号，借用期间的配置由我方工程师协助导入。逾期未归还的按设备原价的 1% 每日收取占用费。\n\n## 三、安装与调试\n\n### Q10：设备管理口 IP 忘了怎么办？\n\n长按设备面板 RESET 按钮 10 秒以上，设备恢复出厂设置，管理口 IP 恢复为 192.168.1.10，默认账号 admin，默认密码 Gl@2024。恢复出厂会清空全部点位配置，请务必先尝试其他方式找回，例如用网络扫描工具在网段内查找设备 MAC 前缀 8C:1F:64 的主机', 0.603541, 2, 'Agentic检索', '2026-09-04 03:41:51');
INSERT INTO `message_reference` VALUES (93, 354, 253, 134, '。状态为\"已连接\"说明网络与鉴权正常，问题多在主题映射或平台侧订阅；状态为\"重连中\"说明网络或证书有问题，检查设备是否能 ping 通平台域名、证书是否过期、系统时间是否准确。系统时间偏差超过 5 分钟会导致 TLS 握手失败。\n\n### Q13：点位配置能批量导入吗？\n\n可以。在【设备管理】→【点位管理】下载 Excel 模板，按模板填写点位名称、寄存器地址、数据类型、缩放系数、单位等字段后导入。单次导入不超过 5000 行，超出时分批导入', 0.595112, 3, 'Agentic检索', '2026-09-04 03:41:51');
INSERT INTO `message_reference` VALUES (94, 354, 251, 134, '站异常还是个别从站异常\n\n### Q12：数据上云后平台收不到，从哪查起', 0.580170, 4, 'Agentic检索', '2026-09-04 03:41:51');
INSERT INTO `message_reference` VALUES (95, 354, 246, 134, '？\n\n三种方式任选其一：\n\n1. 拨打服务热线 400-820-9600，工作日 8:30 至 20:30，节假日 9:00 至 18:00\n2. 在广联智造官网【服务支持】提交在线工单\n3. 联系对接的销售经理或售后工程师\n\n报修时请提供设备序列号（SN）、故障现象描述、故障发生时间、现场照片或日志文件', 0.576325, 5, 'Agentic检索', '2026-09-04 03:41:51');
INSERT INTO `message_reference` VALUES (96, 356, 241, 134, '# 广联智造 客户常见问题解答（FAQ）\n\n文档编号：GL-SVC-2024-011\n版本：V5.0\n维护部门：客户服务中心\n更新日期：2025 年 1 月 10 日\n\n## 一、订购与交付\n\n### Q1：GTE-3000 的标准交货周期是多久？\n\n常规型号现货库存充足时，付款后 3 个工作日内发货。GTE-3000Pro 及定制配置为订单式生产，交货周期为 15 个工作日。批量订单超过 100 台的，交货周期另行确认', 0.032266, 1, 'BM25检索+向量检索', '2026-09-04 03:42:51');
INSERT INTO `message_reference` VALUES (97, 356, 243, 134, '。试用期内设备所有权归公司，试用结束后 7 日内返还或转为采购。试用设备的运费由客户承担，采购转化后运费可在货款中抵扣。\n\n### Q4：能否开具增值税专用发票？\n\n可以。客户提供开票信息（单位名称、纳税人识别号、地址电话、开户行及账号）后，随货或在收到货款后 5 个工作日内开具 13% 增值税专用发票。\n\n## 二、质保与维修\n\n### Q5：设备的质保期是多久？\n\nGTE 系列整机质量保证期为自出厂之日起 24 个月。电源适配器、天线等配件的保修期为 12 个月', 0.031778, 2, 'BM25检索+向量检索', '2026-09-04 03:42:51');
INSERT INTO `message_reference` VALUES (98, 356, 268, 135, '。\n\n六、换货政策\n\n（一）质保期内的换货\n\n设备在质保期内出现同一故障且经过两次维修仍未解决的，可申请换货。换新设备的质保期按原设备剩余质保期计算，剩余不足 3 个月的按 3 个月计。\n\n到货 30 日内出现非人为的功能性故障的，可直接申请换新，不必先走维修。\n\n（二）型号升级换货\n\n采购后 90 日内，因项目需求变更需要升级到更高型号的（如 GTE-3000 换 GTE-3000S），可申请补差价换货。补差金额 = 新型号价格 - 原型号价格 × 0.9，其中 0.9 为使用折旧系数', 0.031498, 3, 'BM25检索+向量检索', '2026-09-04 03:42:51');
INSERT INTO `message_reference` VALUES (99, 356, 247, 134, '。序列号在设备侧面铭牌上，格式为 GL3000-YYWW-XXXXX。\n\n### Q8：维修一般要多久？\n\n寄修方式：客户寄出后，我方收到设备起 5 个工作日内完成检测与维修并寄回。质保期内往返运费由公司承担，质保期外客户承担寄出运费。\n\n上门方式：仅适用于购买了上门服务包的客户，或单笔采购超过 50 台的项目客户。省会城市 24 小时内到达现场，其他地级市 48 小时内到达。\n\n### Q9：有备机可以借用吗？\n\n签订年度服务协议的客户可申请备机借用，借用期最长 15 天', 0.031281, 4, 'BM25检索+向量检索', '2026-09-04 03:42:51');
INSERT INTO `message_reference` VALUES (100, 356, 232, 133, '【第 1 页】\n广联智造股份有限公司\n售后服务政策与质量保证条款\n文档编号：GL-SVC-2024-002\n版本：V4.2\n生效日期：2024 年 8 月 1 日\n归口部门：客户服务中心\n第一条 适用范围\n本条款适用于客户向广联智造股份有限公司采购的 GTE 系列工业智能\n网关及其配件。销售合同中另有约定的，以合同约定为准；合同未约\n定的事项，按本条款执行。\n第二条 质量保证期\n一、GTE-3000、GTE-3000S、GTE-3000Pro 整机质量保证期为自出厂\n之日起 24 个月', 0.016129, 5, '向量检索', '2026-09-04 03:42:51');
INSERT INTO `message_reference` VALUES (101, 356, 264, 135, '。支持期内按现有库存供应，库存售罄后提供替代方案，包括以旧换新折价或迁移到 GTE-3000 系列。\n\n停产型号的备件不接受退货。\n\n五、退货政策\n\n（一）可退货情形\n\n1. 到货 7 日内，设备未拆封、包装完好、配件齐全，因客户方原因需要退货的，可申请无理由退货，客户承担往返运费，公司不收取折旧费。\n2. 到货 15 日内，经检测确认为设备本身质量问题且无法通过维修解决的，可退货，往返运费由公司承担，货款全额退回', 0.015625, 6, '向量检索', '2026-09-04 03:42:51');
INSERT INTO `message_reference` VALUES (102, 356, 273, 135, '。质保期外可以购买主板自行更换，但更换后设备不再享有整机质保，仅备件本身享有 6 个月保修。\n\n问：备件也有质保吗？\n答：有。单独购买的备件自签收之日起保修 6 个月，随整机维修更换的备件跟随整机剩余质保期，剩余不足 3 个月的按 3 个月计。', 0.015385, 7, 'BM25检索', '2026-09-04 03:42:51');
INSERT INTO `message_reference` VALUES (103, 356, 233, 133, '。质保期以设备铭牌标注的出厂日期为准。\n二、客户能提供有效购买凭证的，可按购买日期起算，最长顺延 3 个\n月。\n三、电源适配器、天线、端子、导轨卡扣等配件的保修期为 12 个月。\n四、单独采购的备件自签收之日起保修 6 个月；随整机维修更换的备\n件跟随整机剩余质保期，剩余不足 3 个月的按 3 个月计。\n五、质保期内经两次维修仍未解决同一故障的，客户可申请换货，换\n新设备的质保期按原设备剩余质保期计算，剩余不足 3 个月的按 3 个\n月计', 0.015152, 8, 'BM25检索', '2026-09-04 03:42:51');
INSERT INTO `message_reference` VALUES (104, 358, 203, 131, '广联智造股份有限公司 考勤与请假管理办法\n\n文档编号：GL-HR-2024-006\n版本：V2.3\n生效日期：2024 年 7 月 1 日\n归口部门：人力资源部\n\n第一章 考勤规定\n\n第一条 全体员工均须参加考勤。考勤方式为企业微信定位打卡与门禁刷卡双记录，以企业微信记录为准，门禁记录用于异常核查。\n\n第二条 每日打卡两次：上班一次，下班一次。漏打卡当月不超过 3 次的，由本人在 OA 提交补卡申请，主管审批后不计异常；超过 3 次的，从第 4 次起每次按迟到处理。\n\n第三条 迟到与早退：\n上班时间后 30 分钟以内到岗记迟到，下班时间前 30 分钟以内离岗记早退。\n当月迟到或早退累计不超过 2 次的不扣款。\n第 3 次起每次扣款 50 元，当月累计超过 5 次的，绩效考核降一档。\n\n第四条 上班时间后超过 30 分钟到岗且未提前请假的，按旷工半天处理。全天未到岗且未办理请假手续的，按旷工一天处理。\n\n第五条 旷工处理：\n旷工一天扣发当日工资的 2 倍。\n连续旷工 3 天或年度累计旷工 5 天的，公司可依据员工手册第三十条解除劳动合同。\n\n第六条 外出与出差期间无法打卡的，在 OA 提交外勤或出差申请，审批通过后系统自动免打卡。客户现场驻场的，由项目经理在周报中统一确认出勤。\n\n第七条 弹性工作岗位按员工手册第十二条执行，打卡记录仅统计当日工时是否满 8 小时，不单独计迟到。核心时段 10:00 至 16:00 无故缺勤的，按早退或旷工处理。\n\n第二章 假期种类与标准\n\n第八条 法定年休假\n\n员工累计工作满 1 年不满 10 年的，年休假 5 天；满 10 年不满 20 年的，年休假 10 天；满 20 年的，年休假 15 天。累计工作年限包含在其他单位的工作年限，以社保缴纳记录或离职证明为准。\n\n第九条 公司福利年假\n\n在本公司司龄满 1 年的，额外增加福利年假 2 天；司龄满 3 年增加 4 天；司龄满 5 年增加 6 天。福利年假与法定年休假合并使用，当年有效，不跨年结转，也不折算工资。\n\n第十条 病假\n\n病假须提供二级及以上医院的病假条与挂号记录。当年病假累计不超过 10 天的，按基本工资的 80% 计发；超过 10 天的部分按当地最低工资标准的 80% 计发。\n连续病假超过 15 天的，须提交复工证明后方可返岗。\n医疗期按国家规定根据工龄核定，医疗期内公司不解除劳动合同。\n\n第十一条 事假\n\n事假为无薪假，按日工资标准扣除。日工资 = 月工资 ÷ 21.75。\n单次事假不超过 3 天的由部门负责人审批；超过 3 天的报分管副总审批；超过 10 天的报总经理审批。\n当年事假累计超过 20 天的，取消当年年终奖资格。\n\n第十二条 婚假\n\n依法登记结婚的享受婚假 13 天（含国家规定 3 天与地方奖励 10 天），含双休日与法定节假日。婚假须在领证之日起', 0.362394, 1, 'BM25检索+向量检索→重排→父块回填', '2026-09-04 03:42:56');
INSERT INTO `message_reference` VALUES (105, 360, 254, 134, '。单次导入不超过 5000 行，超出时分批导入。导入前系统会做格式校验，校验不通过的行会标红并给出原因，修正后重新导入。\n\n## 四、故障与告警\n\n### Q14：设备报 ERR-5021 是什么意思？\n\nERR-5021 是点位配置与协议栈不兼容，常见于跨大版本升级固件之后。处理方式是回退到升级前的固件版本，按《固件升级与版本发布说明》先升到过渡版本再升级目标版本。\n\n### Q15：设备频繁重启是什么原因？\n\n最常见的三个原因：\n\n1. 供电不稳', 0.829305, 1, 'Agentic检索', '2026-09-04 03:43:01');
INSERT INTO `message_reference` VALUES (106, 360, 248, 134, '。备机为同型号或更高型号，借用期间的配置由我方工程师协助导入。逾期未归还的按设备原价的 1% 每日收取占用费。\n\n## 三、安装与调试\n\n### Q10：设备管理口 IP 忘了怎么办？\n\n长按设备面板 RESET 按钮 10 秒以上，设备恢复出厂设置，管理口 IP 恢复为 192.168.1.10，默认账号 admin，默认密码 Gl@2024。恢复出厂会清空全部点位配置，请务必先尝试其他方式找回，例如用网络扫描工具在网段内查找设备 MAC 前缀 8C:1F:64 的主机', 0.603541, 2, 'Agentic检索', '2026-09-04 03:43:01');
INSERT INTO `message_reference` VALUES (107, 360, 253, 134, '。状态为\"已连接\"说明网络与鉴权正常，问题多在主题映射或平台侧订阅；状态为\"重连中\"说明网络或证书有问题，检查设备是否能 ping 通平台域名、证书是否过期、系统时间是否准确。系统时间偏差超过 5 分钟会导致 TLS 握手失败。\n\n### Q13：点位配置能批量导入吗？\n\n可以。在【设备管理】→【点位管理】下载 Excel 模板，按模板填写点位名称、寄存器地址、数据类型、缩放系数、单位等字段后导入。单次导入不超过 5000 行，超出时分批导入', 0.595112, 3, 'Agentic检索', '2026-09-04 03:43:01');
INSERT INTO `message_reference` VALUES (108, 360, 251, 134, '站异常还是个别从站异常\n\n### Q12：数据上云后平台收不到，从哪查起', 0.580170, 4, 'Agentic检索', '2026-09-04 03:43:01');
INSERT INTO `message_reference` VALUES (109, 360, 246, 134, '？\n\n三种方式任选其一：\n\n1. 拨打服务热线 400-820-9600，工作日 8:30 至 20:30，节假日 9:00 至 18:00\n2. 在广联智造官网【服务支持】提交在线工单\n3. 联系对接的销售经理或售后工程师\n\n报修时请提供设备序列号（SN）、故障现象描述、故障发生时间、现场照片或日志文件', 0.576325, 5, 'Agentic检索', '2026-09-04 03:43:01');
INSERT INTO `message_reference` VALUES (110, 364, 267, 135, '. 我方收货后 3 个工作日内完成外观与功能检测\n5. 检测通过后 5 个工作日内办理退款，退款原路返回\n\n检测发现设备存在人为损坏的，退货申请作废，设备寄回客户，运费由客户承担', 0.631210, 1, 'Agentic检索', '2026-09-05 15:11:54');
INSERT INTO `message_reference` VALUES (111, 364, 266, 135, '。\n\n（二）不可退货情形\n\n1. 超过到货 15 日\n2. 设备已投入使用并产生磨损、划痕、端子变形\n3. 封条破损、自行拆机\n4. 定制固件或定制硬件配置的设备\n5. 试用转采购的设备（试用期即为验收期）\n6. 促销、清仓、样机特价销售的设备\n\n（三）退货流程\n\n1. 客户提交退货申请，注明设备序列号、采购单号、退货原因，附现场照片\n2. 客户服务中心 2 个工作日内审核并答复\n3. 审核通过后由客户寄回，包装内附退货申请单复印件\n4. 我方收货后 3 个工作日内完成外观与功能检测\n5. 检测', 0.538573, 2, 'Agentic检索', '2026-09-05 15:11:54');
INSERT INTO `message_reference` VALUES (112, 364, 265, 135, '。\n3. 交付的型号、配置与合同不符，且客户不接受更换的，可退货，全部费用由公司承担', 0.537121, 3, 'Agentic检索', '2026-09-05 15:11:54');
INSERT INTO `message_reference` VALUES (113, 364, 270, 135, '。\n\n（三）换货流程\n\n1. 提交换货申请，注明原设备序列号与目标型号\n2. 审核通过后，公司先发新设备（需客户提供设备押金或签署《设备返还承诺函》）\n3. 客户收到新设备后 10 个工作日内寄回原设备\n4. 我方检测原设备无人为损坏后，退还押金或解除承诺函\n5. 逾期未寄回的，按新设备原价开票收费\n\n七、返修与退换的包装要求\n\n1. 使用原厂包装箱，无原箱时使用不小于 5 层瓦楞纸的硬质纸箱\n2. 设备四周填充不少于 3 厘米厚的防震材料\n3. 端子、天线等小件单独装袋，避免在运输中划伤主板', 0.523996, 4, 'Agentic检索', '2026-09-05 15:11:54');
INSERT INTO `message_reference` VALUES (114, 364, 272, 135, '。\n\n八、常见问题\n\n问：不知道设备序列号在哪看？\n答：序列号印在设备侧面铭牌上，格式 GL3000-YYWW-XXXXX，YY 为出厂年份后两位，WW 为出厂周数。也可在 Web 界面【运行监控】页面顶部查看。\n\n问：退货时发票怎么处理？\n答：已开具的增值税专用发票需退回原件，我方收到发票原件后再办理退款。发票已认证抵扣的，由客户开具红字信息表。\n\n问：能不能只换主板自己动手修？\n答：质保期内自行拆机会导致失去保修资格', 0.505766, 5, 'Agentic检索', '2026-09-05 15:11:54');
INSERT INTO `message_reference` VALUES (115, 366, 156, 125, '。LAN2 默认为业务口，出厂配置为 DHCP 客户端。GTE-3000S 与 GTE-3000Pro 的 LAN3、LAN4 可配置为交换口，级联下游设备。\n\n管理口 IP 遗忘时，长按 RESET 按钮 10 秒以上，设备恢复出厂设置，管理口 IP 回到 192.168.1.10。恢复出厂设置会清空全部采集点位配置，操作前务必先导出配置文件。\n\n### 3.3 串口\n\nRS485 采用 2 针端子，A、B 两线。串口参数支持 1200 ~ 115200bps，默认 9600bps、8 数据位、1 停止位、无校验。同一条 485 总线上最多挂接 32 个从站，总线两端需接 120Ω 终端电阻，GTE-3000S 与 GTE-3000Pro 内置可通过拨码开关启用的终端电阻。\n\n### 3.4 数字量输入输出\n\nGTE-3000Pro 提供 4 路 DI 和 2 路 DO。DI 为干接点输入，DO 为继电器输出，触点容量 30VDC/2A。DO 常用于联动声光报警器，在采集中断或阈值越限时输出信号', 0.032266, 1, 'BM25检索+向量检索', '2026-09-05 15:14:07');
INSERT INTO `message_reference` VALUES (116, 366, 158, 125, '。超出点位上限后新增点位会被拒绝，Web 配置页提示\"点位数量超出当前型号上限\"。\n\n## 5. 采集与上报机制\n\n采集任务以\"采集组\"为单位组织。一个采集组包含若干点位、一个采集周期和一个上报策略。采集周期最小 100ms，最大 3600s。上报策略有三种：\n\n**周期上报**：按固定间隔把最新值打包上报，间隔独立于采集周期配置。适合趋势类数据，例如温度、电流。\n\n**变化上报**：只有当数值变化超过设定的死区阈值时才上报。适合状态类数据，能显著降低流量。死区阈值支持绝对值和百分比两种形式。\n\n**混合上报**：变化时立即上报，同时按一个较长的心跳周期兜底上报一次，保证上层系统即使错过变化事件也能拿到最新值。生产环境推荐这一种。\n\n断网时数据进入本地缓存，GTE-3000 缓存容量为 10 万条，GTE-3000S 为 50 万条，GTE-3000Pro 为 500 万条。网络恢复后按时间顺序补传，补传速率默认限制为 200 条/秒，避免瞬间冲垮上层系统。缓存写满后按先进先出丢弃最旧的数据。\n\n## 6. 边缘计算\n\nGTE-3000Pro 支持在设备上运行边缘规则和轻量模型', 0.032002, 2, 'BM25检索+向量检索', '2026-09-05 15:14:07');
INSERT INTO `message_reference` VALUES (117, 366, 154, 125, '。\n\n系列内共三款型号，硬件平台一致，差异集中在算力、接口数量和无线能力上：\n\n| 型号 | 处理器 | 内存 | 存储 | 以太网口 | 串口 | 无线 | 典型功耗 |\n| --- | --- | --- | --- | --- | --- | --- | --- |\n| GTE-3000 | 四核 1.2GHz | 2GB | 8GB eMMC | 2 × 千兆 | 2 × RS485 | 无 | 6.5W |\n| GTE-3000S | 四核 1.2GHz | 4GB | 16GB eMMC | 4 × 千兆 | 4 × RS485/RS232 | 4G 全网通 | 9.2W |\n| GTE-3000Pro | 八核 1.8GHz | 8GB | 64GB eMMC | 4 × 千兆 | 4 × RS485/RS232 | 5G + Wi-Fi 6 | 15.8W |\n\nGTE-3000 是基础款，适合单产线小规模采集；GTE-3000S 增加了 4G 上行和更多串口，适合没有有线网络的车间；GTE-3000Pro 具备本地推理能力，可在边缘侧运行轻量视觉检测模型', 0.031778, 3, 'BM25检索+向量检索', '2026-09-05 15:14:07');
INSERT INTO `message_reference` VALUES (118, 366, 157, 125, '。DO 常用于联动声光报警器，在采集中断或阈值越限时输出信号。\n\n## 4. 协议支持\n\n设备南向（面向现场设备）支持的协议：\n\n- Modbus RTU / Modbus TCP\n- OPC UA Client\n- Siemens S7（S7-200 Smart / S7-1200 / S7-1500）\n- Mitsubishi MC 协议（3E 帧）\n- Omron FINS\n- 三菱 FX 系列编程口协议\n- CNC 设备的 FOCAS 协议（仅 GTE-3000Pro 支持）\n\n设备北向（面向上层系统）支持的协议：\n\n- MQTT 3.1.1 / MQTT 5.0，支持 TLS 加密和双向证书认证\n- HTTP / HTTPS 主动上报\n- OPC UA Server\n- 阿里云、华为云、AWS IoT 平台标准接入\n\n一台 GTE-3000 最多可配置 2000 个采集点位，GTE-3000S 为 5000 个，GTE-3000Pro 为 20000 个。超出点位上限后新增点位会被拒绝，Web 配置页提示\"点位数量超出当前型号上限\"', 0.031754, 4, 'BM25检索+向量检索', '2026-09-05 15:14:07');
INSERT INTO `message_reference` VALUES (119, 366, 161, 125, '。升级过程约 3 ~ 5 分钟，期间采集中断，升级完成后自动重启并恢复原有配置。\n\n## 9. 典型部署方式\n\n**单机部署**：一台 GTE-3000 接入一条产线的 PLC 与仪表，通过 LAN2 接入车间交换机，数据上报到厂级 MES。\n\n**双机热备**：两台 GTE-3000S 通过心跳线互联，主机故障时备机在 5 秒内接管，点位配置由主机自动同步给备机。热备要求两台设备型号、固件版本完全一致。\n\n**级联部署**：车间层用多台 GTE-3000 就近采集，汇聚到一台 GTE-3000Pro 做边缘计算与统一上云，减少公网连接数。\n\n## 10. 选型建议\n\n- 点位少于 500、有有线网络、无边缘计算需求：GTE-3000\n- 点位 500 ~ 3000、现场没有网线、需要 4G 上行：GTE-3000S\n- 点位超过 3000、需要边缘推理或 CNC 设备接入：GTE-3000Pro\n\n三款设备的点位配置格式完全兼容，后期从 GTE-3000 升级到 GTE-3000Pro 时，导出配置直接导入即可，无需重新录入点位。', 0.031010, 5, 'BM25检索+向量检索', '2026-09-05 15:14:07');
INSERT INTO `message_reference` VALUES (120, 366, 461, 134, '。GTE-3000Pro 另支持部署自定义容器，需签订技术合作协议后由我方开放权限。', 0.030077, 6, 'BM25检索+向量检索', '2026-09-05 15:14:07');
INSERT INTO `message_reference` VALUES (121, 366, 160, 125, '。\n\n主要功能区：\n\n- 运行监控：CPU、内存、存储占用，各采集组的实时状态\n- 设备管理：南向设备与点位的增删改查，支持 Excel 批量导入\n- 数据转发：北向连接配置与主题映射\n- 边缘规则：规则编写与调试\n- 系统维护：固件升级、配置导入导出、日志下载、时间同步\n\n配置文件导出格式为加密的 .glcfg，导入时校验型号与版本，跨型号导入会被拒绝。GTE-3000 的配置可以导入 GTE-3000S，反向不行，因为高型号的点位数可能超出低型号上限。\n\n## 8. 安全机制\n\n设备默认关闭 Telnet 和 FTP，仅开放 HTTPS 与 SSH。SSH 默认端口 22，可在系统维护页修改。\n\n支持三级用户角色：管理员可做全部操作；运维员可查看监控、下载日志、重启采集任务，不能改点位配置；访客只读。\n\n固件包由广联智造签名，设备升级时校验签名，签名不通过直接拒绝并保留原固件。升级过程约 3 ~ 5 分钟，期间采集中断，升级完成后自动重启并恢复原有配置', 0.029857, 7, 'BM25检索+向量检索', '2026-09-05 15:14:07');
INSERT INTO `message_reference` VALUES (122, 366, 174, 128, '。\n\n二、当前在维版本\n\n3.2.14-r5   稳定版，2024 年 9 月发布，推荐生产环境使用\n3.3.6-r2    功能版，2024 年 12 月发布，新增 5G 双卡双待和 MQTT 5.0 支持\n2.9.20-r8   维护版，仅修复严重缺陷，2025 年 12 月 31 日停止维护\n\n三、3.3.6 主要变更\n\n新增功能：\n1. MQTT 5.0 支持，可使用共享订阅和主题别名，长连接场景下报文开销降低约 15%\n2. GTE-3000S 与 GTE-3000Pro 支持 5G 双卡双待，主卡故障时 30 秒内自动切换到备卡\n3. 采集组支持导入导出为 Excel，字段包括点位名称、寄存器地址、数据类型、缩放系数\n4. Web 界面新增\"通信质量\"面板，展示各南向设备的响应耗时与超时率\n5. 边缘规则支持窗口函数，可计算 5 分钟滑动平均值\n\n缺陷修复：\n1. 修复 RS485 在 115200bps 下长时间运行偶发丢帧的问题，原因是串口驱动缓冲区在高负载下未及时清空\n2. 修复断网补传时数据顺序错乱的问题，补传队列改为严格按时间戳排序\n3. 修复配置文件导入后 DO', 0.014925, 8, 'BM25检索', '2026-09-05 15:14:07');
INSERT INTO `message_reference` VALUES (123, 368, 233, 133, '。质保期以设备铭牌标注的出厂日期为准。\n二、客户能提供有效购买凭证的，可按购买日期起算，最长顺延 3 个\n月。\n三、电源适配器、天线、端子、导轨卡扣等配件的保修期为 12 个月。\n四、单独采购的备件自签收之日起保修 6 个月；随整机维修更换的备\n件跟随整机剩余质保期，剩余不足 3 个月的按 3 个月计。\n五、质保期内经两次维修仍未解决同一故障的，客户可申请换货，换\n新设备的质保期按原设备剩余质保期计算，剩余不足 3 个月的按 3 个\n月计', 0.689955, 1, 'Agentic检索', '2026-09-05 15:15:03');
INSERT INTO `message_reference` VALUES (124, 368, 446, 134, '。电源适配器、天线等配件的保修期为 12 个月。质保期以设备铭牌上的出厂日期为准，客户能提供有效购买凭证的，可按购买日期顺延，最长顺延 3 个月', 0.684115, 2, 'Agentic检索', '2026-09-05 15:15:03');
INSERT INTO `message_reference` VALUES (125, 368, 273, 135, '。质保期外可以购买主板自行更换，但更换后设备不再享有整机质保，仅备件本身享有 6 个月保修。\n\n问：备件也有质保吗？\n答：有。单独购买的备件自签收之日起保修 6 个月，随整机维修更换的备件跟随整机剩余质保期，剩余不足 3 个月的按 3 个月计。', 0.646740, 3, 'Agentic检索', '2026-09-05 15:15:03');
INSERT INTO `message_reference` VALUES (126, 368, 236, 133, '。\n三、寄修服务：我方收到设备起 5 个工作日内完成检测与维修并寄\n回。质保期内往返运费由公司承担；质保期外，客户承担寄出运费，\n公司承担寄回运费。\n四、上门服务：适用于购买上门服务包的客户，或单笔采购 50 台以\n上的项目客户。省会城市 24 小时内到达现场，其他地级市 48 小时内\n到达，偏远地区双方另行约定。\n第六条 备机借用\n签订年度服务协议的客户，在设备返修期间可申请备机借用，借用期\n最长 15 天。备机为同型号或更高型号，配置由我方工程师协助导入', 0.610097, 4, 'Agentic检索', '2026-09-05 15:15:03');
INSERT INTO `message_reference` VALUES (127, 368, 234, 133, '。\n第三条 免费保修范围\n质保期内，因设计、材料、制造工艺缺陷导致的功能性故障，公司提\n供免费维修或更换，包括但不限于：主板元器件失效、接口虚焊、电\n源模块异常、无线模组不识别、存储芯片写入失败。\n第四条 不属于免费保修的情形\n一、超出质量保证期。\n二、未按产品手册要求使用，例如输入电压超出 DC 9V 至 36V 范围、\n\n【第 2 页】\n环境温度长期超过 70℃、未做接地导致的通信板损坏。\n三、客户自行拆机、改装，或设备封条破损。\n四、水浸、火灾、雷击、地震、电涌等不可抗力造成的损坏', 0.603640, 5, 'Agentic检索', '2026-09-05 15:15:03');
INSERT INTO `message_reference` VALUES (146, 454, 267, 135, '. 我方收货后 3 个工作日内完成外观与功能检测\n5. 检测通过后 5 个工作日内办理退款，退款原路返回\n\n检测发现设备存在人为损坏的，退货申请作废，设备寄回客户，运费由客户承担', 0.643712, 1, 'Agentic检索', '2026-09-05 15:49:30');
INSERT INTO `message_reference` VALUES (147, 454, 265, 135, '。\n3. 交付的型号、配置与合同不符，且客户不接受更换的，可退货，全部费用由公司承担', 0.545196, 2, 'Agentic检索', '2026-09-05 15:49:30');
INSERT INTO `message_reference` VALUES (148, 454, 266, 135, '。\n\n（二）不可退货情形\n\n1. 超过到货 15 日\n2. 设备已投入使用并产生磨损、划痕、端子变形\n3. 封条破损、自行拆机\n4. 定制固件或定制硬件配置的设备\n5. 试用转采购的设备（试用期即为验收期）\n6. 促销、清仓、样机特价销售的设备\n\n（三）退货流程\n\n1. 客户提交退货申请，注明设备序列号、采购单号、退货原因，附现场照片\n2. 客户服务中心 2 个工作日内审核并答复\n3. 审核通过后由客户寄回，包装内附退货申请单复印件\n4. 我方收货后 3 个工作日内完成外观与功能检测\n5. 检测', 0.537210, 3, 'Agentic检索', '2026-09-05 15:49:30');
INSERT INTO `message_reference` VALUES (149, 454, 270, 135, '。\n\n（三）换货流程\n\n1. 提交换货申请，注明原设备序列号与目标型号\n2. 审核通过后，公司先发新设备（需客户提供设备押金或签署《设备返还承诺函》）\n3. 客户收到新设备后 10 个工作日内寄回原设备\n4. 我方检测原设备无人为损坏后，退还押金或解除承诺函\n5. 逾期未寄回的，按新设备原价开票收费\n\n七、返修与退换的包装要求\n\n1. 使用原厂包装箱，无原箱时使用不小于 5 层瓦楞纸的硬质纸箱\n2. 设备四周填充不少于 3 厘米厚的防震材料\n3. 端子、天线等小件单独装袋，避免在运输中划伤主板', 0.520610, 4, 'Agentic检索', '2026-09-05 15:49:30');
INSERT INTO `message_reference` VALUES (150, 454, 272, 135, '。\n\n八、常见问题\n\n问：不知道设备序列号在哪看？\n答：序列号印在设备侧面铭牌上，格式 GL3000-YYWW-XXXXX，YY 为出厂年份后两位，WW 为出厂周数。也可在 Web 界面【运行监控】页面顶部查看。\n\n问：退货时发票怎么处理？\n答：已开具的增值税专用发票需退回原件，我方收到发票原件后再办理退款。发票已认证抵扣的，由客户开具红字信息表。\n\n问：能不能只换主板自己动手修？\n答：质保期内自行拆机会导致失去保修资格', 0.491770, 5, 'Agentic检索', '2026-09-05 15:49:30');
INSERT INTO `message_reference` VALUES (160, 502, 157, 125, '。DO 常用于联动声光报警器，在采集中断或阈值越限时输出信号。\n\n## 4. 协议支持\n\n设备南向（面向现场设备）支持的协议：\n\n- Modbus RTU / Modbus TCP\n- OPC UA Client\n- Siemens S7（S7-200 Smart / S7-1200 / S7-1500）\n- Mitsubishi MC 协议（3E 帧）\n- Omron FINS\n- 三菱 FX 系列编程口协议\n- CNC 设备的 FOCAS 协议（仅 GTE-3000Pro 支持）\n\n设备北向（面向上层系统）支持的协议：\n\n- MQTT 3.1.1 / MQTT 5.0，支持 TLS 加密和双向证书认证\n- HTTP / HTTPS 主动上报\n- OPC UA Server\n- 阿里云、华为云、AWS IoT 平台标准接入\n\n一台 GTE-3000 最多可配置 2000 个采集点位，GTE-3000S 为 5000 个，GTE-3000Pro 为 20000 个。超出点位上限后新增点位会被拒绝，Web 配置页提示\"点位数量超出当前型号上限\"', 0.032018, 1, 'BM25检索+向量检索', '2026-09-05 16:27:11');
INSERT INTO `message_reference` VALUES (161, 502, 158, 125, '。超出点位上限后新增点位会被拒绝，Web 配置页提示\"点位数量超出当前型号上限\"。\n\n## 5. 采集与上报机制\n\n采集任务以\"采集组\"为单位组织。一个采集组包含若干点位、一个采集周期和一个上报策略。采集周期最小 100ms，最大 3600s。上报策略有三种：\n\n**周期上报**：按固定间隔把最新值打包上报，间隔独立于采集周期配置。适合趋势类数据，例如温度、电流。\n\n**变化上报**：只有当数值变化超过设定的死区阈值时才上报。适合状态类数据，能显著降低流量。死区阈值支持绝对值和百分比两种形式。\n\n**混合上报**：变化时立即上报，同时按一个较长的心跳周期兜底上报一次，保证上层系统即使错过变化事件也能拿到最新值。生产环境推荐这一种。\n\n断网时数据进入本地缓存，GTE-3000 缓存容量为 10 万条，GTE-3000S 为 50 万条，GTE-3000Pro 为 500 万条。网络恢复后按时间顺序补传，补传速率默认限制为 200 条/秒，避免瞬间冲垮上层系统。缓存写满后按先进先出丢弃最旧的数据。\n\n## 6. 边缘计算\n\nGTE-3000Pro 支持在设备上运行边缘规则和轻量模型', 0.032002, 2, 'BM25检索+向量检索', '2026-09-05 16:27:11');
INSERT INTO `message_reference` VALUES (162, 502, 156, 125, '。LAN2 默认为业务口，出厂配置为 DHCP 客户端。GTE-3000S 与 GTE-3000Pro 的 LAN3、LAN4 可配置为交换口，级联下游设备。\n\n管理口 IP 遗忘时，长按 RESET 按钮 10 秒以上，设备恢复出厂设置，管理口 IP 回到 192.168.1.10。恢复出厂设置会清空全部采集点位配置，操作前务必先导出配置文件。\n\n### 3.3 串口\n\nRS485 采用 2 针端子，A、B 两线。串口参数支持 1200 ~ 115200bps，默认 9600bps、8 数据位、1 停止位、无校验。同一条 485 总线上最多挂接 32 个从站，总线两端需接 120Ω 终端电阻，GTE-3000S 与 GTE-3000Pro 内置可通过拨码开关启用的终端电阻。\n\n### 3.4 数字量输入输出\n\nGTE-3000Pro 提供 4 路 DI 和 2 路 DO。DI 为干接点输入，DO 为继电器输出，触点容量 30VDC/2A。DO 常用于联动声光报警器，在采集中断或阈值越限时输出信号', 0.031754, 3, 'BM25检索+向量检索', '2026-09-05 16:27:11');
INSERT INTO `message_reference` VALUES (163, 502, 161, 125, '。升级过程约 3 ~ 5 分钟，期间采集中断，升级完成后自动重启并恢复原有配置。\n\n## 9. 典型部署方式\n\n**单机部署**：一台 GTE-3000 接入一条产线的 PLC 与仪表，通过 LAN2 接入车间交换机，数据上报到厂级 MES。\n\n**双机热备**：两台 GTE-3000S 通过心跳线互联，主机故障时备机在 5 秒内接管，点位配置由主机自动同步给备机。热备要求两台设备型号、固件版本完全一致。\n\n**级联部署**：车间层用多台 GTE-3000 就近采集，汇聚到一台 GTE-3000Pro 做边缘计算与统一上云，减少公网连接数。\n\n## 10. 选型建议\n\n- 点位少于 500、有有线网络、无边缘计算需求：GTE-3000\n- 点位 500 ~ 3000、现场没有网线、需要 4G 上行：GTE-3000S\n- 点位超过 3000、需要边缘推理或 CNC 设备接入：GTE-3000Pro\n\n三款设备的点位配置格式完全兼容，后期从 GTE-3000 升级到 GTE-3000Pro 时，导出配置直接导入即可，无需重新录入点位。', 0.031258, 4, 'BM25检索+向量检索', '2026-09-05 16:27:11');
INSERT INTO `message_reference` VALUES (164, 502, 461, 134, '。GTE-3000Pro 另支持部署自定义容器，需签订技术合作协议后由我方开放权限。', 0.030090, 5, 'BM25检索+向量检索', '2026-09-05 16:27:11');
INSERT INTO `message_reference` VALUES (165, 502, 160, 125, '。\n\n主要功能区：\n\n- 运行监控：CPU、内存、存储占用，各采集组的实时状态\n- 设备管理：南向设备与点位的增删改查，支持 Excel 批量导入\n- 数据转发：北向连接配置与主题映射\n- 边缘规则：规则编写与调试\n- 系统维护：固件升级、配置导入导出、日志下载、时间同步\n\n配置文件导出格式为加密的 .glcfg，导入时校验型号与版本，跨型号导入会被拒绝。GTE-3000 的配置可以导入 GTE-3000S，反向不行，因为高型号的点位数可能超出低型号上限。\n\n## 8. 安全机制\n\n设备默认关闭 Telnet 和 FTP，仅开放 HTTPS 与 SSH。SSH 默认端口 22，可在系统维护页修改。\n\n支持三级用户角色：管理员可做全部操作；运维员可查看监控、下载日志、重启采集任务，不能改点位配置；访客只读。\n\n固件包由广联智造签名，设备升级时校验签名，签名不通过直接拒绝并保留原固件。升级过程约 3 ~ 5 分钟，期间采集中断，升级完成后自动重启并恢复原有配置', 0.030077, 6, 'BM25检索+向量检索', '2026-09-05 16:27:11');
INSERT INTO `message_reference` VALUES (166, 502, 153, 125, '# GTE-3000 系列工业智能网关 产品技术手册\n\n文档编号：GL-PRD-2024-017\n版本：V3.2\n适用型号：GTE-3000、GTE-3000S、GTE-3000Pro\n发布单位：广联智造股份有限公司 产品部\n\n## 1. 产品概述\n\nGTE-3000 系列是广联智造面向离散制造和流程工业推出的工业智能网关，部署在产线设备与上层系统之间，负责协议转换、边缘计算和数据上云。设备采用无风扇铝合金外壳设计，支持 DIN 导轨安装和壁挂安装两种方式', 0.029631, 7, 'BM25检索+向量检索', '2026-09-05 16:27:11');
INSERT INTO `message_reference` VALUES (167, 502, 154, 125, '。\n\n系列内共三款型号，硬件平台一致，差异集中在算力、接口数量和无线能力上：\n\n| 型号 | 处理器 | 内存 | 存储 | 以太网口 | 串口 | 无线 | 典型功耗 |\n| --- | --- | --- | --- | --- | --- | --- | --- |\n| GTE-3000 | 四核 1.2GHz | 2GB | 8GB eMMC | 2 × 千兆 | 2 × RS485 | 无 | 6.5W |\n| GTE-3000S | 四核 1.2GHz | 4GB | 16GB eMMC | 4 × 千兆 | 4 × RS485/RS232 | 4G 全网通 | 9.2W |\n| GTE-3000Pro | 八核 1.8GHz | 8GB | 64GB eMMC | 4 × 千兆 | 4 × RS485/RS232 | 5G + Wi-Fi 6 | 15.8W |\n\nGTE-3000 是基础款，适合单产线小规模采集；GTE-3000S 增加了 4G 上行和更多串口，适合没有有线网络的车间；GTE-3000Pro 具备本地推理能力，可在边缘侧运行轻量视觉检测模型', 0.016393, 8, '向量检索', '2026-09-05 16:27:11');
INSERT INTO `message_reference` VALUES (168, 504, 267, 135, '. 我方收货后 3 个工作日内完成外观与功能检测\n5. 检测通过后 5 个工作日内办理退款，退款原路返回\n\n检测发现设备存在人为损坏的，退货申请作废，设备寄回客户，运费由客户承担', 0.650795, 1, 'Agentic检索', '2026-09-05 16:32:06');
INSERT INTO `message_reference` VALUES (169, 504, 266, 135, '。\n\n（二）不可退货情形\n\n1. 超过到货 15 日\n2. 设备已投入使用并产生磨损、划痕、端子变形\n3. 封条破损、自行拆机\n4. 定制固件或定制硬件配置的设备\n5. 试用转采购的设备（试用期即为验收期）\n6. 促销、清仓、样机特价销售的设备\n\n（三）退货流程\n\n1. 客户提交退货申请，注明设备序列号、采购单号、退货原因，附现场照片\n2. 客户服务中心 2 个工作日内审核并答复\n3. 审核通过后由客户寄回，包装内附退货申请单复印件\n4. 我方收货后 3 个工作日内完成外观与功能检测\n5. 检测', 0.594103, 2, 'Agentic检索', '2026-09-05 16:32:06');
INSERT INTO `message_reference` VALUES (170, 504, 265, 135, '。\n3. 交付的型号、配置与合同不符，且客户不接受更换的，可退货，全部费用由公司承担', 0.573874, 3, 'Agentic检索', '2026-09-05 16:32:06');
INSERT INTO `message_reference` VALUES (171, 504, 270, 135, '。\n\n（三）换货流程\n\n1. 提交换货申请，注明原设备序列号与目标型号\n2. 审核通过后，公司先发新设备（需客户提供设备押金或签署《设备返还承诺函》）\n3. 客户收到新设备后 10 个工作日内寄回原设备\n4. 我方检测原设备无人为损坏后，退还押金或解除承诺函\n5. 逾期未寄回的，按新设备原价开票收费\n\n七、返修与退换的包装要求\n\n1. 使用原厂包装箱，无原箱时使用不小于 5 层瓦楞纸的硬质纸箱\n2. 设备四周填充不少于 3 厘米厚的防震材料\n3. 端子、天线等小件单独装袋，避免在运输中划伤主板', 0.544619, 4, 'Agentic检索', '2026-09-05 16:32:06');
INSERT INTO `message_reference` VALUES (172, 504, 264, 135, '。支持期内按现有库存供应，库存售罄后提供替代方案，包括以旧换新折价或迁移到 GTE-3000 系列。\n\n停产型号的备件不接受退货。\n\n五、退货政策\n\n（一）可退货情形\n\n1. 到货 7 日内，设备未拆封、包装完好、配件齐全，因客户方原因需要退货的，可申请无理由退货，客户承担往返运费，公司不收取折旧费。\n2. 到货 15 日内，经检测确认为设备本身质量问题且无法通过维修解决的，可退货，往返运费由公司承担，货款全额退回', 0.524938, 5, 'Agentic检索', '2026-09-05 16:32:06');
INSERT INTO `message_reference` VALUES (173, 506, 154, 125, '。\n\n系列内共三款型号，硬件平台一致，差异集中在算力、接口数量和无线能力上：\n\n| 型号 | 处理器 | 内存 | 存储 | 以太网口 | 串口 | 无线 | 典型功耗 |\n| --- | --- | --- | --- | --- | --- | --- | --- |\n| GTE-3000 | 四核 1.2GHz | 2GB | 8GB eMMC | 2 × 千兆 | 2 × RS485 | 无 | 6.5W |\n| GTE-3000S | 四核 1.2GHz | 4GB | 16GB eMMC | 4 × 千兆 | 4 × RS485/RS232 | 4G 全网通 | 9.2W |\n| GTE-3000Pro | 八核 1.8GHz | 8GB | 64GB eMMC | 4 × 千兆 | 4 × RS485/RS232 | 5G + Wi-Fi 6 | 15.8W |\n\nGTE-3000 是基础款，适合单产线小规模采集；GTE-3000S 增加了 4G 上行和更多串口，适合没有有线网络的车间；GTE-3000Pro 具备本地推理能力，可在边缘侧运行轻量视觉检测模型', 0.032787, 1, 'BM25检索+向量检索', '2026-09-05 16:34:37');
INSERT INTO `message_reference` VALUES (174, 506, 161, 125, '。升级过程约 3 ~ 5 分钟，期间采集中断，升级完成后自动重启并恢复原有配置。\n\n## 9. 典型部署方式\n\n**单机部署**：一台 GTE-3000 接入一条产线的 PLC 与仪表，通过 LAN2 接入车间交换机，数据上报到厂级 MES。\n\n**双机热备**：两台 GTE-3000S 通过心跳线互联，主机故障时备机在 5 秒内接管，点位配置由主机自动同步给备机。热备要求两台设备型号、固件版本完全一致。\n\n**级联部署**：车间层用多台 GTE-3000 就近采集，汇聚到一台 GTE-3000Pro 做边缘计算与统一上云，减少公网连接数。\n\n## 10. 选型建议\n\n- 点位少于 500、有有线网络、无边缘计算需求：GTE-3000\n- 点位 500 ~ 3000、现场没有网线、需要 4G 上行：GTE-3000S\n- 点位超过 3000、需要边缘推理或 CNC 设备接入：GTE-3000Pro\n\n三款设备的点位配置格式完全兼容，后期从 GTE-3000 升级到 GTE-3000Pro 时，导出配置直接导入即可，无需重新录入点位。', 0.031746, 2, 'BM25检索+向量检索', '2026-09-05 16:34:37');
INSERT INTO `message_reference` VALUES (175, 506, 156, 125, '。LAN2 默认为业务口，出厂配置为 DHCP 客户端。GTE-3000S 与 GTE-3000Pro 的 LAN3、LAN4 可配置为交换口，级联下游设备。\n\n管理口 IP 遗忘时，长按 RESET 按钮 10 秒以上，设备恢复出厂设置，管理口 IP 回到 192.168.1.10。恢复出厂设置会清空全部采集点位配置，操作前务必先导出配置文件。\n\n### 3.3 串口\n\nRS485 采用 2 针端子，A、B 两线。串口参数支持 1200 ~ 115200bps，默认 9600bps、8 数据位、1 停止位、无校验。同一条 485 总线上最多挂接 32 个从站，总线两端需接 120Ω 终端电阻，GTE-3000S 与 GTE-3000Pro 内置可通过拨码开关启用的终端电阻。\n\n### 3.4 数字量输入输出\n\nGTE-3000Pro 提供 4 路 DI 和 2 路 DO。DI 为干接点输入，DO 为继电器输出，触点容量 30VDC/2A。DO 常用于联动声光报警器，在采集中断或阈值越限时输出信号', 0.031054, 3, 'BM25检索+向量检索', '2026-09-05 16:34:37');
INSERT INTO `message_reference` VALUES (176, 506, 160, 125, '。\n\n主要功能区：\n\n- 运行监控：CPU、内存、存储占用，各采集组的实时状态\n- 设备管理：南向设备与点位的增删改查，支持 Excel 批量导入\n- 数据转发：北向连接配置与主题映射\n- 边缘规则：规则编写与调试\n- 系统维护：固件升级、配置导入导出、日志下载、时间同步\n\n配置文件导出格式为加密的 .glcfg，导入时校验型号与版本，跨型号导入会被拒绝。GTE-3000 的配置可以导入 GTE-3000S，反向不行，因为高型号的点位数可能超出低型号上限。\n\n## 8. 安全机制\n\n设备默认关闭 Telnet 和 FTP，仅开放 HTTPS 与 SSH。SSH 默认端口 22，可在系统维护页修改。\n\n支持三级用户角色：管理员可做全部操作；运维员可查看监控、下载日志、重启采集任务，不能改点位配置；访客只读。\n\n固件包由广联智造签名，设备升级时校验签名，签名不通过直接拒绝并保留原固件。升级过程约 3 ~ 5 分钟，期间采集中断，升级完成后自动重启并恢复原有配置', 0.029857, 4, 'BM25检索+向量检索', '2026-09-05 16:34:37');
INSERT INTO `message_reference` VALUES (177, 506, 157, 125, '。DO 常用于联动声光报警器，在采集中断或阈值越限时输出信号。\n\n## 4. 协议支持\n\n设备南向（面向现场设备）支持的协议：\n\n- Modbus RTU / Modbus TCP\n- OPC UA Client\n- Siemens S7（S7-200 Smart / S7-1200 / S7-1500）\n- Mitsubishi MC 协议（3E 帧）\n- Omron FINS\n- 三菱 FX 系列编程口协议\n- CNC 设备的 FOCAS 协议（仅 GTE-3000Pro 支持）\n\n设备北向（面向上层系统）支持的协议：\n\n- MQTT 3.1.1 / MQTT 5.0，支持 TLS 加密和双向证书认证\n- HTTP / HTTPS 主动上报\n- OPC UA Server\n- 阿里云、华为云、AWS IoT 平台标准接入\n\n一台 GTE-3000 最多可配置 2000 个采集点位，GTE-3000S 为 5000 个，GTE-3000Pro 为 20000 个。超出点位上限后新增点位会被拒绝，Web 配置页提示\"点位数量超出当前型号上限\"', 0.016129, 5, 'BM25检索', '2026-09-05 16:34:37');
INSERT INTO `message_reference` VALUES (178, 506, 153, 125, '# GTE-3000 系列工业智能网关 产品技术手册\n\n文档编号：GL-PRD-2024-017\n版本：V3.2\n适用型号：GTE-3000、GTE-3000S、GTE-3000Pro\n发布单位：广联智造股份有限公司 产品部\n\n## 1. 产品概述\n\nGTE-3000 系列是广联智造面向离散制造和流程工业推出的工业智能网关，部署在产线设备与上层系统之间，负责协议转换、边缘计算和数据上云。设备采用无风扇铝合金外壳设计，支持 DIN 导轨安装和壁挂安装两种方式', 0.015625, 6, '向量检索', '2026-09-05 16:34:37');
INSERT INTO `message_reference` VALUES (179, 506, 169, 127, '侧拒绝建立连接 | 确认 PLC 的机架号槽号配置，确认 PLC 允许的连接数未耗尽 | 部分 |\n| ERR-5021 | 点位配置与协议栈不兼容 | 严重 | 加载点位配置时字段解析失败 | 多见于跨大版本升级固件之后，回退固件后按过渡版本重新升级 | 是 |\n| ERR-5022 | 点位数量超出型号上限 | 警告 | 配置点位数超过当前型号上限 | 删减点位或升级到更高型号，GTE-3000 上限 2000、GTE-3000S 为 5000、GTE-3000Pro 为 20000 | 部分 |\n| ERR-6003 | MQTT 连接鉴权失败 | 严重 | Broker 返回 CONNACK 错误码 4 或 5 | 核对用户名密码与 ClientID，确认平台侧设备未被禁用 | 否 |\n| ERR-6008 | TLS 握手失败 | 严重 | 证书校验不通过或时间不同步 | 检查证书有效期与 CA 链，核对设备系统时间偏差是否超过 5 分钟 | 否 |\n| ERR-6012 | 本地缓存写满 | 警告 | 断网期间缓存条数达到型号上限 | 尽快恢复网络，缓存写满后按先进先出丢弃', 0.015625, 7, 'BM25检索', '2026-09-05 16:34:37');
INSERT INTO `message_reference` VALUES (180, 506, 460, 134, '。认证证书可向销售经理索取电子版。\n\n### Q21：老型号 GTE-2000 还能买到吗？\n\nGTE-2000 已于 2023 年 12 月停产，目前仅提供备件与维修支持，支持期至 2026 年 12 月。新项目建议直接选用 GTE-3000 系列，点位配置文件可通过转换工具从 GTE-2000 迁移。\n\n### Q22：能提供二次开发接口吗？\n\n可以。设备提供 RESTful API 与 OPC UA Server 两种对接方式，API 文档可在官网【开发者】板块下载', 0.015385, 8, '向量检索', '2026-09-05 16:34:37');
INSERT INTO `message_reference` VALUES (181, 510, 154, 125, '。\n\n系列内共三款型号，硬件平台一致，差异集中在算力、接口数量和无线能力上：\n\n| 型号 | 处理器 | 内存 | 存储 | 以太网口 | 串口 | 无线 | 典型功耗 |\n| --- | --- | --- | --- | --- | --- | --- | --- |\n| GTE-3000 | 四核 1.2GHz | 2GB | 8GB eMMC | 2 × 千兆 | 2 × RS485 | 无 | 6.5W |\n| GTE-3000S | 四核 1.2GHz | 4GB | 16GB eMMC | 4 × 千兆 | 4 × RS485/RS232 | 4G 全网通 | 9.2W |\n| GTE-3000Pro | 八核 1.8GHz | 8GB | 64GB eMMC | 4 × 千兆 | 4 × RS485/RS232 | 5G + Wi-Fi 6 | 15.8W |\n\nGTE-3000 是基础款，适合单产线小规模采集；GTE-3000S 增加了 4G 上行和更多串口，适合没有有线网络的车间；GTE-3000Pro 具备本地推理能力，可在边缘侧运行轻量视觉检测模型', 0.032787, 1, 'BM25检索+向量检索', '2026-09-05 16:38:27');
