INSERT INTO `message_reference` VALUES (184, 510, 160, 125, '。\n\n主要功能区：\n\n- 运行监控：CPU、内存、存储占用，各采集组的实时状态\n- 设备管理：南向设备与点位的增删改查，支持 Excel 批量导入\n- 数据转发：北向连接配置与主题映射\n- 边缘规则：规则编写与调试\n- 系统维护：固件升级、配置导入导出、日志下载、时间同步\n\n配置文件导出格式为加密的 .glcfg，导入时校验型号与版本，跨型号导入会被拒绝。GTE-3000 的配置可以导入 GTE-3000S，反向不行，因为高型号的点位数可能超出低型号上限。\n\n## 8. 安全机制\n\n设备默认关闭 Telnet 和 FTP，仅开放 HTTPS 与 SSH。SSH 默认端口 22，可在系统维护页修改。\n\n支持三级用户角色：管理员可做全部操作；运维员可查看监控、下载日志、重启采集任务，不能改点位配置；访客只读。\n\n固件包由广联智造签名，设备升级时校验签名，签名不通过直接拒绝并保留原固件。升级过程约 3 ~ 5 分钟，期间采集中断，升级完成后自动重启并恢复原有配置', 0.029857, 4, 'BM25检索+向量检索', '2026-09-05 16:38:27');
INSERT INTO `message_reference` VALUES (185, 510, 157, 125, '。DO 常用于联动声光报警器，在采集中断或阈值越限时输出信号。\n\n## 4. 协议支持\n\n设备南向（面向现场设备）支持的协议：\n\n- Modbus RTU / Modbus TCP\n- OPC UA Client\n- Siemens S7（S7-200 Smart / S7-1200 / S7-1500）\n- Mitsubishi MC 协议（3E 帧）\n- Omron FINS\n- 三菱 FX 系列编程口协议\n- CNC 设备的 FOCAS 协议（仅 GTE-3000Pro 支持）\n\n设备北向（面向上层系统）支持的协议：\n\n- MQTT 3.1.1 / MQTT 5.0，支持 TLS 加密和双向证书认证\n- HTTP / HTTPS 主动上报\n- OPC UA Server\n- 阿里云、华为云、AWS IoT 平台标准接入\n\n一台 GTE-3000 最多可配置 2000 个采集点位，GTE-3000S 为 5000 个，GTE-3000Pro 为 20000 个。超出点位上限后新增点位会被拒绝，Web 配置页提示\"点位数量超出当前型号上限\"', 0.016129, 5, 'BM25检索', '2026-09-05 16:38:27');
INSERT INTO `message_reference` VALUES (186, 510, 153, 125, '# GTE-3000 系列工业智能网关 产品技术手册\n\n文档编号：GL-PRD-2024-017\n版本：V3.2\n适用型号：GTE-3000、GTE-3000S、GTE-3000Pro\n发布单位：广联智造股份有限公司 产品部\n\n## 1. 产品概述\n\nGTE-3000 系列是广联智造面向离散制造和流程工业推出的工业智能网关，部署在产线设备与上层系统之间，负责协议转换、边缘计算和数据上云。设备采用无风扇铝合金外壳设计，支持 DIN 导轨安装和壁挂安装两种方式', 0.015625, 6, '向量检索', '2026-09-05 16:38:27');
INSERT INTO `message_reference` VALUES (187, 510, 169, 127, '侧拒绝建立连接 | 确认 PLC 的机架号槽号配置，确认 PLC 允许的连接数未耗尽 | 部分 |\n| ERR-5021 | 点位配置与协议栈不兼容 | 严重 | 加载点位配置时字段解析失败 | 多见于跨大版本升级固件之后，回退固件后按过渡版本重新升级 | 是 |\n| ERR-5022 | 点位数量超出型号上限 | 警告 | 配置点位数超过当前型号上限 | 删减点位或升级到更高型号，GTE-3000 上限 2000、GTE-3000S 为 5000、GTE-3000Pro 为 20000 | 部分 |\n| ERR-6003 | MQTT 连接鉴权失败 | 严重 | Broker 返回 CONNACK 错误码 4 或 5 | 核对用户名密码与 ClientID，确认平台侧设备未被禁用 | 否 |\n| ERR-6008 | TLS 握手失败 | 严重 | 证书校验不通过或时间不同步 | 检查证书有效期与 CA 链，核对设备系统时间偏差是否超过 5 分钟 | 否 |\n| ERR-6012 | 本地缓存写满 | 警告 | 断网期间缓存条数达到型号上限 | 尽快恢复网络，缓存写满后按先进先出丢弃', 0.015625, 7, 'BM25检索', '2026-09-05 16:38:27');
INSERT INTO `message_reference` VALUES (188, 510, 460, 134, '。认证证书可向销售经理索取电子版。\n\n### Q21：老型号 GTE-2000 还能买到吗？\n\nGTE-2000 已于 2023 年 12 月停产，目前仅提供备件与维修支持，支持期至 2026 年 12 月。新项目建议直接选用 GTE-3000 系列，点位配置文件可通过转换工具从 GTE-2000 迁移。\n\n### Q22：能提供二次开发接口吗？\n\n可以。设备提供 RESTful API 与 OPC UA Server 两种对接方式，API 文档可在官网【开发者】板块下载', 0.015385, 8, '向量检索', '2026-09-05 16:38:27');
INSERT INTO `message_reference` VALUES (198, 560, 456, 134, '。单次导入不超过 5000 行，超出时分批导入。导入前系统会做格式校验，校验不通过的行会标红并给出原因，修正后重新导入。\n\n## 四、故障与告警\n\n### Q14：设备报 ERR-5021 是什么意思？\n\nERR-5021 是点位配置与协议栈不兼容，常见于跨大版本升级固件之后。处理方式是回退到升级前的固件版本，按《固件升级与版本发布说明》先升到过渡版本再升级目标版本。\n\n### Q15：设备频繁重启是什么原因？\n\n最常见的三个原因：\n\n1. 供电不稳', 0.829305, 1, 'Agentic检索', '2026-09-05 17:27:48');
INSERT INTO `message_reference` VALUES (199, 560, 450, 134, '。备机为同型号或更高型号，借用期间的配置由我方工程师协助导入。逾期未归还的按设备原价的 1% 每日收取占用费。\n\n## 三、安装与调试\n\n### Q10：设备管理口 IP 忘了怎么办？\n\n长按设备面板 RESET 按钮 10 秒以上，设备恢复出厂设置，管理口 IP 恢复为 192.168.1.10，默认账号 admin，默认密码 Gl@2024。恢复出厂会清空全部点位配置，请务必先尝试其他方式找回，例如用网络扫描工具在网段内查找设备 MAC 前缀 8C:1F:64 的主机', 0.603541, 2, 'Agentic检索', '2026-09-05 17:27:48');
INSERT INTO `message_reference` VALUES (200, 560, 455, 134, '。状态为\"已连接\"说明网络与鉴权正常，问题多在主题映射或平台侧订阅；状态为\"重连中\"说明网络或证书有问题，检查设备是否能 ping 通平台域名、证书是否过期、系统时间是否准确。系统时间偏差超过 5 分钟会导致 TLS 握手失败。\n\n### Q13：点位配置能批量导入吗？\n\n可以。在【设备管理】→【点位管理】下载 Excel 模板，按模板填写点位名称、寄存器地址、数据类型、缩放系数、单位等字段后导入。单次导入不超过 5000 行，超出时分批导入', 0.595112, 3, 'Agentic检索', '2026-09-05 17:27:48');
INSERT INTO `message_reference` VALUES (201, 560, 453, 134, '站异常还是个别从站异常\n\n### Q12：数据上云后平台收不到，从哪查起', 0.580170, 4, 'Agentic检索', '2026-09-05 17:27:48');
INSERT INTO `message_reference` VALUES (202, 560, 448, 134, '？\n\n三种方式任选其一：\n\n1. 拨打服务热线 400-820-9600，工作日 8:30 至 20:30，节假日 9:00 至 18:00\n2. 在广联智造官网【服务支持】提交在线工单\n3. 联系对接的销售经理或售后工程师\n\n报修时请提供设备序列号（SN）、故障现象描述、故障发生时间、现场照片或日志文件', 0.576325, 5, 'Agentic检索', '2026-09-05 17:27:48');
INSERT INTO `message_reference` VALUES (212, 608, 267, 135, '. 我方收货后 3 个工作日内完成外观与功能检测\n5. 检测通过后 5 个工作日内办理退款，退款原路返回\n\n检测发现设备存在人为损坏的，退货申请作废，设备寄回客户，运费由客户承担', 0.660440, 1, 'Agentic检索', '2026-09-05 17:41:41');
INSERT INTO `message_reference` VALUES (213, 608, 265, 135, '。\n3. 交付的型号、配置与合同不符，且客户不接受更换的，可退货，全部费用由公司承担', 0.586382, 2, 'Agentic检索', '2026-09-05 17:41:41');
INSERT INTO `message_reference` VALUES (214, 608, 266, 135, '。\n\n（二）不可退货情形\n\n1. 超过到货 15 日\n2. 设备已投入使用并产生磨损、划痕、端子变形\n3. 封条破损、自行拆机\n4. 定制固件或定制硬件配置的设备\n5. 试用转采购的设备（试用期即为验收期）\n6. 促销、清仓、样机特价销售的设备\n\n（三）退货流程\n\n1. 客户提交退货申请，注明设备序列号、采购单号、退货原因，附现场照片\n2. 客户服务中心 2 个工作日内审核并答复\n3. 审核通过后由客户寄回，包装内附退货申请单复印件\n4. 我方收货后 3 个工作日内完成外观与功能检测\n5. 检测', 0.583063, 3, 'Agentic检索', '2026-09-05 17:41:41');
INSERT INTO `message_reference` VALUES (215, 608, 264, 135, '。支持期内按现有库存供应，库存售罄后提供替代方案，包括以旧换新折价或迁移到 GTE-3000 系列。\n\n停产型号的备件不接受退货。\n\n五、退货政策\n\n（一）可退货情形\n\n1. 到货 7 日内，设备未拆封、包装完好、配件齐全，因客户方原因需要退货的，可申请无理由退货，客户承担往返运费，公司不收取折旧费。\n2. 到货 15 日内，经检测确认为设备本身质量问题且无法通过维修解决的，可退货，往返运费由公司承担，货款全额退回', 0.560201, 4, 'Agentic检索', '2026-09-05 17:41:41');
INSERT INTO `message_reference` VALUES (216, 608, 240, 133, '。\n第十二条 附则\n本条款由客户服务中心负责解释，自生效之日起施行，原《售后服务\n条款》（GL-SVC-2022-002）同时废止。', 0.542563, 5, 'Agentic检索', '2026-09-05 17:41:41');
INSERT INTO `message_reference` VALUES (217, 612, 194, 130, '广联智造股份有限公司 差旅与费用报销管理制度\n\n文档编号：GL-FIN-2024-004\n\n版本：V3.5\n\n生效日期：2024 年 9 月 1 日\n\n归口部门：财务部\n\n第一章 总则\n\n第一条 为规范公司差旅与费用报销管理，控制成本、提高效率，制定本制度。本制度适用于公司全体员工因公出差、日常费用垫付及各类费用报销业务。\n\n第二条 报销遵循先审批后支出、实事求是、单据合规三项原则。未经审批发生的费用，公司有权拒绝报销。\n\n第二章 出差管理\n\n第三条 出差前须在 OA 系统提交出差申请，注明出差事由、目的地、起止日期、同行人员、预计费用。审批通过后方可订票。紧急出差可先行前往，但须在出发后 1 个工作日内补交申请。\n\n第四条 出差审批权限：3 天以内由部门负责人审批；3 天以上至 7 天由分管副总审批；7 天以上或出境由总经理审批。\n\n第五条 交通工具标准：\n\n单程飞行时间超过 3 小时或火车运行时间超过 6 小时的，普通员工可申请升舱，需分管副总批准。\n\n第六条 住宿标准（每人每晚，含税）：\n\n超标准住宿需事前申请并说明原因，事后补报的一律按标准上限报销，差额自理。两名同性别员工同行的，鼓励合住标准间，节省部分按每人每晚 50 元给予补贴。\n\n第七条 出差补贴（每人每天）：\n\n出差当日往返不足 8 小时的不发放补贴；客户或合作方已安排餐食的，当餐补贴不予发放。客户现场连续驻场满 5 个工作日的，另按员工手册第十七条发放驻场补贴。\n\n第三章 费用报销\n\n第八条 报销时限：费用发生后 30 日内提交报销单，跨年度费用最迟在次年 1 月 15 日前提交，逾期不予受理。\n\n第九条 单据要求：发票抬头须为公司全称，纳税人识别号准确；增值税专用发票需在开票之日起 360 日内认证；餐费、住宿费须附消费明细；打车费须提供行程单而非仅支付截图。\n\n第十条 报销审批权限：\n\n第十一条 付款周期：每月 10 日、25 日为固定付款日。报销单在付款日前 3 个工作日完成财务审核的，纳入本期付款，否则顺延至下一期。\n\n第十二条 借款管理：单笔预借款不超过预计费用的 80%，出差结束后 10 个工作日内核销。前次借款未核销的，不得再次借款。\n\n第四章 违规处理\n\n第十三条 虚开发票、虚报费用、拆分单据规避审批的，全额追回并按员工手册第三十条按严重违纪处理。\n\n第十四条 财务部每季度抽查报销单据，抽查比例不低于 10%，抽查结果报总经理。\n\n第五章 附则\n\n第十五条 本制度由财务部负责解释，自生效之日起施行。\n\n| 职级 | 飞机 | 火车 | 市内交通 |\n| --- | --- | --- | --- |\n| 总经理及以上 | 公务舱 | 商务座 | 实报实销 |\n| 总监 / 分管副总 | 经济舱 | 一等座 | 实报实销 |\n| 经理 / 主管 | 经济舱 | 二等座 | 每', 0.466713, 1, 'BM25检索+向量检索→重排→父块回填', '2026-09-05 17:42:47');
INSERT INTO `message_reference` VALUES (218, 614, 162, 126, 'GTE 系列网关 现场安装与维护作业指导书\n\n文档编号：GL-OPS-2024-009\n\n版本：V2.6\n\n适用型号：GTE-3000 / GTE-3000S / GTE-3000Pro\n\n编制部门：技术服务部\n\n1. 作业前准备\n\n现场作业前须完成三项确认：一是确认安装位置的环境温度长期不超过 60℃，且远离变频器、大功率接触器等强干扰源；二是确认现场供电为 DC 9V 至 36V，并预留独立空开；三是确认网络条件，有线接入需提前布好网线，4G/5G 接入需确认现场信号强度不低于 -95dBm。\n\n作业工具清单：\n\n2. 安装步骤\n\n1. 断开现场电源，确认电源指示灯熄灭后再进行接线作业。\n\n2. 将网关卡扣对准 DIN 导轨，先挂上沿再向下扣紧，听到卡扣到位声即可；壁挂安装时使用 M4 螺丝固定四角。\n\n3. 接入电源：3 针端子从左到右依次为 V+、V-、PE，PE 必须接柜体接地排，接地电阻不大于 4Ω。\n\n4. 接入 RS485：A 接 A、B 接 B，总线两端启用 120Ω 终端电阻，屏蔽层单端接地', 0.032522, 1, 'BM25检索+向量检索', '2026-09-05 17:43:35');
INSERT INTO `message_reference` VALUES (219, 614, 153, 125, '# GTE-3000 系列工业智能网关 产品技术手册\n\n文档编号：GL-PRD-2024-017\n版本：V3.2\n适用型号：GTE-3000、GTE-3000S、GTE-3000Pro\n发布单位：广联智造股份有限公司 产品部\n\n## 1. 产品概述\n\nGTE-3000 系列是广联智造面向离散制造和流程工业推出的工业智能网关，部署在产线设备与上层系统之间，负责协议转换、边缘计算和数据上云。设备采用无风扇铝合金外壳设计，支持 DIN 导轨安装和壁挂安装两种方式', 0.032266, 2, 'BM25检索+向量检索', '2026-09-05 17:43:35');
INSERT INTO `message_reference` VALUES (220, 614, 161, 125, '。升级过程约 3 ~ 5 分钟，期间采集中断，升级完成后自动重启并恢复原有配置。\n\n## 9. 典型部署方式\n\n**单机部署**：一台 GTE-3000 接入一条产线的 PLC 与仪表，通过 LAN2 接入车间交换机，数据上报到厂级 MES。\n\n**双机热备**：两台 GTE-3000S 通过心跳线互联，主机故障时备机在 5 秒内接管，点位配置由主机自动同步给备机。热备要求两台设备型号、固件版本完全一致。\n\n**级联部署**：车间层用多台 GTE-3000 就近采集，汇聚到一台 GTE-3000Pro 做边缘计算与统一上云，减少公网连接数。\n\n## 10. 选型建议\n\n- 点位少于 500、有有线网络、无边缘计算需求：GTE-3000\n- 点位 500 ~ 3000、现场没有网线、需要 4G 上行：GTE-3000S\n- 点位超过 3000、需要边缘推理或 CNC 设备接入：GTE-3000Pro\n\n三款设备的点位配置格式完全兼容，后期从 GTE-3000 升级到 GTE-3000Pro 时，导出配置直接导入即可，无需重新录入点位。', 0.031054, 3, 'BM25检索+向量检索', '2026-09-05 17:43:35');
INSERT INTO `message_reference` VALUES (221, 614, 261, 135, '。\n\n二、备件目录与价格\n\n常备备件及参考价格（含税，单位：元）：\n\nGTE-3000 主板                    1280\nGTE-3000S 主板                   1860\nGTE-3000Pro 主板                 3450\n24V/2A 工业电源适配器              120\n3 针电源凤凰端子                    15\n串口端子（5 针）                    18\nDIN 导轨卡扣', 0.029857, 4, 'BM25检索+向量检索', '2026-09-05 17:43:36');
INSERT INTO `message_reference` VALUES (222, 614, 457, 134, '。用万用表测量输入电压，低于 9V 时设备会掉电重启，优先排查电源适配器和线路压降。\n2. 环境温度过高。长期高于 60℃ 会触发保护重启，检查安装位置是否靠近热源、机柜是否有散热。\n3. 边缘规则或模型占用内存过高。GTE-3000Pro 同时运行超过 3 个模型时可能触发内存保护，减少模型数量。\n\n### Q16：断网期间的数据会丢吗？\n\n不会立即丢失。断网时数据进入本地缓存，GTE-3000 可缓存 10 万条，GTE-3000S 为 50 万条，GTE-3000Pro 为 500 万条', 0.015873, 5, 'BM25检索', '2026-09-05 17:43:36');
INSERT INTO `message_reference` VALUES (223, 614, 156, 125, '。LAN2 默认为业务口，出厂配置为 DHCP 客户端。GTE-3000S 与 GTE-3000Pro 的 LAN3、LAN4 可配置为交换口，级联下游设备。\n\n管理口 IP 遗忘时，长按 RESET 按钮 10 秒以上，设备恢复出厂设置，管理口 IP 回到 192.168.1.10。恢复出厂设置会清空全部采集点位配置，操作前务必先导出配置文件。\n\n### 3.3 串口\n\nRS485 采用 2 针端子，A、B 两线。串口参数支持 1200 ~ 115200bps，默认 9600bps、8 数据位、1 停止位、无校验。同一条 485 总线上最多挂接 32 个从站，总线两端需接 120Ω 终端电阻，GTE-3000S 与 GTE-3000Pro 内置可通过拨码开关启用的终端电阻。\n\n### 3.4 数字量输入输出\n\nGTE-3000Pro 提供 4 路 DI 和 2 路 DO。DI 为干接点输入，DO 为继电器输出，触点容量 30VDC/2A。DO 常用于联动声光报警器，在采集中断或阈值越限时输出信号', 0.015625, 6, '向量检索', '2026-09-05 17:43:36');
INSERT INTO `message_reference` VALUES (224, 614, 163, 126, '。\n\n5. 接入以太网：LAN1 为管理口，LAN2 为业务口，网线做完后用测试仪确认线序为 T568B。\n\n6. 无线型号安装天线，天线尽量伸出金属柜体，柜内安装会导致信号衰减 10dB 以上。\n\n7. 上电，观察指示灯：PWR 常亮表示供电正常，SYS 每秒闪烁一次表示系统运行正常，COM 闪烁表示串口有数据收发。\n\n3. 调试与验收\n\n笔记本网口配置为 192.168.1.100/24，浏览器访问 https://192.168.1.10 登录 Web 界面，默认账号 admin，默认密码 Gl@2024，首次登录强制修改密码。\n\n依次完成：修改管理口 IP 为现场规划地址、配置业务口网络、添加南向设备与点位、配置北向 MQTT 连接、启动采集组、在运行监控页确认各采集组状态为运行中。\n\n验收标准：\n\n4. 日常维护\n\n月度维护：检查指示灯状态、查看 Web 界面的 CPU 与内存占用是否长期高于 80%、检查存储剩余空间是否低于 20%、导出并归档运行日志。\n\n季度维护：清理设备表面与散热片积灰、复紧电源与串口端子、核对系统时间偏差是否超过 1 分钟、导出一次完整配置文件备份', 0.015625, 7, 'BM25检索', '2026-09-05 17:43:36');
INSERT INTO `message_reference` VALUES (225, 614, 461, 134, '。GTE-3000Pro 另支持部署自定义容器，需签订技术合作协议后由我方开放权限。', 0.015385, 8, '向量检索', '2026-09-05 17:43:36');
INSERT INTO `message_reference` VALUES (226, 616, 162, 126, 'GTE 系列网关 现场安装与维护作业指导书\n\n文档编号：GL-OPS-2024-009\n\n版本：V2.6\n\n适用型号：GTE-3000 / GTE-3000S / GTE-3000Pro\n\n编制部门：技术服务部\n\n1. 作业前准备\n\n现场作业前须完成三项确认：一是确认安装位置的环境温度长期不超过 60℃，且远离变频器、大功率接触器等强干扰源；二是确认现场供电为 DC 9V 至 36V，并预留独立空开；三是确认网络条件，有线接入需提前布好网线，4G/5G 接入需确认现场信号强度不低于 -95dBm。\n\n作业工具清单：\n\n2. 安装步骤\n\n1. 断开现场电源，确认电源指示灯熄灭后再进行接线作业。\n\n2. 将网关卡扣对准 DIN 导轨，先挂上沿再向下扣紧，听到卡扣到位声即可；壁挂安装时使用 M4 螺丝固定四角。\n\n3. 接入电源：3 针端子从左到右依次为 V+、V-、PE，PE 必须接柜体接地排，接地电阻不大于 4Ω。\n\n4. 接入 RS485：A 接 A、B 接 B，总线两端启用 120Ω 终端电阻，屏蔽层单端接地', 0.032522, 1, 'BM25检索+向量检索', '2026-09-05 17:44:30');
INSERT INTO `message_reference` VALUES (227, 616, 153, 125, '# GTE-3000 系列工业智能网关 产品技术手册\n\n文档编号：GL-PRD-2024-017\n版本：V3.2\n适用型号：GTE-3000、GTE-3000S、GTE-3000Pro\n发布单位：广联智造股份有限公司 产品部\n\n## 1. 产品概述\n\nGTE-3000 系列是广联智造面向离散制造和流程工业推出的工业智能网关，部署在产线设备与上层系统之间，负责协议转换、边缘计算和数据上云。设备采用无风扇铝合金外壳设计，支持 DIN 导轨安装和壁挂安装两种方式', 0.032522, 2, 'BM25检索+向量检索', '2026-09-05 17:44:30');
