INSERT INTO `message_reference` VALUES (229, 616, 261, 135, '。\n\n二、备件目录与价格\n\n常备备件及参考价格（含税，单位：元）：\n\nGTE-3000 主板                    1280\nGTE-3000S 主板                   1860\nGTE-3000Pro 主板                 3450\n24V/2A 工业电源适配器              120\n3 针电源凤凰端子                    15\n串口端子（5 针）                    18\nDIN 导轨卡扣', 0.029857, 4, 'BM25检索+向量检索', '2026-09-05 17:44:30');
