INSERT INTO `message_reference` VALUES (234, 618, 194, 130, '广联智造股份有限公司 差旅与费用报销管理制度\n\n文档编号：GL-FIN-2024-004\n\n版本：V3.5\n\n生效日期：2024 年 9 月 1 日\n\n归口部门：财务部\n\n第一章 总则\n\n第一条 为规范公司差旅与费用报销管理，控制成本、提高效率，制定本制度。本制度适用于公司全体员工因公出差、日常费用垫付及各类费用报销业务。\n\n第二条 报销遵循先审批后支出、实事求是、单据合规三项原则。未经审批发生的费用，公司有权拒绝报销。\n\n第二章 出差管理\n\n第三条 出差前须在 OA 系统提交出差申请，注明出差事由、目的地、起止日期、同行人员、预计费用。审批通过后方可订票。紧急出差可先行前往，但须在出发后 1 个工作日内补交申请。\n\n第四条 出差审批权限：3 天以内由部门负责人审批；3 天以上至 7 天由分管副总审批；7 天以上或出境由总经理审批。\n\n第五条 交通工具标准：\n\n单程飞行时间超过 3 小时或火车运行时间超过 6 小时的，普通员工可申请升舱，需分管副总批准。\n\n第六条 住宿标准（每人每晚，含税）：\n\n超标准住宿需事前申请并说明原因，事后补报的一律按标准上限报销，差额自理。两名同性别员工同行的，鼓励合住标准间，节省部分按每人每晚 50 元给予补贴。\n\n第七条 出差补贴（每人每天）：\n\n出差当日往返不足 8 小时的不发放补贴；客户或合作方已安排餐食的，当餐补贴不予发放。客户现场连续驻场满 5 个工作日的，另按员工手册第十七条发放驻场补贴。\n\n第三章 费用报销\n\n第八条 报销时限：费用发生后 30 日内提交报销单，跨年度费用最迟在次年 1 月 15 日前提交，逾期不予受理。\n\n第九条 单据要求：发票抬头须为公司全称，纳税人识别号准确；增值税专用发票需在开票之日起 360 日内认证；餐费、住宿费须附消费明细；打车费须提供行程单而非仅支付截图。\n\n第十条 报销审批权限：\n\n第十一条 付款周期：每月 10 日、25 日为固定付款日。报销单在付款日前 3 个工作日完成财务审核的，纳入本期付款，否则顺延至下一期。\n\n第十二条 借款管理：单笔预借款不超过预计费用的 80%，出差结束后 10 个工作日内核销。前次借款未核销的，不得再次借款。\n\n第四章 违规处理\n\n第十三条 虚开发票、虚报费用、拆分单据规避审批的，全额追回并按员工手册第三十条按严重违纪处理。\n\n第十四条 财务部每季度抽查报销单据，抽查比例不低于 10%，抽查结果报总经理。\n\n第五章 附则\n\n第十五条 本制度由财务部负责解释，自生效之日起施行。\n\n| 职级 | 飞机 | 火车 | 市内交通 |\n| --- | --- | --- | --- |\n| 总经理及以上 | 公务舱 | 商务座 | 实报实销 |\n| 总监 / 分管副总 | 经济舱 | 一等座 | 实报实销 |\n| 经理 / 主管 | 经济舱 | 二等座 | 每', 0.604182, 1, 'BM25检索+向量检索→重排→父块回填', '2026-09-05 17:44:55');
INSERT INTO `message_reference` VALUES (235, 620, 267, 135, '. 我方收货后 3 个工作日内完成外观与功能检测\n5. 检测通过后 5 个工作日内办理退款，退款原路返回\n\n检测发现设备存在人为损坏的，退货申请作废，设备寄回客户，运费由客户承担', 0.628568, 1, 'Agentic检索', '2026-09-05 17:45:45');
INSERT INTO `message_reference` VALUES (236, 620, 266, 135, '。\n\n（二）不可退货情形\n\n1. 超过到货 15 日\n2. 设备已投入使用并产生磨损、划痕、端子变形\n3. 封条破损、自行拆机\n4. 定制固件或定制硬件配置的设备\n5. 试用转采购的设备（试用期即为验收期）\n6. 促销、清仓、样机特价销售的设备\n\n（三）退货流程\n\n1. 客户提交退货申请，注明设备序列号、采购单号、退货原因，附现场照片\n2. 客户服务中心 2 个工作日内审核并答复\n3. 审核通过后由客户寄回，包装内附退货申请单复印件\n4. 我方收货后 3 个工作日内完成外观与功能检测\n5. 检测', 0.559441, 2, 'Agentic检索', '2026-09-05 17:45:45');
INSERT INTO `message_reference` VALUES (237, 620, 265, 135, '。\n3. 交付的型号、配置与合同不符，且客户不接受更换的，可退货，全部费用由公司承担', 0.552811, 3, 'Agentic检索', '2026-09-05 17:45:45');
INSERT INTO `message_reference` VALUES (238, 620, 270, 135, '。\n\n（三）换货流程\n\n1. 提交换货申请，注明原设备序列号与目标型号\n2. 审核通过后，公司先发新设备（需客户提供设备押金或签署《设备返还承诺函》）\n3. 客户收到新设备后 10 个工作日内寄回原设备\n4. 我方检测原设备无人为损坏后，退还押金或解除承诺函\n5. 逾期未寄回的，按新设备原价开票收费\n\n七、返修与退换的包装要求\n\n1. 使用原厂包装箱，无原箱时使用不小于 5 层瓦楞纸的硬质纸箱\n2. 设备四周填充不少于 3 厘米厚的防震材料\n3. 端子、天线等小件单独装袋，避免在运输中划伤主板', 0.520743, 4, 'Agentic检索', '2026-09-05 17:45:45');
INSERT INTO `message_reference` VALUES (239, 620, 264, 135, '。支持期内按现有库存供应，库存售罄后提供替代方案，包括以旧换新折价或迁移到 GTE-3000 系列。\n\n停产型号的备件不接受退货。\n\n五、退货政策\n\n（一）可退货情形\n\n1. 到货 7 日内，设备未拆封、包装完好、配件齐全，因客户方原因需要退货的，可申请无理由退货，客户承担往返运费，公司不收取折旧费。\n2. 到货 15 日内，经检测确认为设备本身质量问题且无法通过维修解决的，可退货，往返运费由公司承担，货款全额退回', 0.520614, 5, 'Agentic检索', '2026-09-05 17:45:45');
INSERT INTO `prompt_template` VALUES (1, 'RAG_ANSWER', '知识库问答', '问答生成', '你是企业知识库助手。请严格根据下面提供的资料回答用户问题。\n资料中没有的内容不要编造，直接回答\"知识库中未找到相关内容\"。\n\n资料：\n{context}\n\n用户问题：{question}', 'context,question', '是', '主问答 Prompt，要求模型不得脱离资料作答。', '2026-09-03 21:09:50', '2026-09-03 21:09:50');
INSERT INTO `prompt_template` VALUES (2, 'QUERY_REWRITE', '多查询扩展', '查询改写', '请把用户问题改写成 {count} 个表述不同但语义一致的检索问题，覆盖可能的同义表达。\n只输出问题本身，每行一个，不要编号。\n\n用户问题：{question}', 'count,question', '是', '用于多路召回前的查询扩展。', '2026-09-03 21:09:50', '2026-09-03 21:09:50');
INSERT INTO `prompt_template` VALUES (3, 'CONTEXT_GRADE', '召回相关性评分', 'Agentic RAG', '判断下面这段资料能否用于回答用户问题。\n只回答\"相关\"或\"不相关\"，不要输出其他内容。\n\n资料：\n{context}\n\n用户问题：{question}', 'context,question', '是', 'LangGraph 中判断是否需要重新检索的节点使用。', '2026-09-03 21:09:50', '2026-09-03 21:09:50');
INSERT INTO `prompt_template` VALUES (4, 'HALLUCINATION_CHECK', '幻觉校验', 'Agentic RAG', '判断下面的回答是否完全由所给资料支撑。\n只回答\"有支撑\"或\"无支撑\"，不要输出其他内容。\n\n资料：\n{context}\n\n回答：\n{answer}', 'context,answer', '是', '生成后校验，无支撑则触发重新生成。', '2026-09-03 21:09:50', '2026-09-03 21:09:50');
INSERT INTO `prompt_template` VALUES (5, 'EVAL_CASE_GEN', '评测问答对生成', '评测集构建', '根据下面的文档片段，生成 {count} 条问答对，用于评测知识库问答效果。\n\n要求：\n1. 问题要具体，答案必须能从某一个片段里直接找到，不要跨片段拼凑。\n2. 每条问答对必须标出答案来自哪个片段，填该片段的编号数字。\n3. ground_truth 只写答案本身，不要解释、不要重复问题。\n\n以 JSON 数组返回，每项包含三个字段：\n  question       问题\n  ground_truth   标准答案\n  source_index   答案所在片段的编号（数字，来自下面的 [片段N]）\n\n示例：\n[{\"question\": \"电源适配器的保修期是多长时间？\", \"ground_truth\": \"12个月\", \"source_index\": 2}]\n\n片段：\n{context}', 'count,context', '是', '按文档片段生成评测用例，要求标出答案来源片段编号，供 Context Recall 做参照', '2026-09-03 21:09:50', '2026-09-06 23:57:23');
INSERT INTO `prompt_template` VALUES (6, 'COREFERENCE_RESOLVE', '多轮指代消解', '查询改写', '下面是一段对话历史，请把用户最后这句话改写成一个不依赖上下文、可以独立理解的完整问题。\n只输出改写后的问题本身，不要输出任何解释。\n\n对话历史：\n{history}\n\n用户最后这句话：{question}', 'history,question', '是', '多轮对话里把\"那它呢\"这类指代补全成完整问题。', '2026-09-03 21:09:50', '2026-09-03 21:09:50');
INSERT INTO `prompt_template` VALUES (7, 'HYDE_ANSWER', 'HyDE假设答案', '查询改写', '请针对下面的问题，用企业文档的书面语气写一段可能的答案。\n不需要保证内容正确，重点是用词和句式要像正式文档。\n控制在 150 字以内，只输出这段文字。\n\n问题：{question}', 'question', '是', '先生成一段假答案，再拿它去检索，答案和答案在语义空间里更接近。', '2026-09-03 21:09:50', '2026-09-03 21:09:50');
INSERT INTO `prompt_template` VALUES (8, 'EVAL_SPLIT_STATEMENTS', '评测拆分陈述句', '效果评测', '请把下面这段文字拆成若干条独立的陈述句，每条只表达一个事实。\n只输出陈述句本身，每行一条，不要编号，不要输出其他内容。\n\n文字：\n{text}', 'text', '是', '算上下文召回和忠实度之前，先把文字拆成一条条可判断的陈述。', '2026-09-03 21:09:50', '2026-09-03 21:09:50');
INSERT INTO `prompt_template` VALUES (9, 'EVAL_JUDGE_SUPPORT', '评测判断是否有支撑', '效果评测', '下面是一段资料和若干条陈述。请逐条判断每条陈述能否由这段资料推出。\n按陈述顺序输出，每行一个\"是\"或\"否\"，不要编号，不要输出其他内容。\n\n资料：\n{context}\n\n陈述：\n{statements}', 'context,statements', '是', '一次判断多条，比逐条调用省很多次模型调用。', '2026-09-03 21:09:50', '2026-09-03 21:09:50');
INSERT INTO `prompt_template` VALUES (10, 'EVAL_JUDGE_RELEVANCE', '评测判断片段相关性', '效果评测', '下面是一个问题和若干段资料。请逐段判断该资料对回答这个问题是否有用。\n按资料顺序输出，每行一个\"是\"或\"否\"，不要编号，不要输出其他内容。\n\n问题：{question}\n\n资料：\n{contexts}', 'question,contexts', '是', '算上下文精度用，判断召回的片段有没有用。', '2026-09-03 21:09:50', '2026-09-03 21:09:50');
INSERT INTO `prompt_template` VALUES (11, 'EVAL_REVERSE_QUESTION', '评测反推问题', '效果评测', '请阅读下面这段回答，推测它最可能是在回答什么问题。\n只输出这个问题本身，不要输出其他内容。\n\n回答：\n{answer}', 'answer', '是', '算答案相关性用，反推出的问题和原问题越接近，说明答案越切题。', '2026-09-03 21:09:50', '2026-09-03 21:09:50');
INSERT INTO `qa_app` VALUES (182, '产品技术助手', 'c6807d313cbb4104', '面向售前和现场工程师，回答 GTE 系列的规格、接口、故障代码、固件升级，以及质保与维修政策问题。', NULL, 1, 2, 'RAG_ANSWER', '否', 6, '知识库中未找到相关内容。', '否', '正常', 1, '2026-09-04 03:41:09', '2026-09-04 11:42:36');
INSERT INTO `qa_app` VALUES (183, '企业制度问答', '3767c6cd09c94651', '面向全体员工，回答考勤请假、差旅报销、信息安全等制度条款问题。', NULL, 1, 3, 'RAG_ANSWER', '否', 8, '现行制度里没有查到相关条款，请联系人力资源部确认。', '否', '正常', 1, '2026-09-04 03:41:09', '2026-09-04 03:41:09');
INSERT INTO `qa_app` VALUES (184, '售后智能客服', '733a379af85246a4', '面向客服坐席和客户，回答质保、维修、备件与退换货问题，走 Agentic 链路自行判断要不要重新检索。', NULL, 1, 2, 'RAG_ANSWER', '是', 6, '这个问题在售后知识库里没有查到，请转接人工客服 400-820-9600。', '否', '正常', 1, '2026-09-04 03:41:09', '2026-09-04 03:41:09');
