INSERT INTO `tool_call_log` VALUES (37, NULL, NULL, 'search_knowledge', '知识库检索', '{\"query\": \"设备报 ERR-5021 该怎么处理？\", \"kb_id\": 208, \"top_k\": 5}', NULL, '失败', '连不上向量库，请确认 PostgreSQL 已启动：Psycopg cannot use the \'ProactorEventLoop\' to run in async mode. Please use a compatible event loop, for instance by running \'asyncio.run(..., loop_factory=asyncio.SelectorEventLoop(selectors.SelectSe', 1640, '2026-09-05 17:26:48');
INSERT INTO `tool_call_log` VALUES (38, NULL, NULL, 'search_knowledge', '知识库检索', '{\"query\": \"设备报 ERR-5021 该怎么处理？\", \"kb_id\": 208, \"top_k\": 5}', '{\"count\": 5, \"results\": [{\"chunk_id\": 456, \"document_id\": 134, \"score\": 0.829305, \"content\": \"。单次导入不超过 5000 行，超出时分批导入。导入前系统会做格式校验，校验不通过的行会标红并给出原因，修正后重新导入。\\n\\n## 四、故障与告警\\n\\n### Q14：设备报 ERR-5021 是什么意思？\\n\\nERR-5021 是点位配置与协议栈不兼容，常见于跨大版本升级固件之后。处理方式是回退到升级前的固件版本，按《固件升级与版本发布说明》先升到过渡版本再升级目标版本。\\n\\n### Q15：设备频繁重启是什么原因？\\n\\n最常见的三个原因：\\n\\n1. 供电不稳\"}, {\"chunk_id\": 450, \"document_id\": 134, \"score\": 0.603541, \"content\": \"。备机为同型号或更高型号，借用期间的配置由我方工程师协助导入。逾期未归还的按设备原价的 1% 每日收取占用费。\\n\\n## 三、安装与调试\\n\\n### Q10：设备管理口 IP 忘了怎么办？\\n\\n长按设备面板 RESET 按钮 10 秒以上，设备恢复出厂设置，管理口 IP 恢复为 192.168.1.10，默认账号 admin，默认密码 Gl@2024。恢复出厂会清空全部点位配置，请务必先尝试其他方式找回，例如用网络扫描工具在网段内查找设备 MAC 前缀 8C:1F:64 的主机\"}, {\"chunk_id\": 455, \"document_id\": 134, \"score\": 0.595112, \"content\": \"。状态为\\\"已连接\\\"说明网络与鉴权正常，问题多在主题映射或平台侧订阅；状态为\\\"重连中\\\"说明网络或证书有问题，检查设备是否能 ping 通平台域名、证书是否过期、系统时间是否准确。系统时间偏差超过 5 分钟会导致 TLS 握手失败。\\n\\n### Q13：点位配置能批量导入吗？\\n\\n可以。在【设备管理】→【点位管理】下载 Excel 模板，按模板填写点位名称、寄存器地址、数据类型、缩放系数、单位等字段后导入。单次导入不超过 5000 行，超出时分批导入\"}, {\"chunk_id\": 453, \"document_id\": 134, \"score\": 0.58017, \"content\": \"站异常还是个别从站异常\\n\\n### Q12：数据上云后平台收不到，从哪查起\"}, {\"chunk_id\": 448, \"document_id\": 134, \"score\": 0.576325, \"content\": \"？\\n\\n三种方式任选其一：\\n\\n1. 拨打服务热线 400-820-9600，工作日 8:30 至 20:30，节假日 9:00 至 18:00\\n2. 在广联智造官网【服务支持】提交在线工单\\n3. 联系对接的销售经理或售后工程师\\n\\n报修时请提供设备序列号（SN）、故障现象描述、故障发生时间、现场照片或日志文件\"}]}', '成功', NULL, 1582, '2026-09-05 17:27:45');
INSERT INTO `tool_call_log` VALUES (39, NULL, NULL, 'search_knowledge', '知识库检索', '{\"query\": \"把 GTE-3000、GTE-3000S、GTE-3000Pro 三个型号的差异完整列出来，包括处理器、内存、接口、无线和点位上限。\", \"kb_id\": 208, \"top_k\": 5}', '{\"count\": 5, \"results\": [{\"chunk_id\": 460, \"document_id\": 134, \"score\": 0.743315, \"content\": \"。认证证书可向销售经理索取电子版。\\n\\n### Q21：老型号 GTE-2000 还能买到吗？\\n\\nGTE-2000 已于 2023 年 12 月停产，目前仅提供备件与维修支持，支持期至 2026 年 12 月。新项目建议直接选用 GTE-3000 系列，点位配置文件可通过转换工具从 GTE-2000 迁移。\\n\\n### Q22：能提供二次开发接口吗？\\n\\n可以。设备提供 RESTful API 与 OPC UA Server 两种对接方式，API 文档可在官网【开发者】板块下载\"}, {\"chunk_id\": 261, \"document_id\": 135, \"score\": 0.735164, \"content\": \"。\\n\\n二、备件目录与价格\\n\\n常备备件及参考价格（含税，单位：元）：\\n\\nGTE-3000 主板                    1280\\nGTE-3000S 主板                   1860\\nGTE-3000Pro 主板                 3450\\n24V/2A 工业电源适配器              120\\n3 针电源凤凰端子                    15\\n串口端子（5 针）                    18\\nDIN 导轨卡扣\"}, {\"chunk_id\": 461, \"document_id\": 134, \"score\": 0.727452, \"content\": \"。GTE-3000Pro 另支持部署自定义容器，需签订技术合作协议后由我方开放权限。\"}, {\"chunk_id\": 444, \"document_id\": 134, \"score\": 0.703726, \"content\": \"。批量订单超过 100 台的，交货周期另行确认。\\n\\n### Q2：设备发货包含哪些配件？\\n\\n标准包装内含：网关主机 1 台、24V/2A 电源适配器 1 个、DIN 导轨卡扣 1 套、3 针电源端子 1 个、串口端子 2 个（GTE-3000S 与 GTE-3000Pro 为 4 个）、快速入门指南 1 份、合格证 1 张。天线为选配件，4G/5G 型号默认随机附送吸盘天线 1 根。\\n\\n### Q3：可以先试用再采购吗？\\n\\n支持。意向客户可申请 30 天试用，需提交试用申请单并由销售经理审批\"}, {\"chunk_id\": 268, \"document_id\": 135, \"score\": 0.702362, \"content\": \"。\\n\\n六、换货政策\\n\\n（一）质保期内的换货\\n\\n设备在质保期内出现同一故障且经过两次维修仍未解决的，可申请换货。换新设备的质保期按原设备剩余质保期计算，剩余不足 3 个月的按 3 个月计。\\n\\n到货 30 日内出现非人为的功能性故障的，可直接申请换新，不必先走维修。\\n\\n（二）型号升级换货\\n\\n采购后 90 日内，因项目需求变更需要升级到更高型号的（如 GTE-3000 换 GTE-3000S），可申请补差价换货。补差金额 = 新型号价格 - 原型号价格 × 0.9，其中 0.9 为使用折旧系数\"}]}', '成功', NULL, 1502, '2026-09-05 17:28:23');
INSERT INTO `tool_call_log` VALUES (40, NULL, NULL, 'search_knowledge', '知识库检索', '{\"query\": \"请完整对比GTE-3000系列三款机型（基础版、S版、Pro版）的芯片型号、运行内存、物理接口类型、无线通信规格以及可接入的终端点位上限\", \"kb_id\": 208, \"top_k\": 5}', '{\"count\": 5, \"results\": [{\"chunk_id\": 461, \"document_id\": 134, \"score\": 0.733603, \"content\": \"。GTE-3000Pro 另支持部署自定义容器，需签订技术合作协议后由我方开放权限。\"}, {\"chunk_id\": 460, \"document_id\": 134, \"score\": 0.709467, \"content\": \"。认证证书可向销售经理索取电子版。\\n\\n### Q21：老型号 GTE-2000 还能买到吗？\\n\\nGTE-2000 已于 2023 年 12 月停产，目前仅提供备件与维修支持，支持期至 2026 年 12 月。新项目建议直接选用 GTE-3000 系列，点位配置文件可通过转换工具从 GTE-2000 迁移。\\n\\n### Q22：能提供二次开发接口吗？\\n\\n可以。设备提供 RESTful API 与 OPC UA Server 两种对接方式，API 文档可在官网【开发者】板块下载\"}, {\"chunk_id\": 444, \"document_id\": 134, \"score\": 0.694215, \"content\": \"。批量订单超过 100 台的，交货周期另行确认。\\n\\n### Q2：设备发货包含哪些配件？\\n\\n标准包装内含：网关主机 1 台、24V/2A 电源适配器 1 个、DIN 导轨卡扣 1 套、3 针电源端子 1 个、串口端子 2 个（GTE-3000S 与 GTE-3000Pro 为 4 个）、快速入门指南 1 份、合格证 1 张。天线为选配件，4G/5G 型号默认随机附送吸盘天线 1 根。\\n\\n### Q3：可以先试用再采购吗？\\n\\n支持。意向客户可申请 30 天试用，需提交试用申请单并由销售经理审批\"}, {\"chunk_id\": 261, \"document_id\": 135, \"score\": 0.683601, \"content\": \"。\\n\\n二、备件目录与价格\\n\\n常备备件及参考价格（含税，单位：元）：\\n\\nGTE-3000 主板                    1280\\nGTE-3000S 主板                   1860\\nGTE-3000Pro 主板                 3450\\n24V/2A 工业电源适配器              120\\n3 针电源凤凰端子                    15\\n串口端子（5 针）                    18\\nDIN 导轨卡扣\"}, {\"chunk_id\": 457, \"document_id\": 134, \"score\": 0.662574, \"content\": \"。用万用表测量输入电压，低于 9V 时设备会掉电重启，优先排查电源适配器和线路压降。\\n2. 环境温度过高。长期高于 60℃ 会触发保护重启，检查安装位置是否靠近热源、机柜是否有散热。\\n3. 边缘规则或模型占用内存过高。GTE-3000Pro 同时运行超过 3 个模型时可能触发内存保护，减少模型数量。\\n\\n### Q16：断网期间的数据会丢吗？\\n\\n不会立即丢失。断网时数据进入本地缓存，GTE-3000 可缓存 10 万条，GTE-3000S 为 50 万条，GTE-3000Pro 为 500 万条\"}]}', '成功', NULL, 393, '2026-09-05 17:28:27');
INSERT INTO `tool_call_log` VALUES (41, NULL, NULL, 'search_knowledge', '知识库检索', '{\"query\": \"请完整对比GTE-3000系列三款机型（基础版、S版、Pro版）的芯片型号、运行内存、物理接口类型、无线通信规格以及可接入的终端点位上限\", \"kb_id\": 208, \"top_k\": 5}', '{\"count\": 5, \"results\": [{\"chunk_id\": 461, \"document_id\": 134, \"score\": 0.733603, \"content\": \"。GTE-3000Pro 另支持部署自定义容器，需签订技术合作协议后由我方开放权限。\"}, {\"chunk_id\": 460, \"document_id\": 134, \"score\": 0.709467, \"content\": \"。认证证书可向销售经理索取电子版。\\n\\n### Q21：老型号 GTE-2000 还能买到吗？\\n\\nGTE-2000 已于 2023 年 12 月停产，目前仅提供备件与维修支持，支持期至 2026 年 12 月。新项目建议直接选用 GTE-3000 系列，点位配置文件可通过转换工具从 GTE-2000 迁移。\\n\\n### Q22：能提供二次开发接口吗？\\n\\n可以。设备提供 RESTful API 与 OPC UA Server 两种对接方式，API 文档可在官网【开发者】板块下载\"}, {\"chunk_id\": 444, \"document_id\": 134, \"score\": 0.694215, \"content\": \"。批量订单超过 100 台的，交货周期另行确认。\\n\\n### Q2：设备发货包含哪些配件？\\n\\n标准包装内含：网关主机 1 台、24V/2A 电源适配器 1 个、DIN 导轨卡扣 1 套、3 针电源端子 1 个、串口端子 2 个（GTE-3000S 与 GTE-3000Pro 为 4 个）、快速入门指南 1 份、合格证 1 张。天线为选配件，4G/5G 型号默认随机附送吸盘天线 1 根。\\n\\n### Q3：可以先试用再采购吗？\\n\\n支持。意向客户可申请 30 天试用，需提交试用申请单并由销售经理审批\"}, {\"chunk_id\": 261, \"document_id\": 135, \"score\": 0.683601, \"content\": \"。\\n\\n二、备件目录与价格\\n\\n常备备件及参考价格（含税，单位：元）：\\n\\nGTE-3000 主板                    1280\\nGTE-3000S 主板                   1860\\nGTE-3000Pro 主板                 3450\\n24V/2A 工业电源适配器              120\\n3 针电源凤凰端子                    15\\n串口端子（5 针）                    18\\nDIN 导轨卡扣\"}, {\"chunk_id\": 457, \"document_id\": 134, \"score\": 0.662574, \"content\": \"。用万用表测量输入电压，低于 9V 时设备会掉电重启，优先排查电源适配器和线路压降。\\n2. 环境温度过高。长期高于 60℃ 会触发保护重启，检查安装位置是否靠近热源、机柜是否有散热。\\n3. 边缘规则或模型占用内存过高。GTE-3000Pro 同时运行超过 3 个模型时可能触发内存保护，减少模型数量。\\n\\n### Q16：断网期间的数据会丢吗？\\n\\n不会立即丢失。断网时数据进入本地缓存，GTE-3000 可缓存 10 万条，GTE-3000S 为 50 万条，GTE-3000Pro 为 500 万条\"}]}', '成功', NULL, 310, '2026-09-05 17:28:30');
INSERT INTO `tool_call_log` VALUES (42, NULL, NULL, 'search_knowledge', '知识库检索', '{\"query\": \"把 GTE-3000、GTE-3000S、GTE-3000Pro 三个型号的差异完整列出来，包括处理器、内存、接口、无线和点位上限。\", \"kb_id\": 208, \"top_k\": 5}', '{\"count\": 5, \"results\": [{\"chunk_id\": 460, \"document_id\": 134, \"score\": 0.743315, \"content\": \"。认证证书可向销售经理索取电子版。\\n\\n### Q21：老型号 GTE-2000 还能买到吗？\\n\\nGTE-2000 已于 2023 年 12 月停产，目前仅提供备件与维修支持，支持期至 2026 年 12 月。新项目建议直接选用 GTE-3000 系列，点位配置文件可通过转换工具从 GTE-2000 迁移。\\n\\n### Q22：能提供二次开发接口吗？\\n\\n可以。设备提供 RESTful API 与 OPC UA Server 两种对接方式，API 文档可在官网【开发者】板块下载\"}, {\"chunk_id\": 261, \"document_id\": 135, \"score\": 0.735164, \"content\": \"。\\n\\n二、备件目录与价格\\n\\n常备备件及参考价格（含税，单位：元）：\\n\\nGTE-3000 主板                    1280\\nGTE-3000S 主板                   1860\\nGTE-3000Pro 主板                 3450\\n24V/2A 工业电源适配器              120\\n3 针电源凤凰端子                    15\\n串口端子（5 针）                    18\\nDIN 导轨卡扣\"}, {\"chunk_id\": 461, \"document_id\": 134, \"score\": 0.727452, \"content\": \"。GTE-3000Pro 另支持部署自定义容器，需签订技术合作协议后由我方开放权限。\"}, {\"chunk_id\": 444, \"document_id\": 134, \"score\": 0.703726, \"content\": \"。批量订单超过 100 台的，交货周期另行确认。\\n\\n### Q2：设备发货包含哪些配件？\\n\\n标准包装内含：网关主机 1 台、24V/2A 电源适配器 1 个、DIN 导轨卡扣 1 套、3 针电源端子 1 个、串口端子 2 个（GTE-3000S 与 GTE-3000Pro 为 4 个）、快速入门指南 1 份、合格证 1 张。天线为选配件，4G/5G 型号默认随机附送吸盘天线 1 根。\\n\\n### Q3：可以先试用再采购吗？\\n\\n支持。意向客户可申请 30 天试用，需提交试用申请单并由销售经理审批\"}, {\"chunk_id\": 268, \"document_id\": 135, \"score\": 0.702362, \"content\": \"。\\n\\n六、换货政策\\n\\n（一）质保期内的换货\\n\\n设备在质保期内出现同一故障且经过两次维修仍未解决的，可申请换货。换新设备的质保期按原设备剩余质保期计算，剩余不足 3 个月的按 3 个月计。\\n\\n到货 30 日内出现非人为的功能性故障的，可直接申请换新，不必先走维修。\\n\\n（二）型号升级换货\\n\\n采购后 90 日内，因项目需求变更需要升级到更高型号的（如 GTE-3000 换 GTE-3000S），可申请补差价换货。补差金额 = 新型号价格 - 原型号价格 × 0.9，其中 0.9 为使用折旧系数\"}]}', '成功', NULL, 1559, '2026-09-05 17:33:57');
