INSERT INTO `tool_call_log` VALUES (45, NULL, NULL, 'list_documents', '文档清单查询', '{\"kb_id\": 999999}', '{\"count\": 0, \"documents\": []}', '成功', NULL, 0, '2026-09-05 17:35:29');
INSERT INTO `tool_call_log` VALUES (46, NULL, NULL, 'get_document_detail', '文档详情查询', '{\"document_id\": 999999}', NULL, '失败', '未找到文档', 0, '2026-09-05 17:35:29');
INSERT INTO `tool_call_log` VALUES (47, NULL, NULL, 'search_knowledge', '知识库检索', '{\"query\": \"你们售后退款是如何处理的？\", \"kb_id\": 208, \"top_k\": 5}', '{\"count\": 5, \"results\": [{\"chunk_id\": 267, \"document_id\": 135, \"score\": 0.66044, \"content\": \". 我方收货后 3 个工作日内完成外观与功能检测\\n5. 检测通过后 5 个工作日内办理退款，退款原路返回\\n\\n检测发现设备存在人为损坏的，退货申请作废，设备寄回客户，运费由客户承担\"}, {\"chunk_id\": 265, \"document_id\": 135, \"score\": 0.586382, \"content\": \"。\\n3. 交付的型号、配置与合同不符，且客户不接受更换的，可退货，全部费用由公司承担\"}, {\"chunk_id\": 266, \"document_id\": 135, \"score\": 0.583063, \"content\": \"。\\n\\n（二）不可退货情形\\n\\n1. 超过到货 15 日\\n2. 设备已投入使用并产生磨损、划痕、端子变形\\n3. 封条破损、自行拆机\\n4. 定制固件或定制硬件配置的设备\\n5. 试用转采购的设备（试用期即为验收期）\\n6. 促销、清仓、样机特价销售的设备\\n\\n（三）退货流程\\n\\n1. 客户提交退货申请，注明设备序列号、采购单号、退货原因，附现场照片\\n2. 客户服务中心 2 个工作日内审核并答复\\n3. 审核通过后由客户寄回，包装内附退货申请单复印件\\n4. 我方收货后 3 个工作日内完成外观与功能检测\\n5. 检测\"}, {\"chunk_id\": 264, \"document_id\": 135, \"score\": 0.560201, \"content\": \"。支持期内按现有库存供应，库存售罄后提供替代方案，包括以旧换新折价或迁移到 GTE-3000 系列。\\n\\n停产型号的备件不接受退货。\\n\\n五、退货政策\\n\\n（一）可退货情形\\n\\n1. 到货 7 日内，设备未拆封、包装完好、配件齐全，因客户方原因需要退货的，可申请无理由退货，客户承担往返运费，公司不收取折旧费。\\n2. 到货 15 日内，经检测确认为设备本身质量问题且无法通过维修解决的，可退货，往返运费由公司承担，货款全额退回\"}, {\"chunk_id\": 240, \"document_id\": 133, \"score\": 0.542563, \"content\": \"。\\n第十二条 附则\\n本条款由客户服务中心负责解释，自生效之日起施行，原《售后服务\\n条款》（GL-SVC-2022-002）同时废止。\"}]}', '成功', NULL, 1617, '2026-09-05 17:41:34');
INSERT INTO `tool_call_log` VALUES (48, NULL, NULL, 'search_knowledge', '知识库检索', '{\"query\": \"你们售后退款都是怎么操作的？\", \"kb_id\": 208, \"top_k\": 5}', '{\"count\": 5, \"results\": [{\"chunk_id\": 267, \"document_id\": 135, \"score\": 0.628568, \"content\": \". 我方收货后 3 个工作日内完成外观与功能检测\\n5. 检测通过后 5 个工作日内办理退款，退款原路返回\\n\\n检测发现设备存在人为损坏的，退货申请作废，设备寄回客户，运费由客户承担\"}, {\"chunk_id\": 266, \"document_id\": 135, \"score\": 0.559441, \"content\": \"。\\n\\n（二）不可退货情形\\n\\n1. 超过到货 15 日\\n2. 设备已投入使用并产生磨损、划痕、端子变形\\n3. 封条破损、自行拆机\\n4. 定制固件或定制硬件配置的设备\\n5. 试用转采购的设备（试用期即为验收期）\\n6. 促销、清仓、样机特价销售的设备\\n\\n（三）退货流程\\n\\n1. 客户提交退货申请，注明设备序列号、采购单号、退货原因，附现场照片\\n2. 客户服务中心 2 个工作日内审核并答复\\n3. 审核通过后由客户寄回，包装内附退货申请单复印件\\n4. 我方收货后 3 个工作日内完成外观与功能检测\\n5. 检测\"}, {\"chunk_id\": 265, \"document_id\": 135, \"score\": 0.552811, \"content\": \"。\\n3. 交付的型号、配置与合同不符，且客户不接受更换的，可退货，全部费用由公司承担\"}, {\"chunk_id\": 270, \"document_id\": 135, \"score\": 0.520743, \"content\": \"。\\n\\n（三）换货流程\\n\\n1. 提交换货申请，注明原设备序列号与目标型号\\n2. 审核通过后，公司先发新设备（需客户提供设备押金或签署《设备返还承诺函》）\\n3. 客户收到新设备后 10 个工作日内寄回原设备\\n4. 我方检测原设备无人为损坏后，退还押金或解除承诺函\\n5. 逾期未寄回的，按新设备原价开票收费\\n\\n七、返修与退换的包装要求\\n\\n1. 使用原厂包装箱，无原箱时使用不小于 5 层瓦楞纸的硬质纸箱\\n2. 设备四周填充不少于 3 厘米厚的防震材料\\n3. 端子、天线等小件单独装袋，避免在运输中划伤主板\"}, {\"chunk_id\": 264, \"document_id\": 135, \"score\": 0.520614, \"content\": \"。支持期内按现有库存供应，库存售罄后提供替代方案，包括以旧换新折价或迁移到 GTE-3000 系列。\\n\\n停产型号的备件不接受退货。\\n\\n五、退货政策\\n\\n（一）可退货情形\\n\\n1. 到货 7 日内，设备未拆封、包装完好、配件齐全，因客户方原因需要退货的，可申请无理由退货，客户承担往返运费，公司不收取折旧费。\\n2. 到货 15 日内，经检测确认为设备本身质量问题且无法通过维修解决的，可退货，往返运费由公司承担，货款全额退回\"}]}', '成功', NULL, 397, '2026-09-05 17:45:41');
INSERT INTO `tool_call_log` VALUES (49, NULL, NULL, 'search_knowledge', '知识库检索', '{\"query\": \"11\", \"kb_id\": 208, \"top_k\": 5}', '{\"count\": 5, \"results\": [{\"chunk_id\": 454, \"document_id\": 134, \"score\": 0.367531, \"content\": \"？\\n\\n先在【数据转发】页面看连接状态\"}, {\"chunk_id\": 460, \"document_id\": 134, \"score\": 0.365061, \"content\": \"。认证证书可向销售经理索取电子版。\\n\\n### Q21：老型号 GTE-2000 还能买到吗？\\n\\nGTE-2000 已于 2023 年 12 月停产，目前仅提供备件与维修支持，支持期至 2026 年 12 月。新项目建议直接选用 GTE-3000 系列，点位配置文件可通过转换工具从 GTE-2000 迁移。\\n\\n### Q22：能提供二次开发接口吗？\\n\\n可以。设备提供 RESTful API 与 OPC UA Server 两种对接方式，API 文档可在官网【开发者】板块下载\"}, {\"chunk_id\": 267, \"document_id\": 135, \"score\": 0.363334, \"content\": \". 我方收货后 3 个工作日内完成外观与功能检测\\n5. 检测通过后 5 个工作日内办理退款，退款原路返回\\n\\n检测发现设备存在人为损坏的，退货申请作废，设备寄回客户，运费由客户承担\"}, {\"chunk_id\": 450, \"document_id\": 134, \"score\": 0.354574, \"content\": \"。备机为同型号或更高型号，借用期间的配置由我方工程师协助导入。逾期未归还的按设备原价的 1% 每日收取占用费。\\n\\n## 三、安装与调试\\n\\n### Q10：设备管理口 IP 忘了怎么办？\\n\\n长按设备面板 RESET 按钮 10 秒以上，设备恢复出厂设置，管理口 IP 恢复为 192.168.1.10，默认账号 admin，默认密码 Gl@2024。恢复出厂会清空全部点位配置，请务必先尝试其他方式找回，例如用网络扫描工具在网段内查找设备 MAC 前缀 8C:1F:64 的主机\"}, {\"chunk_id\": 461, \"document_id\": 134, \"score\": 0.344752, \"content\": \"。GTE-3000Pro 另支持部署自定义容器，需签订技术合作协议后由我方开放权限。\"}]}', '成功', NULL, 385, '2026-09-05 17:46:10');
INSERT INTO `tool_call_log` VALUES (50, NULL, NULL, 'search_knowledge', '知识库检索', '{\"query\": \"十一\", \"kb_id\": 208, \"top_k\": 5}', '{\"count\": 5, \"results\": [{\"chunk_id\": 446, \"document_id\": 134, \"score\": 0.29545, \"content\": \"。电源适配器、天线等配件的保修期为 12 个月。质保期以设备铭牌上的出厂日期为准，客户能提供有效购买凭证的，可按购买日期顺延，最长顺延 3 个月\"}, {\"chunk_id\": 267, \"document_id\": 135, \"score\": 0.275725, \"content\": \". 我方收货后 3 个工作日内完成外观与功能检测\\n5. 检测通过后 5 个工作日内办理退款，退款原路返回\\n\\n检测发现设备存在人为损坏的，退货申请作废，设备寄回客户，运费由客户承担\"}, {\"chunk_id\": 450, \"document_id\": 134, \"score\": 0.26953, \"content\": \"。备机为同型号或更高型号，借用期间的配置由我方工程师协助导入。逾期未归还的按设备原价的 1% 每日收取占用费。\\n\\n## 三、安装与调试\\n\\n### Q10：设备管理口 IP 忘了怎么办？\\n\\n长按设备面板 RESET 按钮 10 秒以上，设备恢复出厂设置，管理口 IP 恢复为 192.168.1.10，默认账号 admin，默认密码 Gl@2024。恢复出厂会清空全部点位配置，请务必先尝试其他方式找回，例如用网络扫描工具在网段内查找设备 MAC 前缀 8C:1F:64 的主机\"}, {\"chunk_id\": 234, \"document_id\": 133, \"score\": 0.269081, \"content\": \"。\\n第三条 免费保修范围\\n质保期内，因设计、材料、制造工艺缺陷导致的功能性故障，公司提\\n供免费维修或更换，包括但不限于：主板元器件失效、接口虚焊、电\\n源模块异常、无线模组不识别、存储芯片写入失败。\\n第四条 不属于免费保修的情形\\n一、超出质量保证期。\\n二、未按产品手册要求使用，例如输入电压超出 DC 9V 至 36V 范围、\\n\\n【第 2 页】\\n环境温度长期超过 70℃、未做接地导致的通信板损坏。\\n三、客户自行拆机、改装，或设备封条破损。\\n四、水浸、火灾、雷击、地震、电涌等不可抗力造成的损坏\"}, {\"chunk_id\": 455, \"document_id\": 134, \"score\": 0.258112, \"content\": \"。状态为\\\"已连接\\\"说明网络与鉴权正常，问题多在主题映射或平台侧订阅；状态为\\\"重连中\\\"说明网络或证书有问题，检查设备是否能 ping 通平台域名、证书是否过期、系统时间是否准确。系统时间偏差超过 5 分钟会导致 TLS 握手失败。\\n\\n### Q13：点位配置能批量导入吗？\\n\\n可以。在【设备管理】→【点位管理】下载 Excel 模板，按模板填写点位名称、寄存器地址、数据类型、缩放系数、单位等字段后导入。单次导入不超过 5000 行，超出时分批导入\"}]}', '成功', NULL, 297, '2026-09-05 17:46:11');
INSERT INTO `tool_call_log` VALUES (51, NULL, NULL, 'search_knowledge', '知识库检索', '{\"query\": \"十一\", \"kb_id\": 208, \"top_k\": 5}', '{\"count\": 5, \"results\": [{\"chunk_id\": 446, \"document_id\": 134, \"score\": 0.29545, \"content\": \"。电源适配器、天线等配件的保修期为 12 个月。质保期以设备铭牌上的出厂日期为准，客户能提供有效购买凭证的，可按购买日期顺延，最长顺延 3 个月\"}, {\"chunk_id\": 267, \"document_id\": 135, \"score\": 0.275725, \"content\": \". 我方收货后 3 个工作日内完成外观与功能检测\\n5. 检测通过后 5 个工作日内办理退款，退款原路返回\\n\\n检测发现设备存在人为损坏的，退货申请作废，设备寄回客户，运费由客户承担\"}, {\"chunk_id\": 450, \"document_id\": 134, \"score\": 0.26953, \"content\": \"。备机为同型号或更高型号，借用期间的配置由我方工程师协助导入。逾期未归还的按设备原价的 1% 每日收取占用费。\\n\\n## 三、安装与调试\\n\\n### Q10：设备管理口 IP 忘了怎么办？\\n\\n长按设备面板 RESET 按钮 10 秒以上，设备恢复出厂设置，管理口 IP 恢复为 192.168.1.10，默认账号 admin，默认密码 Gl@2024。恢复出厂会清空全部点位配置，请务必先尝试其他方式找回，例如用网络扫描工具在网段内查找设备 MAC 前缀 8C:1F:64 的主机\"}, {\"chunk_id\": 234, \"document_id\": 133, \"score\": 0.269081, \"content\": \"。\\n第三条 免费保修范围\\n质保期内，因设计、材料、制造工艺缺陷导致的功能性故障，公司提\\n供免费维修或更换，包括但不限于：主板元器件失效、接口虚焊、电\\n源模块异常、无线模组不识别、存储芯片写入失败。\\n第四条 不属于免费保修的情形\\n一、超出质量保证期。\\n二、未按产品手册要求使用，例如输入电压超出 DC 9V 至 36V 范围、\\n\\n【第 2 页】\\n环境温度长期超过 70℃、未做接地导致的通信板损坏。\\n三、客户自行拆机、改装，或设备封条破损。\\n四、水浸、火灾、雷击、地震、电涌等不可抗力造成的损坏\"}, {\"chunk_id\": 455, \"document_id\": 134, \"score\": 0.258112, \"content\": \"。状态为\\\"已连接\\\"说明网络与鉴权正常，问题多在主题映射或平台侧订阅；状态为\\\"重连中\\\"说明网络或证书有问题，检查设备是否能 ping 通平台域名、证书是否过期、系统时间是否准确。系统时间偏差超过 5 分钟会导致 TLS 握手失败。\\n\\n### Q13：点位配置能批量导入吗？\\n\\n可以。在【设备管理】→【点位管理】下载 Excel 模板，按模板填写点位名称、寄存器地址、数据类型、缩放系数、单位等字段后导入。单次导入不超过 5000 行，超出时分批导入\"}]}', '成功', NULL, 345, '2026-09-05 17:46:12');
