-- ----------------------------
-- Table structure for agent_run
-- ----------------------------
DROP TABLE IF EXISTS `agent_run`;
CREATE TABLE `agent_run`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '运行ID',
  `run_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '运行编号',
  `app_id` int NULL DEFAULT NULL COMMENT '所属问答应用ID',
  `session_id` int NULL DEFAULT NULL COMMENT '所属会话ID',
  `message_id` int NULL DEFAULT NULL COMMENT '关联的回答消息ID',
  `user_id` int NULL DEFAULT NULL COMMENT '触发用户ID',
  `run_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '运行类型：Agentic问答、评测执行',
  `run_status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '运行中' COMMENT '运行状态：运行中、已完成、运行失败',
  `current_step` int NOT NULL DEFAULT 0 COMMENT '当前步数',
  `total_step` int NOT NULL DEFAULT 0 COMMENT '总步数',
  `retrieve_count` int NOT NULL DEFAULT 0 COMMENT '实际检索次数，用于校验Agent是否真的检索过',
  `rewrite_count` int NOT NULL DEFAULT 0 COMMENT '查询改写次数',
  `input_snapshot` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '入参快照',
  `output_summary` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '最终结论',
  `error_message` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '失败原因',
  `start_time` datetime NULL DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime NULL DEFAULT NULL COMMENT '结束时间',
  `cost_millis` bigint NULL DEFAULT NULL COMMENT '耗时（毫秒）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_agent_run_no`(`run_no` ASC) USING BTREE,
  INDEX `idx_agent_run_session`(`session_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 210 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'Agent运行记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of agent_run
-- ----------------------------

-- ----------------------------
-- Table structure for agent_step
-- ----------------------------
DROP TABLE IF EXISTS `agent_step`;
CREATE TABLE `agent_step`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '步骤ID',
  `run_id` int NOT NULL COMMENT '所属运行ID',
  `step_index` int NOT NULL DEFAULT 0 COMMENT '第几步',
  `step_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '步骤名称，例如：判断召回结果是否相关',
  `node_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'LangGraph节点名',
  `tool_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '本步调用的工具编码',
  `request_params` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '入参JSON',
  `response_result` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '返回JSON',
  `step_status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '运行中' COMMENT '步骤状态：运行中、已完成、运行失败',
  `error_message` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '失败原因',
  `start_time` datetime NULL DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime NULL DEFAULT NULL COMMENT '结束时间',
  `cost_millis` bigint NULL DEFAULT NULL COMMENT '耗时（毫秒）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_agent_step_run`(`run_id` ASC, `step_index` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1186 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'Agent执行步骤表' ROW_FORMAT = Dynamic;

