-- ----------------------------
-- Table structure for chunk_strategy
-- ----------------------------
DROP TABLE IF EXISTS `chunk_strategy`;
CREATE TABLE `chunk_strategy`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '策略ID',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '策略名称',
  `strategy_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '策略类型：递归分块、父子分块',
  `chunk_size` int NOT NULL DEFAULT 500 COMMENT '片段长度（字符）',
  `chunk_overlap` int NOT NULL DEFAULT 50 COMMENT '相邻片段重叠字符数',
  `parent_chunk_size` int NULL DEFAULT NULL COMMENT '父块长度，仅父子分块使用',
  `separators` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分隔符清单，逗号分隔',
  `is_default` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '否' COMMENT '是否默认策略：是、否',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注说明',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 36 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '切分策略表' ROW_FORMAT = Dynamic;

