-- ----------------------------
-- Table structure for eval_case
-- ----------------------------
DROP TABLE IF EXISTS `eval_case`;
CREATE TABLE `eval_case`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '用例ID',
  `dataset_id` int NOT NULL COMMENT '所属评测集ID',
  `question` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '问题',
  `ground_truth` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '标准答案',
  `reference_chunk_ids` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '标准答案对应的片段ID，逗号分隔，用于算检索指标',
  `source` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '手工录入' COMMENT '来源：手工录入、文档生成、反馈沉淀',
  `enabled` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '是' COMMENT '是否参与评测：是、否',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注说明',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_eval_case_dataset`(`dataset_id` ASC, `enabled` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 192 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '评测用例表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of eval_case
