-- ----------------------------
-- Table structure for eval_case_result
-- ----------------------------
DROP TABLE IF EXISTS `eval_case_result`;
CREATE TABLE `eval_case_result`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '结果ID',
  `task_id` int NOT NULL COMMENT '所属评测任务ID',
  `case_id` int NOT NULL COMMENT '评测用例ID',
  `answer` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '本次生成的答案',
  `retrieved_chunk_ids` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '本次召回的片段ID，逗号分隔',
  `faithfulness` decimal(5, 4) NULL DEFAULT NULL COMMENT '忠实度：答案是否有出处支撑',
  `answer_relevancy` decimal(5, 4) NULL DEFAULT NULL COMMENT '答案相关性：有没有跑题',
  `context_precision` decimal(5, 4) NULL DEFAULT NULL COMMENT '上下文精度：有用的片段是否排在前面',
  `context_recall` decimal(5, 4) NULL DEFAULT NULL COMMENT '上下文召回：该召回的信息是否召回了',
  `avg_score` decimal(5, 4) NULL DEFAULT NULL COMMENT '四项指标平均分',
  `error_message` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '失败原因',
  `cost_millis` bigint NULL DEFAULT NULL COMMENT '耗时（毫秒）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_eval_case_result_task`(`task_id` ASC, `case_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 36 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '评测用例结果表' ROW_FORMAT = Dynamic;

