  `id` int NOT NULL AUTO_INCREMENT COMMENT '知识库ID',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '知识库名称',
  `description` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '知识库描述',
  `embedding_model_id` int NULL DEFAULT NULL COMMENT '绑定的向量模型配置ID',
  `chunk_strategy_id` int NULL DEFAULT NULL COMMENT '默认切分策略ID',
  `document_count` int NOT NULL DEFAULT 0 COMMENT '文档数量',
  `chunk_count` int NOT NULL DEFAULT 0 COMMENT '片段数量',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '正常' COMMENT '状态：正常、停用',
  `create_user_id` int NULL DEFAULT NULL COMMENT '创建人ID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_knowledge_base_user`(`create_user_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1659 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '知识库表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of knowledge_base
-- ----------------------------

-- ----------------------------
-- Table structure for knowledge_chunk
-- ----------------------------
DROP TABLE IF EXISTS `knowledge_chunk`;
CREATE TABLE `knowledge_chunk`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '片段ID',
  `kb_id` int NOT NULL COMMENT '所属知识库ID',
  `document_id` int NOT NULL COMMENT '所属文档ID',
  `parent_id` int NULL DEFAULT NULL COMMENT '父片段ID，父子分块时子块指向父块',
  `chunk_index` int NOT NULL DEFAULT 0 COMMENT '在文档内的顺序号',
  `chunk_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '普通块' COMMENT '片段类型：普通块、父块、子块',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '片段内容',
  `char_count` int NOT NULL DEFAULT 0 COMMENT '片段字符数',
  `page_no` int NULL DEFAULT NULL COMMENT '来源页码',
  `title_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '标题层级路径，用于展示来源位置',
  `extra_meta` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '扩展元数据JSON，用于元数据过滤',
  `vector_status` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '待向量化' COMMENT '向量化状态：待向量化、已完成、失败',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_knowledge_chunk_doc`(`document_id` ASC, `chunk_index` ASC) USING BTREE,
  INDEX `idx_knowledge_chunk_kb`(`kb_id` ASC, `vector_status` ASC) USING BTREE,
  INDEX `idx_knowledge_chunk_parent`(`parent_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1424 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '知识片段表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of knowledge_chunk
-- ----------------------------

-- ----------------------------
-- Table structure for knowledge_document
-- ----------------------------
DROP TABLE IF EXISTS `knowledge_document`;
CREATE TABLE `knowledge_document`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '文档ID',
  `kb_id` int NOT NULL COMMENT '所属知识库ID',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '文档名称',
  `file_name` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '磁盘文件名',
  `file_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '文件访问地址',
  `file_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '文件类型：PDF、WORD、EXCEL、MARKDOWN、TXT',
  `file_size` bigint NULL DEFAULT 0 COMMENT '文件大小（字节）',
  `parse_status` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '待解析' COMMENT '解析状态：待解析、解析中、解析完成、解析失败',
  `parse_error` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '解析失败原因',
  `parsed_text` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '解析出的纯文本，第08章按它切分片段',
  `has_table` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '否' COMMENT '是否包含表格：是、否',
  `has_ocr` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '否' COMMENT '是否走过OCR：是、否',
  `char_count` int NOT NULL DEFAULT 0 COMMENT '解析出的字符数',
  `chunk_count` int NOT NULL DEFAULT 0 COMMENT '切分出的片段数',
  `vector_status` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '待向量化' COMMENT '向量化状态：待向量化、向量化中、已完成、失败',
  `upload_user_id` int NULL DEFAULT NULL COMMENT '上传人ID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_knowledge_document_kb`(`kb_id` ASC, `parse_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1031 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '知识文档表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of knowledge_document
-- ----------------------------

-- ----------------------------
-- Table structure for message_feedback
-- ----------------------------
DROP TABLE IF EXISTS `message_feedback`;
CREATE TABLE `message_feedback`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '反馈ID',
  `message_id` int NOT NULL COMMENT '消息ID',
  `user_id` int NULL DEFAULT NULL COMMENT '反馈人ID',
  `feedback_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '反馈类型：点赞、点踩',
  `reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '反馈原因',
  `converted` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '否' COMMENT '是否已转为评测用例：是、否',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_message_feedback_msg`(`message_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 258 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '消息反馈表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of message_feedback
-- ----------------------------

-- ----------------------------
-- Table structure for message_reference
-- ----------------------------
DROP TABLE IF EXISTS `message_reference`;
CREATE TABLE `message_reference`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '引用ID',
  `message_id` int NOT NULL COMMENT '所属消息ID',
  `chunk_id` int NOT NULL COMMENT '知识片段ID',
  `document_id` int NULL DEFAULT NULL COMMENT '来源文档ID',
  `chunk_content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '片段内容快照，防止片段后续被修改导致来源对不上',
  `score` decimal(10, 6) NULL DEFAULT NULL COMMENT '相关性得分',
  `rank_no` int NULL DEFAULT NULL COMMENT '最终排序位次',
  `retrieval_source` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '召回来源：向量检索、BM25检索、RRF融合、重排',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_message_reference_msg`(`message_id` ASC, `rank_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 441 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '消息引用来源表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of message_reference
-- ----------------------------

-- ----------------------------
-- Table structure for prompt_template
-- ----------------------------
DROP TABLE IF EXISTS `prompt_template`;
CREATE TABLE `prompt_template`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '模板ID',
  `code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板编码，代码里按编码取模板',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板名称',
  `scene` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '使用场景',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板内容，用大括号占位变量',
  `variables` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '变量清单，逗号分隔',
  `enabled` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '是' COMMENT '是否启用：是、否',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注说明',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_prompt_template_code`(`code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 140 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'Prompt模板表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of prompt_template
-- ----------------------------

-- ----------------------------
-- Table structure for qa_app
-- ----------------------------
DROP TABLE IF EXISTS `qa_app`;
CREATE TABLE `qa_app`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '应用ID',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '应用名称',
  `app_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '应用编码，分享链接用',
  `description` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '应用描述',
  `avatar` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '应用头像',
  `chat_model_id` int NULL DEFAULT NULL COMMENT '对话模型配置ID',
  `retrieval_strategy_id` int NULL DEFAULT NULL COMMENT '检索策略ID',
  `prompt_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '系统Prompt模板编码',
  `agent_enabled` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '否' COMMENT '是否启用Agentic RAG：是、否',
  `max_history` int NOT NULL DEFAULT 6 COMMENT '带入模型的历史消息条数',
  `empty_answer` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '没有检索到答案时的兜底话术',
  `share_enabled` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '否' COMMENT '是否开放分享：是、否',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '正常' COMMENT '状态：正常、停用',
  `create_user_id` int NULL DEFAULT NULL COMMENT '创建人ID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_qa_app_code`(`app_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 765 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '问答应用表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of qa_app
-- ----------------------------

-- ----------------------------
-- Table structure for qa_app_kb
-- ----------------------------
DROP TABLE IF EXISTS `qa_app_kb`;
CREATE TABLE `qa_app_kb`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `app_id` int NOT NULL COMMENT '应用ID',
  `kb_id` int NOT NULL COMMENT '知识库ID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_qa_app_kb`(`app_id` ASC, `kb_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 418 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '问答应用与知识库关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of qa_app_kb
-- ----------------------------

-- ----------------------------
-- Table structure for retrieval_debug_record
-- ----------------------------
DROP TABLE IF EXISTS `retrieval_debug_record`;
CREATE TABLE `retrieval_debug_record`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '调试记录ID',
  `kb_id` int NOT NULL COMMENT '知识库ID',
  `query` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '调试用的问题',
  `strategy_ids` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '参与对比的检索策略ID，逗号分隔',
  `result_snapshot` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '各策略召回结果快照JSON，含片段、得分、耗时',
  `cost_millis` bigint NULL DEFAULT NULL COMMENT '本次对比总耗时（毫秒）',
  `create_user_id` int NULL DEFAULT NULL COMMENT '操作人ID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_retrieval_debug_kb`(`kb_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '召回调试记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of retrieval_debug_record
-- ----------------------------

-- ----------------------------
-- Table structure for retrieval_strategy
-- ----------------------------
DROP TABLE IF EXISTS `retrieval_strategy`;
CREATE TABLE `retrieval_strategy`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '策略ID',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '策略名称',
  `vector_enabled` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '是' COMMENT '是否启用向量检索：是、否',
  `vector_top_k` int NOT NULL DEFAULT 5 COMMENT '向量检索召回条数',
  `bm25_enabled` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '否' COMMENT '是否启用BM25关键词检索：是、否',
  `bm25_top_k` int NOT NULL DEFAULT 5 COMMENT 'BM25召回条数',
  `rrf_k` int NOT NULL DEFAULT 60 COMMENT 'RRF融合常数，越小越偏向排名靠前的结果',
  `rerank_enabled` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '否' COMMENT '是否启用重排：是、否',
  `rerank_model_id` int NULL DEFAULT NULL COMMENT '重排模型配置ID',
  `rerank_top_n` int NOT NULL DEFAULT 3 COMMENT '重排后保留条数',
  `query_rewrite_enabled` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '否' COMMENT '是否启用查询改写：是、否',
  `rewrite_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '改写方式：多查询扩展、指代消解、HyDE',
  `multi_query_count` int NOT NULL DEFAULT 3 COMMENT '多查询扩展生成的查询条数',
  `parent_recall_enabled` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '否' COMMENT '命中子块是否回填父块：是、否',
  `vector_score_threshold` decimal(5, 3) NULL DEFAULT NULL COMMENT '向量余弦相似度阈值，仅在最终分数是余弦相似度时生效',
  `rerank_score_threshold` decimal(5, 3) NULL DEFAULT NULL COMMENT '重排相关分阈值，仅在最终分数是重排相关分时生效',
  `metadata_filter` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '元数据过滤条件JSON',
  `is_default` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '否' COMMENT '是否默认策略：是、否',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注说明',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 89 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '检索策略表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of retrieval_strategy
-- ----------------------------

-- ----------------------------
-- Table structure for tool_call_log
-- ----------------------------
DROP TABLE IF EXISTS `tool_call_log`;
CREATE TABLE `tool_call_log`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '日志ID',
  `run_id` int NULL DEFAULT NULL COMMENT '所属运行ID',
  `step_id` int NULL DEFAULT NULL COMMENT '所属步骤ID',
  `tool_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '工具编码',
  `tool_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '工具名称',
  `request_params` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '入参JSON',
  `response_result` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '返回JSON',
  `call_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '成功' COMMENT '调用结果：成功、失败',
  `error_message` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '失败原因',
  `cost_millis` bigint NULL DEFAULT NULL COMMENT '耗时（毫秒）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_tool_call_log_run`(`run_id` ASC) USING BTREE,
  INDEX `idx_tool_call_log_tool`(`tool_code` ASC, `call_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 90 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '工具调用日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of tool_call_log
-- ----------------------------

-- ----------------------------
-- Table structure for user
-- ----------------------------
DROP TABLE IF EXISTS `user`;
CREATE TABLE `user`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '用户ID',
  `username` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '登录账号',
  `password` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '登录密码',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '姓名',
  `avatar` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '头像地址',
  `role` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'USER' COMMENT '角色：ADMIN管理员、USER普通用户',
  `phone` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '联系电话',
  `email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '电子邮箱',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'NORMAL' COMMENT '账号状态：NORMAL正常、DISABLED停用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_username`(`username` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '用户表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of user
-- ----------------------------

SET FOREIGN_KEY_CHECKS = 1;
